; ---------------------------------------------------------------------------
; Unlike the games before this doesn't crash/freeze the 68000, instead it falls through into the EntryPoint which causes the game to soft-restart.

ErrorTrap:
;		nop
;		nop
;		nop
; ---------------------------------------------------------------------------

EntryPoint:
		lea	(System_stack).w,sp
		tst.l	(HW_Port_1_Control-1).l
		bne.s	+
		tst.w	(HW_Expansion_Control-1).l

+
		bne.s	Init_SkipPowerOn	; in case of a soft reset
		lea	SetupValues(pc),a5
		movem.w	(a5)+,d5-d7
		movem.l	(a5)+,a0-a4
		move.b	HW_Version-Z80_bus_request(a1),d0	; get hardware version
		andi.b	#$F,d0
		beq.s	SkipSecurity	; branch if hardware is older than Genesis III
		move.l	#'SEGA',Security_addr-Z80_bus_request(a1)	; satisfy the TMSS

SkipSecurity:
		move.w	(a4),d0	; check if VDP works
		moveq	#0,d0
		movea.l	d0,a6
		move.l	a6,usp	; set usp to $0
		moveq	#VDPInitValues_End-VDPInitValues-1,d1

Init_VDPRegs:
		move.b	(a5)+,d5
		move.w	d5,(a4)
		add.w	d7,d5
		dbf	d1,Init_VDPRegs	; set all 24 registers

		move.l	(a5)+,(a4)	; set VRAM write mode
		move.w	d0,(a3)	; clear the screen
		move.w	d7,(a1)	; stop the Z80
		move.w	d7,(a2)	; reset the Z80

WaitForZ80:
		btst	d0,(a1)	; has the Z80 stopped?
		bne.s	WaitForZ80	; if not, branch
		moveq	#Z80StartupCodeEnd-Z80StartupCodeBegin-1,d2

Init_SoundRAM:
		move.b	(a5)+,(a0)+
		dbf	d2,Init_SoundRAM
		move.w	d0,(a2)
		move.w	d0,(a1)	; start the Z80
		move.w	d7,(a2)	; reset the Z80

Init_ClearRAM:
		move.l	d0,-(a6)		; Clear normal RAM
		dbf	d6,Init_ClearRAM
		move.l	(a5)+,(a4)	; set VDP display mode and increment
		move.l	(a5)+,(a4)	; set VDP to CRAM write
		moveq	#bytesToLcnt($80),d3

Init_ClearCRAM:
		move.l	d0,(a3)			; Clear CRAM
		dbf	d3,Init_ClearCRAM
		move.l	(a5)+,(a4)
		moveq	#bytesToLcnt($50),d4

Init_ClearVSRAM:
		move.l	d0,(a3)			; Clear VSRAM
		dbf	d4,Init_ClearVSRAM
		moveq	#PSGInitValues_End-PSGInitValues-1,d5

Init_InputPSG:
		move.b	(a5)+,PSG_input-VDP_data_port(a3)	; reset the PSG
		dbf	d5,Init_InputPSG
		move.w	d0,(a2)
		movem.l	(a6),d0-a6	; clear all registers
		move	#$2700,sr	; set the sr

Init_SkipPowerOn:
		bra.s	Test_LockOn
; ---------------------------------------------------------------------------
SetupValues:
		dc.w $8000,bytesToLcnt($10000),$100
		dc.l Z80_RAM
		dc.l Z80_bus_request
		dc.l Z80_reset
		dc.l VDP_data_port, VDP_control_port

; values for VDP registers
VDPInitValues:
		dc.b VDPReg0_DisableHInt		; Command $8004 - HInt off, Enable HV counter read
		dc.b VDPReg1_DisableVIntAndDisplay	; Command $8114 - Display off, VInt off, DMA on, PAL off
		dc.b (VRAM_Plane_A_Name_Table>>10)	; Command $8230 - Scroll A Address $C000
		dc.b (VRAM_HScroll_Table>>10)		; Command $833C - Window Address $F000
		dc.b (VRAM_Plane_B_Name_Table>>13)	; Command $8407 - Scroll B Address $E000
		dc.b ($D800>>9)				; Command $856C - Sprite Table Address $D800
		dc.b 0					; Command $8600 - Null
		dc.b (palette_line_0>>9)|$00		; Command $8700 - Background color Pal 0 Color 0
		dc.b 0					; Command $8800 - Null
		dc.b 0					; Command $8900 - Null
		dc.b $FF				; Command $8AFF - Hint timing $FF scanlines
		dc.b VDPReg2_FullScroll			; Command $8B00 - Ext Int off, VScroll full, HScroll full
		dc.b VDPReg3_DisableSH			; Command $8C81 - 40 cell mode, shadow/highlight off, no interlace
		dc.b ($DC00>>10)			; Command $8D37 - HScroll Table Address $DC00
		dc.b 0					; Command $8E00 - Null
		dc.b $01				; Command $8F01 - VDP auto increment 1 byte
		dc.b PlaneSize_512x256			; Command $9001 - 64x32 cell scroll size
		dc.b $00				; Command $9100 - Window H left side, Base Point 0
		dc.b Window_Disable			; Command $9200 - Window V upside, Base Point 0
		dc.b $FF				; Command $93FF - DMA Length Counter $FFFF
		dc.b $FF				; Command $94FF - See above
		dc.b $00				; Command $9500 - DMA Source Address $0
		dc.b $00				; Command $9600 - See above
		dc.b $80				; Command $9700 - See above + VRAM fill mode
VDPInitValues_End:
		dc.l	vdpComm($0000,VRAM,DMA)	; value for VRAM write mode

; Z80 instructions (not the sound driver; that gets loaded later)
Z80StartupCodeBegin:
		save
		cpu Z80			; start assembling Z80 code
		phase 0			; pretend we're at address 0

		xor	a		; clear a to 0
		ld	bc,((Z80_RAM_end-Z80_RAM)-zStartupCodeEndLoc)-1	; prepare to loop this many times
		ld	de,zStartupCodeEndLoc+1	; initial destination address
		ld	hl,zStartupCodeEndLoc	; initial source address
		ld	sp,hl		; set the address the stack starts at
		ld	(hl),a		; set first byte of the stack to 0
		ldir			; loop to fill the stack (entire remaining available Z80 RAM) with 0
		pop	ix		; clear ix
		pop	iy		; clear iy
		ld	i,a		; clear i
		ld	r,a		; clear r
		pop	de		; clear de
		pop	hl		; clear hl
		pop	af		; clear af
		ex	af,af'		; swap af with af'
		exx			; swap bc/de/hl with their shadow registers too
		pop	bc		; clear bc
		pop	de		; clear de
		pop	hl		; clear hl
		pop	af		; clear af
		ld	sp,hl		; clear sp
		di			; clear iff1 (for interrupt handler)
		im	1		; interrupt handling mode = 1
		ld	(hl),0E9h	; replace the first instruction with a jump to itself
		jp	(hl)		; jump to the first instruction (to stay there forever)
zStartupCodeEndLoc:
		dephase			; stop pretending
		restore
		padding off	; unfortunately our flags got reset so we have to set them again...
Z80StartupCodeEnd:

		dc.w $8104			; value for VDP display mode
		dc.w $8F02			; value for VDP increment
		dc.l vdpComm($0000,CRAM,WRITE)	; value for CRAM write mode
		dc.l vdpComm($0000,VSRAM,WRITE)	; value for VSRAM write mode
PSGInitValues:
		dc.b $9F,$BF,$DF,$FF		; values for PSG channel volumes
PSGInitValues_End:
; ---------------------------------------------------------------------------

Test_LockOn:
		tst.w	(VDP_control_port).l
		move.w	#$4EF9,(V_int_jump).w	; machine code for jmp
		move.l	#VInt,(V_int_addr).w
		move.w	#$4EF9,(H_int_jump).w
		move.l	#HInt,(H_int_addr).w

-
		move.w	(VDP_control_port).l,d1
		btst	#1,d1
		bne.s	-	; wait till a DMA is completed
		lea	(RAM_start&$FFFFFF).l,a6
		moveq	#0,d7
		move.w	#bytesToLcnt(CrossResetRAM-RAM_start),d6

-
		move.l	d7,(a6)+
		dbf	d6,-
		; Liliam: removed S&K lock-on code

Test_Checksum:
		btst	#6,(HW_Expansion_Control).l
		beq.s	+
		cmpi.l	#Ref_Checksum_String,(Checksum_string).w
		beq.w	Test_Checksum_Done

+
		; Liliam: removed dummied-out checksum code
		lea	(CrossResetRAM).w,a6
		moveq	#0,d7
		move.w	#bytesToLcnt(CrossResetRAM_End-CrossResetRAM),d6

-
		move.l	d7,(a6)+
		dbf	d6,-	; clear RAM from $FFFE00 to $FFFFEF
		move.b	(HW_Version).l,d6
		andi.b	#$C0,d6
		move.b	d6,(Graphics_flags).w
		move.l	#Ref_Checksum_String,(Checksum_string).w

Test_Checksum_Done:
		; Liliam: removed S&K alone mode
		bsr.w	DetectPAL
		bsr.w	Init_VDP
		bsr.w	SndDrvInit
		bsr.w	Init_Controllers
		jsr	(SRAM_Load).l
		move.b	#GameMode_SegaScreen,(Game_mode).w

GameLoop:
		move.b	(Game_mode).w,d0
		andi.w	#$7C,d0
		movea.l	GameModes(pc,d0.w),a0
		jsr	(a0)
		bra.s	GameLoop
; ---------------------------------------------------------------------------
GameModes:

gmptr:		macro gamemode,{INTLABEL}
__LABEL__:	label	*-GameModes
		dc.l	gamemode
		endm

GameMode_SegaScreen:		gmptr Sega_Screen			;   0
GameMode_TitleScreen:		gmptr Title_Screen			;   4
GameMode_Demo:			gmptr LevelDemo				;   8
GameMode_Level:			gmptr Level				;  $C
GameMode_Museum:		gmptr Museum				; $10	; Liliam: title screen - expand options
GameMode_Continue:		gmptr ContinueScreen			; $14
GameMode_UnlockScreen:		gmptr UnlockScreen			; $18	;
GameMode_EncoreMode:		gmptr EncoreMode			; $1C	;
GameMode_S3Credits:		gmptr S3Credits				; $20
GameMode_LevelSelect:		gmptr LevelSelect			; $24
GameMode_BlueSpheres:		gmptr BlueSpheres			; $28	;
GameMode_BlueSpheresTitle:	gmptr BlueSpheresTitle			; $2C
GameMode_BlueSpheresResults:	gmptr BlueSpheresResults		; $30
GameMode_SpecialStage:		gmptr SpecialStage			; $34
GameMode_Competition:		gmptr Competition_Menu			; $38
GameMode_CompPlayerSelect:	gmptr Competition_PlayerSelect		; $3C
GameMode_CompLevelSelect:	gmptr Competition_LevelSelect		; $40
GameMode_CompResults:		gmptr Competition_Results		; $44
GameMode_SpecialStageResults:	gmptr SpecialStage_Results		; $48
GameMode_SaveScreen:		gmptr SaveScreen			; $4C
GameMode_TimeAttackRecords:	gmptr TimeAttack_Records		; $50
GameMode_Options:		gmptr OptionsScreen			; $54	;
GameMode_EraseData:		gmptr EraseDataScreen			; $58	;
; ---------------------------------------------------------------------------
		; Liliam: removed dead code

; =============== S U B R O U T I N E =======================================


DetectPAL:
		lea	(VDP_control_port).l,a5
		move.w	#VDP_Option1|VDPReg1_EnableDisplay,(a5)		; Command $8174 - Display on, VInt on, DMA on, PAL off
		moveq	#0,d0

.waitForVBlankStart:
		move.w	(a5),d1
		andi.w	#8,d1
		beq.s	.waitForVBlankStart

.waitForVBlankEnd:
		move.w	(a5),d1
		andi.w	#8,d1
		bne.s	.waitForVBlankEnd	; Wait for VBlank to run once

.waitForNextVBlank:
		addq.w	#1,d0
		move.w	(a5),d1
		andi.w	#8,d1
		beq.s	.waitForNextVBlank
		move.w	d0,(V_blank_cycles).w	; Count cycles between VBlanks (likely to detect PAL systems and/or for other timing mechanisms
		rts
; End of function DetectPAL

; ---------------------------------------------------------------------------
; Vertical interrupt handler
; ---------------------------------------------------------------------------

VInt:
		nop
		movem.l	d0-a6,-(sp)
		tst.b	(V_int_routine).w
		beq.w	VInt_0_Main

-
		move.w	(VDP_control_port).l,d0
		andi.w	#8,d0
		beq.s	-	; wait until vertical blanking is taking place

		move.l	#vdpComm($0000,VSRAM,WRITE),(VDP_control_port).l
		move.l	(V_scroll_value).w,(VDP_data_port).l
		btst	#6,(Graphics_flags).w
		beq.s	+	; branch if it's not a PAL system
		move.w	#$700,d0
		dbf	d0,*	; otherwise, waste a bit of time here

+
		move.b	(V_int_routine).w,d0
		move.b	#VInt_ID_0,(V_int_routine).w
		move.w	#1,(H_int_flag).w		; Allow H Interrupt code to run
		andi.w	#$3E,d0
		move.w	VInt_Table(pc,d0.w),d0
		jsr	VInt_Table(pc,d0.w)

VInt_Done:
		addq.l	#1,(V_int_run_count).w
		move.w	(H_int_counter_command).w,(H_int_prev_command).w	; Liliam: bugfix - water transition lag (credit: Tiddles)
		movem.l	(sp)+,d0-a6
		rte
; ---------------------------------------------------------------------------
VInt_Table:

vintptr:	macro vintroutine,{INTLABEL}
__LABEL__:	label	*-VInt_Table
		dc.w	vintroutine-VInt_Table
		endm

VInt_ID_0:	vintptr VInt_0
VInt_ID_2:	vintptr VInt_2
VInt_ID_4:	vintptr VInt_4
VInt_ID_6:	vintptr VInt_6
VInt_ID_8:	vintptr VInt_8
VInt_ID_A:	vintptr VInt_A_C
VInt_ID_C:	vintptr VInt_A_C
VInt_ID_E:	vintptr VInt_E
VInt_ID_10:	vintptr VInt_10
VInt_ID_12:	vintptr VInt_12
VInt_ID_14:	vintptr VInt_14
VInt_ID_16:	vintptr VInt_16
VInt_ID_18:	vintptr VInt_18
VInt_ID_1A:	vintptr VInt_1A
VInt_ID_1C:	vintptr VInt_1C
VInt_ID_1E:	vintptr VInt_1E
; ---------------------------------------------------------------------------

VInt_0:
		addq.w	#4,sp

VInt_0_Main:
		addq.w	#1,(Lag_frame_count).w

		; branch if a level or demo is running
		cmpi.b	#GameMode_Demo+$80,(Game_mode).w
		beq.s	VInt_0_Level
		cmpi.b	#GameMode_Level+$80,(Game_mode).w
		beq.s	VInt_0_Level
		cmpi.b	#GameMode_Demo,(Game_mode).w
		beq.s	VInt_0_Level
		cmpi.b	#GameMode_Level,(Game_mode).w
		beq.s	VInt_0_Level
		bra.s	VInt_Done	; otherwise, return from V-int
; ---------------------------------------------------------------------------

VInt_0_Level:
		tst.b	(Water_flag).w
		beq.w	VInt_0_NoWater
		move.w	(VDP_control_port).l,d0
		btst	#6,(Graphics_flags).w
		beq.s	+	; branch if it isn't a PAL system
		move.w	#$700,d0
		dbf	d0,*	; otherwise waste a bit of time here

+
		move.w	#1,(H_int_flag).w
		stopZ80
		tst.b	(Water_full_screen_flag).w
		bne.s	VInt_0_FullyUnderwater
		dma68kToVDP Normal_palette,0,Normal_palette_end-Normal_palette,CRAM
		bra.s	VInt_0_Water_Cont
; ---------------------------------------------------------------------------

VInt_0_FullyUnderwater:
		dma68kToVDP Water_palette,0,Water_palette_end-Water_palette,CRAM

VInt_0_Water_Cont:
		move.w	(H_int_counter_command).w,(a5)
		startZ80
		bra.w	VInt_Done
; ---------------------------------------------------------------------------

VInt_0_NoWater:
		move.w	(VDP_control_port).l,d0
		btst	#6,(Graphics_flags).w
		beq.s	+	; branch if it isn't a PAL system
		move.w	#$700,d0
		dbf	d0,*	; otherwise, waste a bit of time here

+
		move.w	#1,(H_int_flag).w
		move.w	(H_int_counter_command).w,(VDP_control_port).l
		stopZ80

		; In Competition Mode, we have to update the sprite table
		; even during a lag frame so that the top half of the screen
		; shows the correct sprites.
		tst.w	(Competition_mode).w
		beq.s	VInt_0_Done

		; Update V-Scroll.
		move.l	#vdpComm($0000,VSRAM,WRITE),(VDP_control_port).l
		move.l	(V_scroll_value).w,(VDP_data_port).l

		; Unlike in Sonic 2, the sprite tables are page-flipped in two-player mode.
		; This fixes a race-condition where incomplete sprite tables can be uploaded
		; to the VDP on lag frames, causing corrupted sprites to appear.

		; Upload the front buffer.
		tst.w	(Current_sprite_table_page).w
		beq.s	+
		dma68kToVDP Sprite_table,VRAM_Sprite_Table,Sprite_table_end-Sprite_table,VRAM
		bra.s	VInt_0_Done

+
		dma68kToVDP Sprite_table_alternate,VRAM_Sprite_Table,Sprite_table_alternate_end-Sprite_table_alternate,VRAM

VInt_0_Done:
		startZ80
		bra.w	VInt_Done
; ---------------------------------------------------------------------------

VInt_2:
		bsr.w	Do_ControllerPal
		tst.w	(Demo_timer).w
		beq.w	+
		subq.w	#1,(Demo_timer).w

+
		rts
; ---------------------------------------------------------------------------

VInt_14:
		move.b	(V_int_run_count+3).w,d0
		andi.w	#$F,d0
		bne.s	+	; run the following code once every 16 frames

		stopZ80
		bsr.w	Poll_Controllers
		startZ80

+
		tst.w	(Demo_timer).w
		beq.w	+
		subq.w	#1,(Demo_timer).w

+
		jmp	(Set_Kos_Bookmark).l
; ---------------------------------------------------------------------------

VInt_4:
		bsr.w	TitleAnim_FlipBuffer
		bsr.w	Do_ControllerPal
		move.w	(Ctrl_1).w,(Ctrl_1_title).w
		bsr.w	Process_Nem_Queue
		tst.w	(Demo_timer).w
		beq.w	+
		subq.w	#1,(Demo_timer).w

+
		rts
; ---------------------------------------------------------------------------

VInt_6:
		bsr.w	Do_ControllerPal
		rts
; ---------------------------------------------------------------------------

VInt_10:
		cmpi.b	#GameMode_SpecialStage,(Game_mode).w
		beq.w	VInt_1C		; If in a special stage, branch

VInt_8:
		stopZ80
		bsr.w	Poll_Controllers
		tst.b	(Hyper_Sonic_flash_timer).w
		beq.s	VInt_8_NoFlash

		; flash screen white when Hyper Sonic's double jump move is used
		subq.b	#1,(Hyper_Sonic_flash_timer).w
		lea	(VDP_data_port).l,a6
		move.l	#vdpComm($0000,CRAM,WRITE),(VDP_control_port).l
		move.w	#$EEE,d0
		move.w	#$20-1,d1

-
		move.w	d0,(a6)
		dbf	d1,-	; fill entire first and second palette lines with white
		move.w	#0,(a6)	; keep backdrop black
		move.w	#$1F-1,d1

-
