; =============== S U B R O U T I N E =======================================


SuperHyper_PalCycle:
		move.b	(Super_palette_status).w,d0	; 0 = off | 1 = fading | -1 = fading done
		beq.w	locret_37EC			; return, if player isn't super
		bmi.w	SuperHyper_PalCycle_Main	; branch, if fade-in is done
		subq.b	#1,d0
		beq.s	SuperHyper_PalCycle_FadeIn			; Liliam: animate super forms consistently
		subq.b	#1,d0						;
		bne.w	SuperHyper_PalCycle_RevertHyperTails		;
;		bne.w	SuperHyper_PalCycle_Revert			;
		bra.s	SuperHyper_PalCycle_Revert			;
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_FadeIn:
		; fade from Sonic's to Super Sonic's palette
		; run frame timer
		subq.b	#1,(Palette_timer).w
		bpl.w	locret_37EC
		move.b	#1,(Palette_timer).w

;		cmpi.w	#2,(Player_mode).w				; Liliam: animate super forms consistently
;		blo.s	loc_3792					;
;		move.b	#-1,(Super_palette_status).w			;
;		move.w	#0,(Palette_frame).w				;
;		move.b	#0,(Palette_frame_Tails).w			;
;		move.b	#0,(Player_1+object_control).w			;
;		rts							;

;loc_3792:
		; increment palette frame and update Sonic's palette
		lea	(PalCycle_SuperSonic).l,a0
		move.w	(Palette_frame).w,d0
		addq.w	#6,(Palette_frame).w
		cmpi.w	#$24,(Palette_frame).w
		blo.s	SuperHyper_PalCycle_FadeInCheckHyper
		move.b	#-1,(Super_palette_status).w
		move.b	#0,(Player_1+object_control).w
		move.w	#0,(Palette_frame).w				;
		move.w	#0,(Palette_frame_Tails).w			;

SuperHyper_PalCycle_FadeInCheckHyper:
		tst.b	(Player_1+character_id).w			;
		beq.s	SuperHyper_PalCycle_ApplyFadeIn			;
		tst.b	(Super_Tails_flag).w				;
		bpl.s	locret_37EC					;

SuperHyper_PalCycle_ApplyFadeIn:
		lea	(Normal_palette+$04).w,a1
		move.l	(a0,d0.w),(a1)+	; Write first two palette entries
		move.w	4(a0,d0.w),(a1)	; Write last palette entry

		tst.b	(Water_flag).w
		beq.s	locret_37EC
		lea	(PalCycle_SuperSonic_Water).l,a0
;		tst.b	(Current_zone).w				;
;		beq.s	loc_37E0					;
;		cmpi.b	#5,(Current_zone).w				;
;		beq.s	loc_37E0					;
;		lea	(PalCycle_SuperSonic_Water2).l,a0		;

;loc_37E0:
		lea	(Water_palette+$04).w,a1
		move.l	(a0,d0.w),(a1)+	; Write first two palette entries
		move.w	4(a0,d0.w),(a1)	; Write last palette entry

locret_37EC:
		rts
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_Revert:
;		cmpi.w	#2,(Player_mode).w				; Liliam: animate super forms consistently
;		bhs.s	SuperHyper_PalCycle_RevertTails			;

		; run frame timer
		subq.b	#1,(Palette_timer).w
		bpl.s	locret_37EC
		move.b	#3,(Palette_timer).w

		lea	(Normal_palette+$4).w,a1			;
		move.w	(Player_mode).w,d0				;
		add.w	d0,d0						;
		move.w	SuperHyper_PalCycle_Revert_Index(pc,d0.w),d0	;
		jmp	SuperHyper_PalCycle_Revert_Index(pc,d0.w)	;
; ---------------------------------------------------------------------------
SuperHyper_PalCycle_Revert_Index:					; Liliam: animate super forms consistently
		dc.w SuperHyper_PalCycle_RevertSonic-SuperHyper_PalCycle_Revert_Index
		dc.w SuperHyper_PalCycle_RevertSonic-SuperHyper_PalCycle_Revert_Index
		dc.w SuperHyper_PalCycle_RevertTails-SuperHyper_PalCycle_Revert_Index
		dc.w SuperHyper_PalCycle_RevertKnuckles-SuperHyper_PalCycle_Revert_Index
		dc.w SuperHyper_PalCycle_RevertAmy-SuperHyper_PalCycle_Revert_Index
		dc.w SuperHyper_PalCycle_RevertMighty-SuperHyper_PalCycle_Revert_Index
		dc.w SuperHyper_PalCycle_RevertRay-SuperHyper_PalCycle_Revert_Index
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_RevertKnuckles:					; Liliam: animate super forms consistently
		lea	(PalCycle_SuperKnucklesRevert).l,a0
		lea	(PalCycle_SuperKnucklesRevert_Water).l,a2
		bra.s	SuperHyper_PalCycle_ApplyRevert
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_RevertMighty:					; Liliam: animate super forms consistently
		lea	(Normal_palette+$A).w,a1
		bsr.s	SuperHyper_PalCycle_RevertKnuckles
		subq.b	#4,d0
		andi.b	#$1F,d0
		tst.b	(Super_palette_status).w
		bne.s	.doExtraColor
		moveq	#0,d0
		lea	(Pal_Mighty+$A).l,a0
		lea	(Normal_palette+$A).w,a1
		lea	(Pal_WaterKnux+$C).l,a2
		bsr.w	SuperHyper_PalCycle_Apply
		moveq	#$18,d0

	.doExtraColor:
		lea	(PalCycle_SuperMighty).l,a0
		move.w	(a0,d0.w),(Normal_palette+$14).w
		tst.b	(Water_flag).w
		beq.s	locret_37EC
		move.w	PalCycle_SuperMighty_Water-PalCycle_SuperMighty(a0,d0.w),(Water_palette+$14).w
		rts
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_RevertRay:						; Liliam: animate super forms consistently
		moveq	#0,d0
		move.w	(Palette_frame).w,d1
		subq.w	#6,(Palette_frame).w
		bhs.s	loc_384A
		move.w	d0,(Palette_frame).w
		move.w	d0,(Palette_frame_Tails).w
		move.b	d0,(Super_palette_status).w
		move.l	(Pal_Ray+$10).l,(Normal_palette+$10).w
		rts
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_RevertSonic:
		; decrement palette frame and update Sonic's palette
		lea	(PalCycle_SuperSonic).l,a0
		lea	(PalCycle_SuperSonic_Water).l,a2		; Liliam: animate super forms consistently

SuperHyper_PalCycle_ApplyRevert:
		move.w	(Palette_frame).w,d0
		subq.w	#6,(Palette_frame).w
		bhs.w	SuperHyper_PalCycle_Apply			;
;		bhs.s	loc_381E					;
;		move.b	#0,(Palette_frame).w				;
		move.w	#0,(Palette_frame).w				;
		move.w	#0,(Palette_frame_Tails).w			;
		move.b	#0,(Super_palette_status).w	; 0 = off

;loc_381E:
		bra.w	SuperHyper_PalCycle_Apply			;
;		bra.s	SuperHyper_PalCycle_ApplyFadeIn			;
; ---------------------------------------------------------------------------

SuperHyper_PalCycle_RevertTails:
SuperHyper_PalCycle_RevertAmy:
		moveq	#0,d0
		move.w	(Palette_frame).w,d1				; Liliam: animate super forms consistently
		subq.w	#6,(Palette_frame).w				;
		bhs.s	loc_384A					;
