Pal_FadeFromBlack:
		move.w	#$40-1,(Palette_fade_info).w
		jsr	Pal_FillBlack(pc)
		move.w	#$15,d4

loc_3AFE:
		move.b	#VInt_ID_12,(V_int_routine).w
		bsr.w	Wait_VSync
		bsr.s	Pal_FromBlack
		bsr.w	Process_Nem_Queue_Init
		dbf	d4,loc_3AFE
		rts
; End of function Pal_FadeFromBlack


; =============== S U B R O U T I N E =======================================


Pal_FadeFromBlack_Original:					; Liliam: use legacy fade for SEGA screen
		move.w	#$40-1,(Palette_fade_info).w
		bsr.w	Pal_FillBlack_Original
		move.w	#$15,d4
		bra.s	loc_3AFE
; End of function Pal_FadeFromBlack_Original


; =============== S U B R O U T I N E =======================================


Pal_FromBlack:
		moveq	#0,d0
		lea	(Normal_palette).w,a0
		lea	(Target_palette).w,a1
		move.b	(Palette_fade_info).w,d0
		adda.w	d0,a0
		adda.w	d0,a1
		move.b	(Palette_fade_count).w,d0

loc_3B2A:
		bsr.s	Pal_AddColor
		dbf	d0,loc_3B2A
		tst.b	(Water_flag).w
		beq.s	locret_3B52
		moveq	#0,d0
		lea	(Water_palette).w,a0
		lea	(Target_water_palette).w,a1
		move.b	(Palette_fade_info).w,d0
		adda.w	d0,a0
		adda.w	d0,a1
		move.b	(Palette_fade_count).w,d0

loc_3B4C:
		bsr.s	Pal_AddColor
		dbf	d0,loc_3B4C

locret_3B52:
		rts
; End of function Pal_FromBlack


