Pal_AddColor:
		move.w	(a1)+,d2
		move.w	d2,d1					; Liliam: bugfix - add delay to match fade out
		andi.w	#$EEE,d2				;
		andi.w	#$F001,d1				;
		bne.s	Pal_AddColor_Delay			;
		move.w	(a0),d3
		cmp.w	d2,d3
		beq.s	loc_3B7C
		move.w	d3,d1
		addi.w	#$200,d1
		cmp.w	d2,d1
		bhi.s	loc_3B6A
		move.w	d1,(a0)+
		rts
; ---------------------------------------------------------------------------

loc_3B6A:
		move.w	d3,d1
		addi.w	#$20,d1
		cmp.w	d2,d1
		bhi.s	loc_3B78
		move.w	d1,(a0)+
		rts
; ---------------------------------------------------------------------------

loc_3B78:
		addq.w	#2,(a0)+
		rts
; ---------------------------------------------------------------------------

Pal_AddColor_Delay:
		rol.w	#4,d2					; Liliam: bugfix - add delay to match fade out
		rol.w	#4,d1					;
		subq.w	#1,d1					;
		or.w	d1,d2					;
		ror.w	#4,d2					;
		move.w	d2,-2(a1)				;

loc_3B7C:
		addq.w	#2,a0
		rts
; End of function Pal_AddColor

