Pal_PrepFade_LevelLoad:										; Liliam: fade in player palette if title card suppressed
		cmpi.l	#Obj_TitleCard,(Dynamic_object_RAM+(object_size*5)).w
		bne.s	.fadePlayerPal
		move.w	#$2030-1,(Palette_fade_info).w
		move.w	#$16,(Dynamic_object_RAM+(object_size*5)+objoff_2E).w
		bra.s	Pal_FillBlack
; ---------------------------------------------------------------------------

	.fadePlayerPal:
		move.w	#$40-1,(Palette_fade_info).w
		tst.b	(Encore_restart_flag).w
		bne.w	Pal_FillWhite_SpecialStage
		cmpi.w	#$1701,(Current_zone_and_act).w
		beq.w	Pal_FillWhite_SpecialStage
		cmpi.w	#$D01,(Apparent_zone_and_act).w
		beq.w	Pal_FillWhite
		tst.w	(Current_zone_and_act).w
		bne.s	Pal_FillBlack
		tst.b	(Last_star_post_hit).w
		bne.s	Pal_FillBlack
		cmpi.w	#3,(Player_mode).w
		bne.s	Pal_FillBlack_Original

; =============== S U B R O U T I N E =======================================


Pal_FillBlack:
		bsr.s	Pal_PrepFade_FromBlack			; Liliam: use legacy fade for AIZ plane intro
;		cmpi.w	#$D01,(Current_zone_and_act).w		;
;		beq.w	Pal_FillWhite				;
;		cmpi.w	#$1701,(Current_zone_and_act).w		;
;		beq.w	Pal_FillWhite				;

Pal_FillBlack_Original:
		lea	(Normal_palette).w,a0			;
		tst.b	(Water_flag).w				;
		beq.s	.init					;
		bsr.s	.init					;
		lea	(Water_palette).w,a0			;

	.init:
		moveq	#0,d0
;		lea	(Normal_palette).w,a0			;
		move.b	(Palette_fade_info).w,d0
		adda.w	d0,a0
		moveq	#0,d1
		move.b	(Palette_fade_count).w,d0

loc_3BA6:
		move.w	d1,(a0)+
;		tst.b	(Water_flag).w				;
;		beq.s	loc_3BB2				;
;		move.w	d1,(Water_palette-Normal_palette)-2(a0)	;

;loc_3BB2:
		dbf	d0,loc_3BA6
		rts
; End of function Pal_FillBlack


; =============== S U B R O U T I N E =======================================


Pal_PrepFade_FromBlack:						; Liliam: bugfix - add delay to match fade out
		lea	(Target_palette).w,a1
		tst.b	(Water_flag).w
		beq.s	.init
		bsr.s	.init
		lea	(Target_water_palette).w,a1

	.init:
		moveq	#0,d0
		move.b	(Palette_fade_info).w,d0
		adda.w	d0,a1
		move.b	(Palette_fade_count).w,d0

	.loop:
		bsr.s	Pal_PrepFade_CalcDelay
		beq.s	.skip
		subi.w	#21,d2
		beq.s	.skip
		neg.w	d2
		ror.w	#3,d1
		or.w	d2,d1
		ror.w	#4,d1
		move.w	d1,(a1)

	.skip:
		addq.w	#2,a1
		dbf	d0,.loop
		rts
; End of function Pal_PrepFade_FromBlack


; =============== S U B R O U T I N E =======================================


Pal_PrepFade_FromWhite:						; Liliam: bugfix - add delay to match fade out
		lea	(Target_palette).w,a1
		tst.b	(Water_flag).w
		beq.s	.init
		bsr.s	.init
		lea	(Target_water_palette).w,a1

	.init:
		moveq	#0,d0
		move.b	(Palette_fade_info).w,d0
		adda.w	d0,a1
		move.b	(Palette_fade_count).w,d0

	.loop:
		bsr.s	Pal_PrepFade_CalcDelay
		beq.s	.skip
		cmpi.w	#21,d2
		beq.s	.skip
		ror.w	#3,d1
		or.w	d2,d1
		ror.w	#4,d1
		move.w	d1,(a1)

	.skip:
		addq.w	#2,a1
		dbf	d0,.loop
		rts
; End of function Pal_PrepFade_FromWhite


; =============== S U B R O U T I N E =======================================


Pal_PrepFade_CalcDelay:						; Liliam: bugfix - add delay to match fade out
		move.w	(a1),d1
		andi.w	#$EEE,d1
		ror.w	#1,d1
		move.w	d1,d2
		andi.w	#$F,d2
		ror.w	#4,d1
		add.w	d1,d2
		andi.w	#$F,d2
		ror.w	#4,d1
		add.w	d1,d2
		andi.w	#$1F,d2
		rts
; End of function Pal_PrepFadeColor


; =============== S U B R O U T I N E =======================================


Animate_Palette:
		tst.w	(Palette_fade_timer).w
		bmi.s	locret_3BE2
		beq.s	loc_3BDC
		tst.b	(Encore_restart_flag).w			; Liliam: Encore mode - restart level
		bne.w	Pal_FromWhite_Encore			;
		subq.w	#1,(Palette_fade_timer).w
		cmpi.w	#$D01,(Apparent_zone_and_act).w		; Liliam: ending - allow start from Knuckles' ending
;		cmpi.w	#$D01,(Current_zone_and_act).w		;
		beq.w	Pal_FromWhite
		cmpi.w	#$1701,(Current_zone_and_act).w
		beq.w	Pal_FromWhite_SpecialStage		; Liliam: ported from S1 - Naka fade for special stage
;		beq.w	Pal_FromWhite				;
		bra.w	Pal_FromBlack
; ---------------------------------------------------------------------------

loc_3BDC:
		jmp	(AnPal_Load).l
; ---------------------------------------------------------------------------

locret_3BE2:
		rts
; End of function Animate_Palette


