		move.w	#4*60,(Demo_timer).w
		enableDisplay				; Turn the display on

		bsr.w	Pal_FadeFromBlack_Original		; Liliam: use legacy fade for SEGA screen
;		bsr.w	Pal_FadeFromBlack			;
		moveq	#signextendB(cmd_SEGA),d0
		bsr.w	Play_Music
		lea	(ArtKos_S3TitleSonic8).l,a1			; Liliam: title anim - decompress art during SEGA sound
		lea	(RAM_start).l,a2				;
		bsr.w	Queue_Kos					;
		bsr.w	Process_Kos_Queue				;
		move.w	#(3*60)-10,(Demo_timer).w			;
;		move.w	#3*60,(Demo_timer).w				;

Wait_SegaS3K:
		move.b	#VInt_ID_14,(V_int_routine).w
		bsr.w	Wait_VSync				; Wait for SEGA sound
		move.b	(Ctrl_1_pressed).w,d0
		andi.b	#button_start_mask,d0
		bne.w	loc_3FE4				; If start was pressed, skip ahead
		tst.w	(Demo_timer).w
		bne.s	Wait_SegaS3K

loc_3FE4:
		moveq	#signextendB(cmd_StopSEGA),d0
		bsr.w	Play_Music				; Stop SEGA sound
		lea	(Pal_Title).l,a1

loc_3FF0:
;		move.b	#VInt_ID_2,(V_int_routine).w	; Liliam: bugfix - don't stop fade prematurely
;		bsr.w	Wait_VSync			;
		lea	(Normal_palette).w,a2
		move.l	(a1)+,(a2)+
		move.l	(a1)+,(a2)+
		move.l	(a1)+,(a2)+
		move.w	(a1)+,(a2)+
		move.b	#VInt_ID_2,(V_int_routine).w	; Liliam: bugfix - don't stop fade prematurely
		bsr.w	Wait_VSync			;
		tst.w	-$E(a1)					; Wait for BG color to turn to black
		bne.s	loc_3FF0
		clr.w	(Ending_scroll_delay).w
		clr.w	(_unkF662).w
		move.b	#-1,(Title_anim_buffer).w
		move.b	#0,(Title_anim_delay).w
		move.w	#1,(Title_anim_frame).w		; Set initial variables for Sonic animation page flipping
		moveq	#1,d0
		bsr.w	TitleSonic_LoadFrame
		move.w	#VDP_Plane_B|(VRAM_Plane_A_Name_Table>>13),(VDP_control_port).l	; Liliam: bugfix - set correct palette for first frame

		move.w	#15*60,(Demo_timer).w		; Set to wait 15 seconds (900 frames in NTSC)
		btst	#6,(Graphics_flags).w
		beq.s	loc_4040
		move.w	#15*50,(Demo_timer).w		; Set to wait 15 seconds (750 frames in PAL)

loc_4040:
;		lea	(ArtKos_S3TitleSonic8).l,a1	; Liliam: moved to loc_3F9E - decompress art during SEGA sound
;		lea	(RAM_start).l,a2		;
;		jsr	(Queue_Kos).l			;
		tst.w	(Title_anim_buffer).w				; Liliam: title anim - delay music
		bne.s	Wait_TitleS3K					;
		moveq	#signextendB(mus_TitleScreen),d0
		bsr.w	Play_Music				; Start playing the title screen music

Wait_TitleS3K:
		move.b	#VInt_ID_4,(V_int_routine).w
;		jsr	(Process_Kos_Queue).l		; Liliam: moved to loc_3F9E - decompress art during SEGA sound
		bsr.w	Wait_VSync
		bsr.w	Iterate_TitleSonicFrame
		jsr	(Process_Sprites).l
		jsr	(Render_Sprites).l
		bsr.w	Process_Nem_Queue_Init
		cmpi.w	#2,(Title_anim_frame).w				; Liliam: title anim - delay music
		beq.s	loc_4040					;
		move.b	(Ctrl_1_pressed).w,d0
		andi.b	#button_start_mask,d0
		bne.w	loc_4090			; If start was pressed, skip straight to title
		cmpi.w	#$C,(Title_anim_frame).w
		blo.s	Wait_TitleS3K		; If last frame was reached, don't repeat

loc_4090:
		move.w	#$C,(Title_anim_frame).w
		lea	(Normal_palette).w,a1
		moveq	#bytesToWcnt(Normal_palette_end-Normal_palette),d1

loc_409C:
		move.w	#$EEE,(a1)+
		dbf	d1,loc_409C				; Flash palette white
		move.b	#3,(Title_anim_delay).w
		move.b	#VInt_ID_4,(V_int_routine).w
		bsr.w	Wait_VSync
		lea	(ArtKos_S3TitleSonicD).l,a0	;S3DATA
		lea	(RAM_start).l,a1
		bsr.w	Kos_Decomp
		move.w	a1,d3
		lsr.w	#1,d3
		move.l	#RAM_start,d1
		move.w	#tiles_to_bytes($000),d2
		andi.l	#$FFFFFF,d1
		jsr	(Add_To_DMA_Queue).l		; Load Sonic art frame 14
		lea	(Level_layout_header).w,a1
		lea	(MapEni_S3TitleSonicD).l,a0
		move.w	#make_art_tile($000,0,1),d0
		bsr.w	Eni_Decomp
		lea	(Level_layout_header).w,a1
		move.l	#vdpComm(VRAM_Plane_A_Name_Table,VRAM,WRITE),d0
		moveq	#40-1,d1
		moveq	#28-1,d2
		jsr	(Plane_Map_To_VRAM).l		; Load Sonic mapping frame 14 to $C000 VRAM
		lea	(Level_layout_header).w,a1
		lea	(MapEni_S3TitleBg).l,a0
		move.w	#make_art_tile($000,2,0),d0
		bsr.w	Eni_Decomp
		lea	(Level_layout_header).w,a1
		move.l	#vdpComm(VRAM_Plane_B_Name_Table,VRAM,WRITE),d0
		moveq	#40-1,d1
		moveq	#28-1,d2
		jsr	(Plane_Map_To_VRAM).l		; Load S3K Title BG to $E000 VRAM
		move.b	#VInt_ID_4,(V_int_routine).w
		bsr.w	Wait_VSync
		lea	(Pal_TitleSonicD).l,a0		; Title palette
		lea	(Target_palette).w,a1
		moveq	#bytesToLcnt(Target_palette_end-Target_palette),d0

loc_4140:
		move.l	(a0)+,(a1)+
		dbf	d0,loc_4140
		move.l	#vdpComm(tiles_to_bytes(ArtTile_Title_Banner),VRAM,WRITE),(VDP_control_port).l		; to VRAM $A000
		lea	(ArtNem_Title_S3Banner).l,a0
		bsr.w	Nem_Decomp
		move.l	#vdpComm(tiles_to_bytes(ArtTile_Title_Menu),VRAM,WRITE),(VDP_control_port).l		; to VRAM $D000
		lea	(ArtNem_TitleScreenText).l,a0
		bsr.w	Nem_Decomp
		move.l	#vdpComm(tiles_to_bytes(ArtTile_Title_Misc),VRAM,WRITE),(VDP_control_port).l		; to VRAM $8000
		lea	(ArtNem_Title_SonicSprites).l,a0
		bsr.w	Nem_Decomp
;		move.l	#vdpComm(tiles_to_bytes(ArtTile_Title_ANDKnuckles),VRAM,WRITE),(VDP_control_port).l	; Liliam: title screen - add 'Unlocked' branding
;		lea	(ArtNem_Title_ANDKnuckles).l,a0								;
;		bsr.w	Nem_Decomp										;
		move.l	#Obj_TitleBanner,(Player_1).w
		move.l	#Obj_TitleSelection,(Player_2).w
		move.l	#Obj_TitleCopyright,(Dynamic_object_RAM).w
		move.l	#Obj_TitleSonicFinger,(Dynamic_object_RAM+object_size).w
		move.l	#Obj_TitleSonicWink,(Dynamic_object_RAM+(object_size*2)).w
		move.l	#Obj_TitleTailsPlane,(Dynamic_object_RAM+(object_size*3)).w
;		move.l	#Obj_TitleANDKnuckles,(Dynamic_object_RAM+(object_size*4)).w				;
		move.b	#0,(Title_anim_delay).w
		move.w	#VDP_Plane_B|(VRAM_Plane_B_Name_Table>>13),(VDP_control_port).l	; Liliam: title screen - add fade from white
		move.w	#VDP_Plane_A|(VRAM_Plane_A_Name_Table>>10),(VDP_control_port).l	;
		tst.b	(Game_mode).w							;
		beq.s	loc_41D4							;
		jsr	(Process_Sprites).l						;
		jsr	(Render_Sprites).l						;
		bsr.w	Pal_FadeFromWhite						;

loc_41D4:

		move.b	#VInt_ID_1A,(V_int_routine).w					;
;		move.b	#VInt_ID_4,(V_int_routine).w					;
		bsr.w	Wait_VSync
		jsr	(Process_Sprites).l
		jsr	(Render_Sprites).l
		bsr.w	Process_Nem_Queue_Init
		tst.w	(Palette_fade_timer).w						;
		bne.s	loc_41D4							;
;		tst.l	(Reserved_object_3).w						;
;		beq.s	loc_41D4							;
		tst.w	(Demo_timer).w
		beq.w	loc_4278			; If the timer has run out, go do the level demos
		move.b	(Ctrl_1_pressed).w,d0
		or.b	(Ctrl_2_pressed).w,d0
		andi.b	#button_start_mask,d0
		beq.w	loc_41D4			; Repeat until start has been pressed on either controller

		; Liliam: removed original implementation
		moveq	#$7F,d0					; Liliam: title screen - expand options
		and.b	(Title_screen_option).w,d0		;
		move.b	TitleScreen_GameModes(pc,d0.w),d0	;
		bmi.s	TitleScreen_DenySelection		;
		move.b	d0,(Game_mode).w			;
		cmpi.b	#GameMode_LevelSelect,d0		;
		beq.s	TitleScreen_LevelSelect			;

		clr.b	(Encore_mode).w				; Liliam: Encore mode - clear variables

TitleScreen_LevelSelect:
		moveq	#signextendB(cmd_FadeOut),d0		; Liliam: upgraded S3&K sound driver (credit: flamewing)
		bra.w	Play_Music				;
; ---------------------------------------------------------------------------

TitleScreen_DenySelection:					; Liliam: title screen - expand options
		moveq	#signextendB(sfx_Error),d0
		bsr.w	Play_SFX
		bra.s	loc_41D4
; ---------------------------------------------------------------------------
TitleScreen_GameModes:						; Liliam: title screen - expand options
		dc.b GameMode_SaveScreen
		dc.b GameMode_EncoreMode
		dc.b GameMode_Competition
	if NoMuseum
		dc.b $80
	else
		dc.b GameMode_Museum
	endif
		dc.b GameMode_BlueSpheres
		dc.b GameMode_S3Credits
		dc.b GameMode_LevelSelect
		even
; ---------------------------------------------------------------------------

loc_4278:
		clr.b	(Encore_mode).w				; Liliam: Encore mode - clear variables
;		moveq	#signextendB(cmd_FadeOut),d0		;
;		bsr.w	Play_SFX				;
		move.w	(Next_demo_number).w,d0
		andi.w	#3,d0					; Liliam: title screen - remove S&K demos
		move.w	d0,(Demo_number).w
;		andi.w	#7,d0					;
		add.w	d0,d0
		lea	DemoLevels(pc),a0
		move.w	(a0,d0.w),d0
		move.w	d0,(Current_zone_and_act).w		; Load level index to the appropriate variables
		move.w	d0,(Apparent_zone_and_act).w
		move.w	d0,(Saved_zone_and_act).w
		move.w	(Next_demo_number).w,d1
		addq.w	#1,d1

		; Liliam: removed S&K alone mode
		cmpi.w	#4,d1					; Liliam: title screen - remove S&K demos
;		cmpi.w	#7,d1					;
		blo.s	loc_42C8
		moveq	#0,d1

loc_42C8:
		move.w	d1,(Next_demo_number).w
		tst.w	d0
		bpl.s	loc_4300			; Branch if we are indeed playing a level
		move.b	#GameMode_SpecialStage,(Game_mode).w	; Do the special stage demo
		move.b	#1,(Current_special_stage).w
		move.b	#1,(SK_special_stage_flag).w
;		move.b	#7,(Current_zone).w			; Liliam: removed S&K alone mode
		clr.w	(Emerald_counts).w
		clr.l	(Collected_emeralds_array).w
		clr.w	(Collected_emeralds_array+4).w
		clr.b	(Collected_emeralds_array+6).w
;		move.b	#2,(Collected_emeralds_array+1).w	; Liliam: removed S&K alone mode
		bra.s	loc_4306
; ---------------------------------------------------------------------------

loc_4300:
		move.b	#GameMode_Demo,(Game_mode).w	; We're about to perform a level demo

loc_4306:
		move.w	#1,(Demo_mode_flag).w
		move.b	#3,(Life_count).w
		move.b	#3,(Life_count_P2).w
		moveq	#0,d0
		move.w	d0,(Ring_count).w
		move.l	d0,(Timer).w
		move.l	d0,(Score).w
		move.w	d0,(Ring_count_P2).w
		move.l	d0,(Timer_P2).w
		move.l	d0,(Score_P2).w
		move.l	#5000,(Next_extra_life_score).w
		move.l	#5000,(Next_extra_life_score_P2).w
		rts
; ---------------------------------------------------------------------------
DemoLevels:
		dc.w     0	; Angel Island
		dc.w  $100	; Hydrocity
		dc.w  $200	; Marble Garden
;		dc.w  $700	; Mushroom Hill 		; Liliam: title screen - remove S&K demos
;		dc.w  $400	; Flying Battery		;
;		dc.w  $800	; Sandopolis			;
		dc.w $FFFF
; ---------------------------------------------------------------------------


TitleAnim_FlipBuffer:
		tst.b	(Title_anim_delay).w
		bne.s	loc_43AC
		move.w	(Title_anim_frame).w,d0				; Liliam: title anim - compensate for variable decompression times
		cmp.w	#$C,d0						;
;		move.b	#4-1,(Title_anim_delay).w			;
;		cmpi.w	#$C,(Title_anim_frame).w			;
		bhs.s	loc_43B2
		move.b	TitleAnim_Delay(pc,d0.w),(Title_anim_delay).w	;
;		move.b	#4-1,(Title_anim_delay).w			;
		lea	(Target_palette).w,a0
		lea	(Normal_palette).w,a1
		moveq	#bytesToLcnt(Normal_palette_line_3-Normal_palette),d0

loc_4376:
		move.l	(a0)+,(a1)+
		dbf	d0,loc_4376
		eori.b	#-1,(Title_anim_buffer).w
		tst.b	(Title_anim_buffer).w
		beq.s	loc_439A
		move.w	#VDP_Plane_B|(VRAM_Plane_A_Name_Table>>13),(VDP_control_port).l		; Nametable B Address $C000
		move.w	#VDP_Plane_A|(VRAM_Plane_A_Name_Table>>10),(VDP_control_port).l		; Nametable A Address $C000
		rts
; ---------------------------------------------------------------------------

loc_439A:
		move.w	#VDP_Plane_B|(VRAM_Plane_B_Name_Table>>13),(VDP_control_port).l		; Nametable B Address $E000
		move.w	#VDP_Plane_A|(VRAM_Plane_B_Name_Table>>10),(VDP_control_port).l		; Nametable A Address $E000
		rts
; ---------------------------------------------------------------------------

loc_43AC:
		subq.b	#1,(Title_anim_delay).w
		rts
; ---------------------------------------------------------------------------
TitleAnim_Delay:							; Liliam: title anim - compensate for variable decompression times
		;            5    5    5    5    5    5   15   10   10   10   10
		dc.b    0,   3,   3,   3,   3,   3,   1,   2,   1,   2,   3,  10
; ---------------------------------------------------------------------------

loc_43B2:
		lea	(Target_palette).w,a0
		lea	(Normal_palette).w,a1
		moveq	#bytesToLcnt(Normal_palette_end-Normal_palette),d0

loc_43BC:
		move.l	(a0)+,(a1)+
		dbf	d0,loc_43BC
		move.w	#VDP_Plane_B|(VRAM_Plane_B_Name_Table>>13),(VDP_control_port).l		; Nametable B Address $E000
		move.w	#VDP_Plane_A|(VRAM_Plane_A_Name_Table>>10),(VDP_control_port).l		; Nametable A Address $C000
		rts

; =============== S U B R O U T I N E =======================================


Iterate_TitleSonicFrame:
		cmpi.b	#1,(Title_anim_delay).w
		bne.s	locret_43F0
		move.w	(Title_anim_frame).w,d0
		move.b	SonicFrameIndex(pc,d0.w),d0
		ext.w	d0
		bmi.s	loc_43F2	; if negative, do not load anymore frames
		bsr.w	TitleSonic_LoadFrame
		addq.w	#1,(Title_anim_frame).w

locret_43F0:
		rts
; ---------------------------------------------------------------------------

loc_43F2:
		move.w	#$C,(Title_anim_frame).w
		move.b	#3,(Title_anim_delay).w
		rts
; ---------------------------------------------------------------------------
SonicFrameIndex:
		dc.b    1,   2,   3,   4,   5,   6,   7,   8,   9,  $A,  $B, $FF
		even

; =============== S U B R O U T I N E =======================================


TitleSonic_LoadFrame:
		move.w	d0,d7
		add.w	d0,d0
		add.w	d0,d0
		move.w	d0,d1
		add.w	d0,d0
		add.w	d1,d0
		lea	(TitleSonic_Frames).l,a2
		lea	(a2,d0.w),a2
		move.w	#$2C60,d3
		move.l	(a2)+,d0				; Art data
		cmpi.w	#7,d7
		beq.s	loc_4446
		bcs.s	loc_4466
		andi.l	#$FFFFFF,d0
		movea.l	d0,a0
		lea	(RAM_start).l,a1
		bsr.w	Kos_Decomp
		move.w	a1,d3
		lsr.w	#1,d3

loc_4446:
		move.l	#RAM_start,d1
		move.w	#0,d2
		tst.b	(Title_anim_buffer).w		; FFFFBC toggles on and off so that each animation frame could alternate locations for a sort of makeshift double-buffering
		beq.s	loc_445A
		move.w	#tiles_to_bytes(ArtTile_Title_Buffer),d2

loc_445A:
		andi.l	#$FFFFFF,d1
		jsr	(Add_To_DMA_Queue).l

loc_4466:
		movea.l	(a2)+,a0			; Palette data address
		lea	(Target_palette).w,a1
		moveq	#bytesToLcnt(Target_palette_line_3-Target_palette),d0

loc_446E:
		move.l	(a0)+,(a1)+
		dbf	d0,loc_446E
		tst.b	(Title_anim_buffer).w
		bne.s	loc_44B8
		lea	(RAM_start+$8000).w,a1			; Buffer 1
		movea.l	(a2)+,a0				; Enigma Mappings
		move.w	#make_art_tile($000,0,0),d0
		bsr.w	Eni_Decomp
		cmpi.w	#7,d7
		bhs.s	loc_449A
		tst.b	(Graphics_flags).w
		bmi.s	loc_449A
		moveq	#0,d0
		move.l	d0,(RAM_start+$83AC).w

loc_449A:
		move	#$2700,sr
		lea	(RAM_start+$8000).w,a1
		move.l	#vdpComm(VRAM_Plane_A_Name_Table,VRAM,WRITE),d0	; to $C000 in VRAM, Nametable A
		moveq	#40-1,d1
		moveq	#28-1,d2
		jsr	(Plane_Map_To_VRAM).l
		move	#$2300,sr
		rts
; ---------------------------------------------------------------------------

loc_44B8:
		lea	(RAM_start+$8000).w,a1			; Buffer 2
		movea.l	(a2)+,a0				; Enigma Mappings
		move.w	#make_art_tile(ArtTile_Title_Buffer,0,0),d0
		cmpi.w	#7,d7
		bhs.s	loc_44CC
		move.w	#make_art_tile($000,0,0),d0

loc_44CC:
		bsr.w	Eni_Decomp
		cmpi.w	#7,d7
		bhs.s	loc_44E2
		tst.b	(Graphics_flags).w
		bmi.s	loc_44E2
		moveq	#0,d0
		move.l	d0,(RAM_start+$83AC).w

loc_44E2:
		move	#$2700,sr
		lea	(RAM_start+$8000).w,a1
		move.l	#vdpComm(VRAM_Plane_B_Name_Table,VRAM,WRITE),d0	; to $E000 in VRAM Nametable B
		moveq	#40-1,d1
		moveq	#28-1,d2
		jsr	(Plane_Map_To_VRAM).l
		move	#$2300,sr
		rts
; End of function TitleSonic_LoadFrame

; ---------------------------------------------------------------------------
TitleSonic_Frames:
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic1
		dc.l MapEni_S3TitleSonic1				;S3DATA
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic2
		dc.l MapEni_S3TitleSonic2				;S3DATA
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic3
		dc.l MapEni_S3TitleSonic3				;S3DATA
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic4
		dc.l MapEni_S3TitleSonic4				;S3DATA
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic5
		dc.l MapEni_S3TitleSonic5				;S3DATA
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic6
		dc.l MapEni_S3TitleSonic6				;S3DATA
		dc.l ArtKos_S3TitleSonic1				;S3DATA
		dc.l Pal_TitleSonic7
		dc.l MapEni_S3TitleSonic7				;S3DATA
		dc.l ArtKos_S3TitleSonic8				;S3DATA
		dc.l Pal_TitleSonic8
		dc.l MapEni_S3TitleSonic8				;S3DATA
		dc.l ArtKos_S3TitleSonic9				;S3DATA
		dc.l Pal_TitleSonic9
		dc.l MapEni_S3TitleSonic9				;S3DATA
		dc.l ArtKos_S3TitleSonicA				;S3DATA
		dc.l Pal_TitleSonicA
		dc.l MapEni_S3TitleSonicA				;S3DATA
		dc.l ArtKos_S3TitleSonicB				;S3DATA
