S3_Level_Select_Code:
		tst.w	(Level_select_flag).w			; Liliam: title screen - restore S3 level select code
		beq.s	loc_4C50				;
		rts
; ---------------------------------------------------------------------------

loc_4C50:
		lea	(LSelect3CodeDat).l,a1
		move.w	(Cheat_input_counter).w,d0
		adda.w	d0,a1
		move.b	(Ctrl_1_pressed_title).w,d0
		andi.b	#$7F,d0
		beq.s	locret_4C90
		move.b	(Ctrl_1_held_title).w,d0
		cmp.b	(a1),d0
		bne.s	loc_4C8A
		addq.w	#1,(Cheat_input_counter).w
		tst.b	1(a1)
		bne.s	locret_4C90
		move.w	#(1<<8)|1,(Level_select_flag).w
;		move.w	#(1<<8)|1,(Debug_cheat_flag).w		; Liliam: ported from S3 - restore level select cheats
		moveq	#signextendB(sfx_RingRight),d0
		bsr.w	Play_SFX
		move.b	#6,(Title_screen_option).w		; Liliam: title screen - move cursor to level select
		move.b	#$C,(Player_2+mapping_frame).w		;

loc_4C8A:
		move.w	#0,(Cheat_input_counter).w
		cmpi.b	#button_up_mask,d0			; Liliam: advance by correct number of up presses on failure
		bne.s	locret_4C90				;
		move.b	1(a1),(Cheat_input_counter+1).w		;

locret_4C90:
		rts
; End of function S3_Level_Select_Code

