ChangeRingFrame_ReadySuper:						; Liliam: HUD - barrier HUD
		cmpi.b	#State_Dead,(Player_1+routine).w
		bhs.w	locret_7810
		moveq	#0,d1
		move.b	d1,(Super_ready_flag).w
		tst.b	(Encore_mode).w
		bne.s	.encoreMode
		tst.w	(Super_Sonic_Knux_flag).w
		bne.s	.checkBarrier
		tst.b	(Update_HUD_timer).w
		beq.s	.notReady
		cmpi.b	#6,(Player_1+character_id).w
		beq.s	.notReady
		cmpi.w	#50,(Ring_count).w
		blo.s	.notReady
		cmpi.b	#7,(Super_emerald_count).w
		bhs.s	.setReadyFlag
		cmpi.b	#7,(Chaos_emerald_count).w
		blo.s	.notReady
		tst.b	(Emeralds_converted_flag).w
		bne.s	.notReady

	.setReadyFlag:
		move.b	#1,(Super_ready_flag).w
		tst.b	(Player_1+jumping).w
		beq.s	.setSuperIcon
		tst.b	(Player_1+double_jump_flag).w
		bne.s	.setSuperIcon
		tst.b	(Super_ready_HUD_flag).w
		bmi.w	.done
		move.l	#ArtUnc_CutsceneSkip+$100,d1
		move.w	#tiles_to_bytes(ArtTile_Player_1+$17),d2
		move.w	#$90,d3
		bsr.w	Add_To_DMA_Queue
		moveq	#-1,d1

	.setSuperIcon:
		move.b	d1,(Super_ready_HUD_flag).w
		moveq	#0,d1
		bra.s	.done
; ---------------------------------------------------------------------------

	.encoreMode:
		tst.b	(Player_1+invincibility_timer).w
		bne.s	.checkBarrier

	.checkCombineRing:
		btst	#Status_CombineRing,(Player_1+status_secondary).w
		beq.s	.setIcon
		moveq	#$C,d1
		bra.s	.setIcon
; ---------------------------------------------------------------------------

	.notReady:
		move.b	d1,(Super_ready_HUD_flag).w
		tst.b	(Player_1+invincibility_timer).w
		beq.s	.setIcon

	.checkBarrier:
		move.b	(Player_1+status_secondary).w,d0
		andi.b	#1<<Status_CombineRing|1<<Status_FireShield|1<<Status_LtngShield|1<<Status_BublShield,d0
		beq.s	.setIcon
		moveq	#4,d1
		btst	#Status_FireShield,d0
		bne.s	.setIcon
		addq.w	#2,d1
		btst	#Status_LtngShield,d0
		bne.s	.setIcon
		addq.w	#2,d1
		btst	#Status_BublShield,d0
		beq.s	.checkCombineRing
		tst.b	(Encore_mode).w
		bne.s	.done
		cmpi.w	#3,(Player_mode).w
		beq.s	.done
		cmpi.w	#4,(Player_mode).w
		beq.s	.done
		tst.b	(Super_palette_status).w
		beq.s	.setIcon
		tst.b	(Super_Tails_flag).w
		bpl.s	.setIcon

	.done:
		addq.w	#2,d1

	.setIcon:
		move.w	d1,(Barrier_HUD_frame).w
		beq.s	ChangeRingFrame
		tst.b	(Barrier_HUD_DMA_flag).w
		bmi.s	ChangeRingFrame
		move.b	#$E,(Barrier_HUD_frame+1).w
		cmp.b	(Barrier_HUD_DMA_flag).w,d1
		beq.s	ChangeRingFrame
		move.b	d1,(Barrier_HUD_DMA_flag).w
		tst.b	(Encore_mode).w
		beq.s	.checkRay
		cmpi.b	#$A,d1
		bne.s	.queueDMA
