		bne.s	loc_7DBA					;
		clr.b	(Alternate_start_flag).w			;
		clr.w	(Player_mode).w					;

loc_7DBA:
		; Liliam: removed S&K alone mode
		clr.b	(Demo_mode_flag).w			; Liliam: ending - allow start from save screen
		cmpi.w	#$D01,d0				;
		bne.s	LevelSelect_CheckSpecialStage		;
		move.b	(Game_mode).w,(Demo_mode_flag).w	;


LevelSelect_CheckSpecialStage:
		cmpi.w	#$4000,d0				; Liliam: level select - access all special stages from act 1
		bne.s	LevelSelect_CheckHPZSS			;
		moveq	#signextendB(sfx_EnterSS),d0		;
		bsr.w	Play_SFX				;
		clr.b	(SK_special_stage_flag).w		;
		move.b	#GameMode_SpecialStage,(Game_mode).w	;
		cmpi.b	#7,(Chaos_emerald_count).w		;
		blo.s	LevelSelect_StartZoneContinued		;
		move.b	#1,(SK_special_stage_flag).w		;
		bra.s	LevelSelect_StartZoneContinued		;
; ---------------------------------------------------------------------------

LevelSelect_CheckHPZSS:
		cmpi.w	#$1701,d0							; Liliam: level select - add HPZ special
		bne.s	LevelSelect_StartZone						;
		moveq	#signextendB(sfx_EnterSS),d0					;
		bsr.w	Play_SFX							;
		clr.b	(Saved2_last_star_post_hit).w					;
		move.w	(Current_zone_and_act).w,(Saved2_zone_and_act).w		;
		move.w	(Apparent_zone_and_act).w,(Saved2_apparent_zone_and_act).w	;
		move.w	#$1701,d0							;

LevelSelect_StartZone:
;		andi.w	#$3FFF,d0							;
		move.w	d0,(Current_zone_and_act).w
		move.w	d0,(Apparent_zone_and_act).w
		move.w	d0,(Saved_zone_and_act).w
		move.w	d0,(Saved_apparent_zone_and_act).w
		move.w	#$1000,d0
		move.w	d0,(Saved_camera_max_Y_pos).w
		move.w	d0,(Saved2_camera_max_Y_pos).w
		move.b	#GameMode_Level,(Game_mode).w

LevelSelect_StartZoneContinued:
		st	(AIZ_skip_intro_flag).w			; Liliam: cutscene skip - AIZ intro
		move.b	#3,(Life_count).w
