LevSel_MarkTable:	; 4 bytes per level select entry
; line primary, 2*column ($E fields), line secondary, 2*column secondary (1 field)
		dc.b    1,   6,   1, $24
		dc.b    1,   6,   2, $24
		dc.b    4,   6,   4, $24
		dc.b    4,   6,   5, $24
		dc.b    7,   6,   7, $24
		dc.b    7,   6,   8, $24
		dc.b   $A,   6,  $A, $24
		dc.b   $A,   6,  $B, $24
		dc.b   $D,   6,  $D, $24
		dc.b   $D,   6,  $E, $24
		dc.b  $10,   6, $10, $24
		dc.b  $10,   6, $11, $24
		dc.b  $13,   6, $13, $24
		dc.b  $13,   6, $14, $24
		dc.b  $16,   6, $16, $24
		dc.b  $16,   6, $17, $24
		dc.b  $19,   6, $19, $24
		dc.b  $19,   6, $1A, $24
; --- second column ---
		dc.b    1, $2C,   1, $4A
		dc.b    1, $2C,   2, $4A
		dc.b    4, $2C,   4, $4A
		dc.b    4, $2C,   5, $4A
		dc.b    7, $2C,   7, $4A
		dc.b    7, $2C,   8, $4A
		dc.b   $A, $2C,  $A, $4A
		dc.b   $A, $2C,  $B, $4A
		dc.b   $D, $2C,  $D, $4A
		dc.b   $D, $2C,  $E, $4A
		dc.b  $10, $2C, $10, $4A
		dc.b  $10, $2C, $11, $4A
;		dc.b  $13, $2C, $13, $4A			; Liliam: level select - expand options
;		dc.b  $13, $2C, $14, $4A			;
;		dc.b  $16, $2C, $16, $4A			;
; --- third column ---
		dc.b    1, $52,   1, $70			;
		dc.b    1, $52,   2, $70			;
		dc.b    4, $52,   4, $70			;
		dc.b    4, $52,   5, $70			;
		dc.b    7, $52,   7, $70			;
		dc.b    7, $52,   8, $70			;
		dc.b   $A, $52,  $A, $70			;
		dc.b   $A, $52,  $B, $70			;
		dc.b   $D, $52,  $D, $70			;
		dc.b   $D, $52,  $E, $70			;
		dc.b  $10, $52, $10, $70			;
		dc.b  $10, $52, $11, $70			;
