LevelSelect_CheckCheats:					; Liliam: ported from S3 - restore level select cheats
		tst.b	(Debug_cheat_flag).w
		bne.s	.check1
		lea	DebugCodeDat(pc),a0
		move.w	(Debug_cheat_input_counter-1).w,d1
		clr.w	(Debug_cheat_input_counter-1).w
		adda.w	d1,a0
		cmp.b	(a0),d2
		bne.s	.check1
		addq.w	#1,d1
		move.w	d1,(Debug_cheat_input_counter-1).w
		tst.b	1(a0)
		bpl.s	.check1
		move.w	#(1<<8)|1,(Debug_cheat_flag).w
		moveq	#signextendB(sfx_RingRight),d0
		bsr.w	Play_SFX
		move.w	d2,d0

	.check1:
		move.w	(Cheat_input_counter).w,d1
		lea	AllEmeraldsCodeDat(pc,d1.w),a0
		cmp.b	(a0),d2
		bne.s	.clear1
		addq.w	#1,(Cheat_input_counter).w
		tst.b	1(a0)
		bpl.s	.check2
		move.b	#7,(Current_special_stage).w
		moveq	#3,d0
		bsr.s	LevelSelect_GiveEmeralds
		moveq	#signextendB(sfx_Perfect),d0
		bsr.w	Play_SFX
		moveq	#signextendB(cmd_Stop),d0

	.clear1:
		clr.w	(Cheat_input_counter).w

	.check2:
		move.w	(Cheat_input_counter2).w,d1
		lea	AllEmeraldsCodeDat2(pc,d1.w),a0
		cmp.b	(a0),d2
		bne.s	.clear2
		addq.w	#1,(Cheat_input_counter2).w
		tst.b	1(a0)
		bpl.s	.done
		moveq	#0,d0
		move.b	d0,(Current_special_stage).w
		tst.b	(Encore_mode).w
		bne.s	.giveEmeralds
		moveq	#1,d0

	.giveEmeralds:
		bsr.s	LevelSelect_GiveEmeralds
		moveq	#signextendB(mus_Emerald),d0

	.clear2:
		clr.w	(Cheat_input_counter2).w

	.done:
		bra.w	Play_Music
; ---------------------------------------------------------------------------

LevelSelect_GiveEmeralds:								; Liliam: level select - add HPZ special
		lea	(Collected_emeralds_array).w,a0
		moveq	#6,d1

	.loop:
		move.b	d0,(a0)+
		dbf	d1,.loop
		move.w	d0,(Emerald_counts).w
		beq.s	.done
		move.w	#$700,(Emerald_counts).w
		lsr.b	#1,d0
		beq.s	.done
		move.w	#$707,(Emerald_counts).w

	.done:
		move.b	d0,(Emeralds_converted_flag).w
		rts
; ---------------------------------------------------------------------------
AllEmeraldsCodeDat:						; Liliam: ported from S3 - restore level select cheats
		dc.b    1,   3,   5,   7, $FF
AllEmeraldsCodeDat2:						; Liliam: ported from S3 - restore level select cheats
		dc.b    2,   4,   5,   6, $FF
DebugCodeDat:							; Liliam: ported from S3 - restore level select cheats
		dc.b    1,   9,   9,   4,   1,   0,   1,   8, $FF
		even
