		move.b	#1,(Special_stage_clear_routine).w	; Set flag to clear special stage

loc_9E9C:
		move.w	(sp)+,d0
		rts
; End of function Decrement_BlueSphere_Count


; =============== S U B R O U T I N E =======================================


sub_9EA0:
		lea	(SStage_layout_buffer+$100).w,a3
		moveq	#0,d1
		move.w	#$400-1,d0

loc_9EAA:
