		cmpi.b	#2,d2					;
		beq.s	loc_9EB0				;
		tst.b	(Special_stage_green_spheres).w		;
		beq.s	loc_9EB2				;
		cmpi.b	#5,d2					;
;		cmpi.b	#2,(a3)+				;
		bne.s	loc_9EB2

loc_9EB0:
		addq.w	#1,d1

loc_9EB2:
