		clr.w	(SRAM_mask_interrupts_flag).w	; No interrupt shenanigans needed
		lea	(SRAM_competition).l,a0
		lea	(SRAM_competition_backup).l,a1
		lea	(Competition_saved_data).w,a2
		moveq	#bytesToWcnt(SRAM_competition_size),d0
		move.w	#SRAM_integrity2,d1		; RAM integrity value
		jsr	Get_From_SRAM(pc)
		beq.s	loc_C190			; If the data read was successful, branch
		lea	SaveData_CompetitionDefault(pc),a0
		lea	(Competition_saved_data).w,a1
		moveq	#bytesToWcnt(SRAM_competition_size-2),d0

loc_C186:
		move.w	(a0)+,(a1)+			; Reset the competition save data to the default
		dbf	d0,loc_C186
		jsr	Write_SaveCompetition(pc)	; Write default data back to SRAM

loc_C190:
		lea	(SRAM_main).l,a0
		lea	(SRAM_main_backup).l,a1
		lea	(Saved_data).w,a2
		moveq	#bytesToWcnt(SRAM_main_size),d0
		move.w	#SRAM_integrity,d1		; RAM integrity value for save game data
		jsr	Get_From_SRAM(pc)
		bne.s	loc_C1C0			; If the data read was not successful, branch
		lea	(Saved_data).w,a0
		moveq	#SRAM_num_slots-1,d0

loc_C1B2:
		tst.b	(a0)
		bpl.w	loc_C256			; If any of the save files are active, then we're done here
		lea	SRAM_next_slot(a0),a0
		dbf	d0,loc_C1B2			; if not then we load them up with default data

loc_C1C0:
		lea	SaveData_MainDefault(pc),a0
		lea	(Saved_data).w,a1
		moveq	#bytesToWcnt(SRAM_main_size-2),d0

loc_C1CA:
		move.w	(a0)+,(a1)+
		dbf	d0,loc_C1CA			; Write default game data
		; Liliam: removed S&K lock-on code
		jsr	Write_SaveGame(pc)

loc_C256:
		lea	(SRAM_encore).l,a0				; Liliam: Encore mode - save data
		lea	(SRAM_encore_backup).l,a1			;
		lea	(Encore_saved_data).w,a2			;
		moveq	#bytesToWcnt(SRAM_encore_size),d0		;
		move.w	#SRAM_integrity,d1				;
		jsr	Get_From_SRAM(pc)				;
		bne.s	.reset						;
		lea	(Encore_saved_data).w,a0			;
		moveq	#SRAM_encore_num_slots-1,d0			;

	.loop1:
		tst.b	(a0)						;
		bpl.s	.extra						;
		lea	SRAM_next_slot(a0),a0				;
		dbf	d0,.loop1					;

	.reset:
		lea	SaveData_EncoreDefault(pc),a0			;
		lea	(Encore_saved_data).w,a1			;
		moveq	#bytesToWcnt(SRAM_encore_size-2),d0		;

	.loop2:
		move.w	(a0)+,(a1)+					;
		dbf	d0,.loop2					;
		bsr.w	Write_SaveEncore				;

	.extra:
		lea	(SRAM_extra).l,a0			; Liliam: options menu
		lea	(SRAM_extra_backup).l,a1		;
		lea	(Extra_saved_data).w,a2			;
		moveq	#bytesToWcnt(SRAM_extra_size),d0	;
		move.w	#SRAM_integrity2,d1			;
		jsr	Get_From_SRAM(pc)			;
		beq.s	.done					;
		lea	(Extra_saved_data).w,a1			;
		moveq	#bytesToWcnt(SRAM_extra_size-4),d0	;

	.loop3:
		clr.w	(a1)+					;
		dbf	d0,.loop3				;
		move.w	d1,(a1)+				;
		move.b	#EncoreFlags_Initial,(Encore_options).w	;
		bsr.w	Write_SaveExtra				;

	.done:
		clr.w	(Dataselect_nosave_player).w
		move.b	#1,(Dataselect_entry).w
		rts
; End of function SRAM_Load

; ---------------------------------------------------------------------------
SaveData_CompetitionDefault:
		dc.w  $8000,     0, $8000,     0, $8000,     0,     1,  $200
		dc.w  $8000,     0, $8000,     0, $8000,     0,     1,  $200
		dc.w  $8000,     0, $8000,     0, $8000,     0,     1,  $200
		dc.w  $8000,     0, $8000,     0, $8000,     0,     1,  $200
		dc.w  $8000,     0, $8000,     0, $8000,     0,     1,  $200
		dc.w  SRAM_integrity2
SaveData_MainDefault:
	if DevMode
		dc.w   $30E,     0,     0, $FFFC,  $300
		dc.w   $20E,  $100,     0, $5554,  $300
		dc.w   $20D,  $200,     0, $5554,  $300
		dc.w   $20C,  $300,     0, $5554,  $300
		dc.w   $20D,  $400,     0, $5554,  $300
		dc.w   $20D,  $500,     0, $5554,  $300
		dc.w   $20D,  $600,     0, $5554,  $300
		dc.w   $10C,  $700,     0,     0,  $300
		dc.w  SRAM_integrity
	else
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  $8000,     0,     0,     0,  $300
		dc.w  SRAM_integrity
	endif
SaveData_EncoreDefault:							; Liliam: Encore mode - save data
	if DevMode
		dc.w   $30C,   %1111111010000<<3,     0, $FFFC, %111110101100010
		dc.w      7,    %111111100101<<3,     0,     0,       %011010001
		dc.w  $8000,                1<<9,     0,     0,                0
		dc.l     -1,     0,     0
		dc.w  SRAM_integrity
	else
		dc.w  $8000,  1<<9,     0,     0,     0
		dc.w  $8000,  1<<9,     0,     0,     0
		dc.w  $8000,  1<<9,     0,     0,     0
		dc.l      0,     0,     0
		dc.w  SRAM_integrity
	endif
;SaveData_S3LevRef:
		; Liliam: removed S&K lock-on code

; =============== S U B R O U T I N E =======================================


Get_From_SRAM:
		movea.l	a2,a3
		move.w	d0,d2
		bsr.s	Read_SRAM
		beq.s	locret_C31E
		movea.l	a1,a0
		movea.l	a3,a2
		move.w	d2,d0
		bsr.s	Read_SRAM

locret_C31E:
		rts
; End of function Get_From_SRAM


; =============== S U B R O U T I N E =======================================


Read_SRAM:
		tst.w	(SRAM_mask_interrupts_flag).w
		beq.s	loc_C32A
		move	#$2700,sr		; Disable interrupts if EF56 is set

loc_C32A:
		move.b	#1,(SRAM_access_flag).l	; Access SRAM
		movea.l	a2,a6
		move.w	d0,d6

loc_C336:
		movep.w	0(a0),d3
		move.w	d3,(a2)+		; Read data from SRAM
		addq.w	#4,a0
		dbf	d0,loc_C336
		move.b	#0,(SRAM_access_flag).l	; No longer access SRAM
		tst.w	(SRAM_mask_interrupts_flag).w
		beq.s	loc_C354
		move	#$2300,sr		; Restore interrupts if EF56 is set

loc_C354:
		subq.w	#1,d6
		bsr.s	Create_SRAMChecksum	; Get the checksum of the given data
		cmp.w	(a6),d7		; Compare the result
		bne.s	locret_C360
		cmp.w	-2(a6),d1	; Also compare the data before with the data given in d1

locret_C360:
		rts
; End of function Read_SRAM


; =============== S U B R O U T I N E =======================================


Create_SRAMChecksum:
		moveq	#0,d7

loc_C364:
		move.w	(a6)+,d5
		eor.w	d5,d7
		lsr.w	#1,d7
		bcc.s	loc_C370
		eori.w	#$8810,d7

loc_C370:
		dbf	d6,loc_C364
		rts
; End of function Create_SRAMChecksum


; =============== S U B R O U T I N E =======================================


Write_SRAM:
		movea.l	a2,a6
		move.w	d0,d6
		subq.w	#1,d6
		bsr.s	Create_SRAMChecksum
		move.w	d7,(a6)
		tst.w	(SRAM_mask_interrupts_flag).w
		beq.s	loc_C38A
		move	#$2700,sr		; If EF56 is set, disable interrupts while saving is occurring

loc_C38A:
		move.b	#1,(SRAM_access_flag).l	; Send I/O signal to SRAM, mapping it to $200001
		movea.l	a2,a3
		move.w	d0,d1

loc_C396:
		move.w	(a2)+,d2
		movep.w	d2,0(a0)	; Copy data to SRAM
		addq.w	#4,a0
		dbf	d0,loc_C396

loc_C3A2:
		move.w	(a3)+,d2
		movep.w	d2,0(a1)	; Copy data to backup SRAM
		addq.w	#4,a1
		dbf	d1,loc_C3A2
		move.b	#0,(SRAM_access_flag).l	; Stop SRAM access
		tst.w	(SRAM_mask_interrupts_flag).w
		beq.s	locret_C3C0
		move	#$2300,sr		; Restore interrupts if EF56 was set

locret_C3C0:
		rts
; End of function Write_SRAM


; =============== S U B R O U T I N E =======================================


Write_SaveCompetition2:
		st	(SRAM_mask_interrupts_flag).w

Write_SaveCompetition:
		move.l	a0,-(sp)
		move.w	d7,-(sp)
		lea	(SRAM_competition).l,a0		; Competition SRAM
		lea	(SRAM_competition_backup).l,a1	; Competition backup SRAM
		lea	(Competition_saved_data).w,a2	; Competition RAM
		moveq	#bytesToWcnt(SRAM_competition_size),d0
		bsr.s	Write_SRAM
		move.w	(sp)+,d7
		movea.l	(sp)+,a0
		rts
; End of function Write_SaveCompetition


; =============== S U B R O U T I N E =======================================


Write_SaveGame:
		move.l	a0,-(sp)
		move.w	d7,-(sp)
		lea	(SRAM_main).l,a0		; Save game SRAM
		lea	(SRAM_main_backup).l,a1		; Save game backup SRAM
		lea	(Saved_data).w,a2		; Save game RAM
		moveq	#bytesToWcnt(SRAM_main_size),d0
		jsr	Write_SRAM(pc)
		move.w	(sp)+,d7
		movea.l	(sp)+,a0
		rts
; End of function Write_SaveGame

; ---------------------------------------------------------------------------

Write_SaveEncore:							; Liliam: Encore mode - save data
		move.l	a0,-(sp)
		move.w	d7,-(sp)
		lea	(SRAM_encore).l,a0
		lea	(SRAM_encore_backup).l,a1
		lea	(Encore_saved_data).w,a2
		moveq	#bytesToWcnt(SRAM_encore_size),d0
		bsr.w	Write_SRAM
		move.w	(sp)+,d7
		movea.l	(sp)+,a0
		rts
; ---------------------------------------------------------------------------

Write_SaveExtra:						; Liliam: options menu
		move.l	a0,-(sp)
		move.w	d7,-(sp)
		lea	(SRAM_extra).l,a0
		lea	(SRAM_extra_backup).l,a1
		lea	(Extra_saved_data).w,a2
		moveq	#bytesToWcnt(SRAM_extra_size),d0
		bsr.w	Write_SRAM
		move.w	(sp)+,d7
		movea.l	(sp)+,a0
		rts
; ---------------------------------------------------------------------------
SaveGame_NextLevel:
		dc.b    1,   1
		dc.b    2,   2
		dc.b    3,   3
		dc.b    4,   4
		dc.b    8,   5    ;,   8						; Liliam: Encore mode - FBZ level order
		dc.b    5,   6    ;,   5						;
		dc.b    6,   7    ;,   6						;
		dc.b    7,   8    ;,   7						;
		dc.b    9,   9
		dc.b   $A,  $A
		dc.b   $C,  $B    ;,  $C				; Liliam: Encore mode - save data
		dc.b   $D,  $C    ;,  $D				;
		dc.b   $E,  $C    ;,  $E				;
		dc.b    0,   0
		dc.b    0,  $F    ;,   0			; Liliam: Encore mode - add extra levels
		dc.b    0, $11    ;,   0			;
		dc.b    0, $12    ;,   0			;
		dc.b    0, $10    ;,   0			;
		dc.b    0,   0
		dc.b    0,   0
		dc.b    0,   0
		dc.b    0,   0
		dc.b   $A,  $A    ;,  $B				; Liliam: Encore mode - save data
		dc.b   $D,  $C    ;,   0				;
		even

; =============== S U B R O U T I N E =======================================


SaveGame:
		; Liliam: removed S&K alone mode
		move.l	(Save_pointer).w,d0
		beq.w	loc_C4CC				; If not playing on a save file, get out
		movea.l	d0,a1
		move.w	(Apparent_zone_and_act).w,d0		; Liliam: HPZ - add Knuckles LRZ2 results
;		move.w	(Current_zone_and_act).w,d0		;
		tst.b	(Encore_mode).w							; Liliam: Encore mode - FBZ level order
		sne	d0								;
;		ror.b	#1,d0								;
		lsr.w	#7,d0
		move.b	SaveGame_NextLevel(pc,d0.w),d0
		bra.s	loc_C452							;
; ---------------------------------------------------------------------------

SaveGame_HPZTeleporter:
		tst.b	(Encore_mode).w					; Liliam: Encore mode - save data
		bne.w	loc_C4CC					;
		move.l	(Save_pointer).w,d0				;
		beq.w	loc_C4CC					;
		movea.l	d0,a1						;
		moveq	#$B,d0						;

loc_C452:
		move.b	SRAM_clear_type(a1),d1
		andi.w	#3,d1
		beq.s	loc_C464
		cmp.b	SRAM_current_zone(a1),d0		; If game is complete, make it uncomplete if last level is less than the current level
		blo.s	loc_C4B4				; Think of, say, getting all the super emeralds then going to Doomsday on a completed save file
		andi.b	#$FC,SRAM_clear_type(a1)

loc_C464:
		move.b	d0,SRAM_current_zone(a1)		; Move next level into current level

		tst.b	(Encore_mode).w					; Liliam: Encore mode - save data
		bne.s	loc_C470					;
		cmpi.w	#3,(Player_mode).w
		beq.s	loc_C470					; Liliam: data select - add extra characters
		cmpi.w	#7,(Player_mode).w				;
		bne.s	loc_C478

loc_C470:
		cmpi.b	#$C,d0
		blo.s	loc_C4B0
		bra.s	loc_C498				; If playing as Knuckles and level code is Death Egg or higher, make it a completed save file
; ---------------------------------------------------------------------------

loc_C478:
		cmpi.w	#2,(Player_mode).w
		blo.s	loc_C488					; Liliam: data select - add extra characters
;		bne.s	loc_C488					;
		cmpi.b	#$D,d0
		blo.s	loc_C4B0
		bra.s	loc_C498				; If playing as Tails and level code is Doomsday or higher, make it a completed save file
; ---------------------------------------------------------------------------

loc_C488:
		cmpi.b	#$D,d0
		bhi.s	loc_C498				; If next level above Doomsday's code, make it a completed save file
		bne.s	loc_C4B0
		cmpi.b	#7,(Chaos_emerald_count).w		; If next level IS Doomsday but the emeralds aren't collected, make it a completed save file
		bhs.s	loc_C4B0

loc_C498:
		moveq	#1,d0
		cmpi.b	#7,(Chaos_emerald_count).w
		blo.s	loc_C4AE				; code 1 is completed without all emeralds
		addq.b	#1,d0
		cmpi.b	#7,(Super_emerald_count).w
		blo.s	loc_C4AE				; code 2 is completed with all chaos emeralds
		addq.b	#1,d0					; code 3 is completed with all super emeralds

loc_C4AE:
		move.b	d0,SRAM_clear_type(a1)

loc_C4B0:
		clr.w	SRAM_collected_special_rings(a1)	; Clear the special stage ring collection memory

loc_C4B4:
		tst.b	(Encore_mode).w					; Liliam: Encore mode - save data
		beq.s	.notEncore					;
		move.w	(Encore_stocks_packed).w,SRAM_life_count(a1)	;
		move.b	(Encore_unlocked_chars).w,d0			;
		lsl.w	#3,d0						;
		or.b	(P2_character).w,d0				;
		lsl.w	#3,d0						;
		or.b	(P1_character).w,d0				;
		lsl.w	#3,d0						;
		or.b	(Current_special_stage).w,d0			;
		move.w	d0,SRAM_player_mode(a1)				;
		bsr.w	Write_SaveEncore				;
		bra.s	loc_C4CC					;
; ---------------------------------------------------------------------------

	.notEncore:
		move.b	(Life_count).w,d0			; Get number of lives
		cmpi.b	#99,d0
		bls.s	loc_C4C0
		moveq	#99,d0

loc_C4C0:
		move.b	d0,SRAM_life_count(a1)			; Put number of lives into memory
		move.b	d0,(Life_count).w
		jsr	Write_SaveGame(pc)

loc_C4CC:
		move.l	(P1_character).w,(Saved_encore_stocks).w	; Liliam: Encore mode - save data
		clr.l	(Collected_special_ring_array).w	; Clear special stage ring collection RAM
		rts
; End of function SaveGame


; =============== S U B R O U T I N E =======================================


SaveGame_SpecialStage:
		; Liliam: removed S&K alone mode
		move.l	(Save_pointer).w,d0
		beq.s	locret_C530
		movea.l	d0,a1					; Get address of save slot
;		tst.b	(SK_special_stage_flag).w			; Liliam: Encore mode - special stage
;		bne.s	loc_C4F8					;
;		andi.b	#$F0,SRAM_current_special_stage(a1)		; Liliam: data select - restructure save file
		andi.b	#$F8,SRAM_current_special_stage(a1)		;
		move.b	(Current_special_stage).w,d0
		andi.b	#7,d0						;
;		andi.b	#$F,d0						;
		or.b	d0,SRAM_current_special_stage(a1)	; Write last played special stage only if Sonic 3 special stages are in effect

loc_C4F8:
		lea	(Collected_emeralds_array).w,a2
		moveq	#0,d0
		moveq	#7-1,d1

loc_C500:
		move.b	(a2)+,d2
		andi.b	#3,d2
		or.b	d2,d0
		lsl.w	#2,d0
		dbf	d1,loc_C500
		move.w	d0,SRAM_collected_emeralds(a1)						; Compress emerald collection RAM and put it into Save Game
		move.w	(Collected_special_ring_array+2).w,SRAM_collected_special_rings(a1)	; Special stage entry ring memory is copied as well

;		move.b	(Continue_count).w,d0			; Liliam: continues - stop awarding in saved games
;		cmpi.b	#99,d0					;
;		bls.s	loc_C524				;
;		moveq	#99,d0					;

;loc_C524:
;		move.b	d0,SRAM_continue_count(a1)		;
;		move.b	d0,(Continue_count).w			;
		tst.b	(Encore_mode).w					; Liliam: Encore mode - save data
		bne.w	Write_SaveEncore				;
		jmp	Write_SaveGame(pc)
