SaveScreen_DrawEncoreStocks:						; Liliam: Encore mode - save data
		lea	(Dynamic_object_RAM+object_size).w,a3
		moveq	#SRAM_encore_num_slots-1,d6

	.loop1:
		movea.w	objoff_40(a3),a0
		tst.b	objoff_30(a0)
		beq.s	.nextSlot
		clr.b	objoff_30(a0)
		lea	Encore_stocks-Reserved_object_3(a0),a1
		moveq	#0,d2
		move.b	(a1)+,d2
		subq.b	#1,d2
		bls.s	.nextSlot
		move.w	art_tile(a0),d0
		lsl.w	#5,d0
		bsr.w	SaveScreen_MakeVDPCommand
		move.l	d0,VDP_control_port-VDP_data_port(a6)

	.loop2:
		bsr.w	HUD_Lives_Encore_CheckMiles
		lsl.w	#5,d1
		lea	ArtUnc_SaveScreenStockIcons(pc,d1.w),a2
		moveq	#bytesToLcnt($20),d3

	.loop3:
		move.l	(a2)+,(a6)
		dbf	d3,.loop3
		dbf	d2,.loop2

	.nextSlot:
		lea	next_object(a3),a3
		dbf	d6,.loop1
		rts
