Obj_SaveScreen_Selector:
		move.w	#$A8,d0
		moveq	#0,d1
		moveq	#0,d2
		move.b	(Dataselect_entry).w,d2
		tst.b	(Encore_mode).w					; Liliam: Encore mode - save data
		bne.s	.encoreMode					;
		tst.b	(Dataselect_encore_entry).w			;
		beq.s	loc_D1C2					;
		move.b	(Dataselect_encore_entry).w,d2			;
		clr.b	(Dataselect_encore_entry).w			;
		cmpi.b	#2,d2						;
		bls.s	.apply						;
		addq.b	#SRAM_num_slots-SRAM_encore_num_slots,d2	;
		bra.s	.apply						;
; ---------------------------------------------------------------------------

	.encoreMode:
		tst.b	(Dataselect_encore_entry).w			; Liliam: Encore mode - save data
		bne.s	loc_D1C2					;
		cmpi.b	#2,d2						;
		bls.s	loc_D1C2					;
		subq.b	#SRAM_num_slots-SRAM_encore_num_slots,d2	;
		cmpi.b	#2,d2						;
		bge.s	.update						;
		moveq	#2,d2						;

	.update:
		move.b	d2,(Dataselect_encore_entry).w			;

	.apply:
		move.b	d2,(Dataselect_entry).w				;

loc_D1C2:
		subq.w	#1,d2
		bcs.s	loc_D1E6

loc_D1C6:
		moveq	#$D-1,d4

loc_D1C8:
		addq.w	#8,d0
		cmpi.w	#$120,d0
		bls.s	loc_D1DE
		subq.w	#8,d0
		addq.w	#8,d1
		cmpi.w	#(SRAM_num_slots*$68)-$80,d1
		bhi.s	loc_D1DA					; Liliam: Encore mode - save data
		tst.b	(Encore_mode).w					;
		beq.s	loc_D1DE					;
		cmpi.w	#(SRAM_encore_num_slots*$68)-$80,d1		;
		bls.s	loc_D1DE

loc_D1DA:
		subq.w	#8,d1
		addq.w	#8,d0

loc_D1DE:
		dbf	d4,loc_D1C8
		dbf	d2,loc_D1C6

loc_D1E6:
		move.w	d0,objoff_12(a0)
		move.w	d1,(Camera_X_pos_copy).w
		neg.w	d1
		move.w	d1,(H_scroll_buffer+2).w
		move.l	#Obj_SaveScreen_Selector_Main,(a0)

Obj_SaveScreen_Selector_Main:
		btst	#button_A,(Ctrl_1_pressed).w		; Liliam: options menu
		beq.s	loc_D1FA				;
		tst.w	(Events_bg+$10).w			;
		bne.w	loc_D2CE				;
		move.b	#GameMode_EraseData,(Game_mode).w	;
		tst.w	(Events_bg+$12).w			;
		bne.w	loc_D2CE				;
		move.b	#GameMode_Options,(Game_mode).w		;
		bra.w	loc_D2CE				;
