loc_D1FA:
		tst.w	(Events_bg+$12).w
		bne.s	loc_D212
		btst	#button_B,(Ctrl_1_pressed).w
		beq.s	loc_D212
		move.b	#GameMode_TitleScreen,(Game_mode).w
		bra.w	loc_D2CE
