		btst	#button_left,(Ctrl_1_pressed).w
		beq.s	loc_D254
		tst.w	(Events_bg+$12).w
		beq.s	loc_D238
		cmpi.b	#1,(Dataselect_entry).w
		beq.s	loc_D254

loc_D238:
		tst.b	(Dataselect_entry).w
