		move.w	(Ring_count).w,d0
		cmpa.w	#Player_1,a0
		beq.s	loc_102A8
		tst.w	(Competition_mode).w
		beq.s	loc_102E0
		move.w	(Ring_count_P2).w,d0

loc_102A8:
		tst.b	status_tertiary(a0)			; Liliam: bugfix - preserve shield
		bmi.s	loc_102E0				;
		btst	#Status_Shield,status_secondary(a0)
		bne.s	loc_102DA
