		clr.b	double_jump_property(a0)		; Liliam: extra skills - drop dash
		bset	#Status_InAir,status(a0)
		move.w	#-$400,y_vel(a0)
		move.w	#-$200,x_vel(a0)
		btst	#Status_Underwater,status(a0)
		beq.s	loc_10312
		move.w	#-$200,y_vel(a0)
		move.w	#-$100,x_vel(a0)

loc_10312:
