		lea	(Distance_from_top_P2).w,a5
		lea	(Dust_P2).w,a6

Amy_Normal:
		move.l	#Map_Amy,mappings(a0)
		bsr.w	loc_10ADE
		move.b	(Disable_A_button_flag).w,d1
		bpl.s	.checkHammerRush
		addq.b	#1,d1
		beq.s	.checkButton
		addq.b	#1,d1
