	.checkTimer:
		bclr	#0,d1
		tst.b	d1
		bne.s	.updateTimer

	.throwBuffered:
		moveq	#-1,d1
		jsr	(AllocateObject).l
		bne.s	.updateTimer
		moveq	#-$1F,d1
		move.l	#Obj_HyperAmyHammer,(a1)
		move.w	x_pos(a0),x_pos(a1)
		move.w	y_pos(a0),y_pos(a1)
		move.w	x_vel(a0),x_vel(a1)
		btst	#Status_Facing,status(a0)
		beq.s	.checkGravity
		bset	#0,render_flags(a1)

	.checkGravity:
		tst.b	(Reverse_gravity_flag).w
		beq.s	.updateTimer
		bset	#1,render_flags(a1)

	.updateTimer:
		move.b	d1,(Disable_A_button_flag).w

	.checkHammerRush:
		tst.b	double_jump_property(a0)
		beq.s	Amy_CheckMoves_Return
		tst.b	double_jump_flag(a0)
		bne.s	Amy_CheckMoves_Return
		cmpi.b	#$1D,anim(a0)
		bne.s	.cancel
		subq.b	#1,double_jump_property(a0)
		beq.s	.done
		move.b	angle(a0),d0
		addi.b	#$30,d0
		bmi.s	.done
		cmpi.b	#$60,d0
		bhi.s	.done
		move.b	(Ctrl_1_held_logical).w,d0
		move.b	d0,d1
		andi.b	#button_ABC_mask,d1
		beq.s	.done
		andi.b	#button_right_mask|button_left_mask,d0
		beq.s	.setSpeed
		bclr	#Status_Facing,status(a0)
		cmpi.b	#button_right_mask,d0
		beq.s	.setSpeed
		bset	#Status_Facing,status(a0)

	.setSpeed:
		move.w	#-$600,ground_vel(a0)
		bclr	#Status_Push,status(a0)
		btst	#Status_Facing,status(a0)
		bne.s	Amy_CheckMoves_Return
		move.w	#$600,ground_vel(a0)
		rts
; ---------------------------------------------------------------------------

	.done:
		clr.b	anim(a0)

	.cancel:
		clr.b	double_jump_property(a0)
		bclr	#Status_WaterSlide,status_secondary(a0)

Amy_CheckMoves_Return:
		rts
; ---------------------------------------------------------------------------

