		moveq	#0,d0

	.return:
		rts
; ---------------------------------------------------------------------------

	.checkValue:
		moveq	#signextendB($C0),d1
		and.b	d0,d1
		move.w	x_pos(a0),d2
		move.w	y_pos(a0),d3
		cmpi.b	#$80,d1
		beq.s	.normalRadius
		subi.w	#$18,d2
		subi.w	#$18,d3
		moveq	#$30,d4
		moveq	#$30,d5
		bra.s	.checkWidth
; ---------------------------------------------------------------------------

	.normalRadius:
