		subq.w	#(TailsRollHeight-3),d3
		moveq	#$10,d4
		moveq	#(TailsRollHeight-3)*2,d5

	.checkWidth:
		moveq	#2,d6
		bsr.w	Touch_Width
		tst.w	d6
		beq.s	.nextObject
		move.w	(sp)+,d6
		moveq	#0,d0
		rts
