Mighty_HammerDrop:						; Liliam: extra skills - hammer drop
		lea	(Dust_P2).w,a6
		cmpa.w	#Player_1,a0
		bne.s	.createDust
		lea	(Dust).w,a6
		tst.b	(Super_Sonic_Knux_flag).w
		bpl.s	.createDust
		move.w	#$14,(Glide_screen_shake).w

