		clr.w	parent2(a6)
		move.b	#8,routine(a6)
		btst	#Status_OnObj,status(a0)
		beq.s	.bounce
		move.w	interact(a0),parent2(a6)

	.bounce:
		move.l	a1,-(sp)
		movea.w	a0,a1
		moveq	#signextendB(sfx_HammerDrop),d0
