MightyRay_TriangleJump_CheckAttach:				; Liliam: extra skills - triangle jump
		btst	d1,(Skill_options).w
		beq.s	.return
		btst	#button_right,d0
		beq.s	.checkLeft
		bclr	#Status_Facing,render_flags(a0)
		bclr	#Status_Facing,status(a0)
		move.b	lrb_solid_bit(a0),d5
		movem.l	a4-a6,-(sp)
		bsr.w	CheckRightWallDist
		movem.l	(sp)+,a4-a6
		tst.w	d1
		beq.s	.attach

	.return:
		rts
; ---------------------------------------------------------------------------

	.checkLeft:
		btst	#button_left,d0
		beq.s	.return
		bset	#Status_Facing,render_flags(a0)
		bset	#Status_Facing,status(a0)
		move.b	lrb_solid_bit(a0),d5
		movem.l	a4-a6,-(sp)
		bsr.w	CheckLeftWallDist
		movem.l	(sp)+,a4-a6
		tst.w	d1
		bne.s	.return
		addq.w	#1,x_pos(a0)

	.attach:
		addq.w	#4,sp
		move.w	(Camera_min_Y_pos).w,d0
		cmp.w	y_pos(a0),d0
		bgt.s	.return
		addq.w	#4,sp
		clr.w	y_pos+2(a0)
		tst.b	(Reverse_gravity_flag).w
		bne.s	.activate
		subi.l	#$2000,y_pos(a0)

	.activate:
		move.b	#$20,double_jump_property(a0)
		move.b	#3,object_control(a0)
		bclr	#Status_Roll,status(a0)
		clr.b	(Ctrl_1_pressed_logical).w
		clr.b	prev_anim(a0)
		clr.b	jumping(a0)
		clr.w	x_vel(a0)
		move.w	#$40,y_vel(a0)
		move.w	x_pos(a0),x_pos+2(a0)
		move.w	y_pos(a0),ground_vel(a0)
		move.b	#$EA,mapping_frame(a0)
		bsr.w	Sonic_Load_PLC_Extra
		moveq	#signextendB(sfx_Grab),d0
		jmp	(Play_SFX).l
; ---------------------------------------------------------------------------

MightyRay_TriangleJump:						; Liliam: extra skills - triangle jump
		move.w	x_pos(a0),d0
		cmp.w	x_pos+2(a0),d0
		bne.s	.detach
		move.w	y_pos(a0),d0
		cmp.w	ground_vel(a0),d0
		bne.s	.detach
		jsr	(MoveSprite_TestGravity2).l
		bsr.w	SonicKnux_DoLevelCollision
		btst	#Status_InAir,status(a0)
		beq.s	.return
		move.w	y_pos(a0),ground_vel(a0)
		subq.b	#1,double_jump_property(a0)
		beq.s	.detach
		move.b	(Ctrl_1_pressed_logical).w,d0
		andi.b	#button_ABC_mask,d0
		beq.s	.return
		move.b	(Ctrl_1_held_logical).w,d0
		andi.w	#button_up_mask|button_down_mask|button_left_mask|button_right_mask,d0
		beq.s	.noInput
		cmpi.b	#$B,d0
		blo.s	.checkUp

	.noInput:
		moveq	#7,d0

	.checkFlip:
		btst	#Status_Facing,status(a0)
		bne.s	.lookup
		moveq	#3,d0

	.lookup:
		lsl.w	#2,d0
		lea	MightyRay_TriangleJumpSpeeds-4(pc,d0.w),a1
		move.w	(a1)+,x_vel(a0)
		move.w	(a1)+,y_vel(a0)
		move.b	#1,jumping(a0)
		btst	#Status_Underwater,status(a0)
		beq.s	.detach
		asr.w	#1,x_vel(a0)
		asr.w	#1,y_vel(a0)

	.detach:
		bset	#Status_Roll,status(a0)
		clr.b	double_jump_property(a0)
		clr.b	object_control(a0)
		clr.w	x_pos+2(a0)
		clr.w	ground_vel(a0)

	.return:
		rts
; ---------------------------------------------------------------------------

	.checkUp:
		btst	#button_up,d0
		bne.s	.lookup
		bset	#Status_Facing,status(a0)
		bne.s	.checkLeft
		btst	#button_right,d0
		beq.s	.lookup
		moveq	#5,d0
		bra.s	.lookup
; ---------------------------------------------------------------------------

	.checkLeft:
		btst	#button_left,d0
		beq.s	.lookup
		moveq	#9,d0
		bra.s	.lookup
; ---------------------------------------------------------------------------
MightyRay_TriangleJumpSpeeds:					; Liliam: extra skills - triangle jump
		dc.w      0, -$600	; 01: up
		dc.w      0,  $400	; 02: down
		dc.w  -$400, -$380	; 03: no input
		dc.w  -$700,     0	; 04: left
		dc.w  -$500, -$600	; 05: left + up
		dc.w  -$700,  $400	; 06: left + down
		dc.w   $400, -$380	; 07: no input
		dc.w   $700,     0	; 08: right
		dc.w   $500, -$600	; 09: right + up
		dc.w   $700,  $400	; 10: right + down
; ---------------------------------------------------------------------------

Obj_Ray:							; Liliam: add extra characters
		move.l	#.main,(a0)
		move.b	#5,character_id(a0)

	.main:
		cmpa.w	#Player_1,a0
		bne.s	.player2
		lea	(Max_speed).w,a4
		lea	(Distance_from_top).w,a5
		lea	(Dust).w,a6
		tst.w	(Debug_placement_mode).w
		beq.s	Ray_Normal
		bmi.w	Sonic_FrameCycle
		jmp	(DebugMode).l
; ---------------------------------------------------------------------------

	.player2:
		lea	(Max_speed_P2).w,a4
		lea	(Distance_from_top_P2).w,a5
		lea	(Dust_P2).w,a6

Ray_Normal:
		move.l	#Map_Ray,mappings(a0)
		bsr.w	loc_10ADE
		tst.b	double_jump_property(a0)
		bne.w	MightyRay_TriangleJump

Ray_CheckMoves_Return:
		rts
; ---------------------------------------------------------------------------
ability_timer = $2D
glide_speed_cap = $28
glide_anim_timer = $30
glide_sfx_timer = $31
AirGlide_Dive = 1
AirGlide_AnimUp = 0

Ray_CheckMoves:							; Liliam: extra skills - air glide (credit: Rubberduckycooly)
		move.b	(Ctrl_1_held_logical).w,d0
		andi.b	#button_right_mask|button_left_mask,d0
		bne.s	.activate
		btst	#button_up,(Ctrl_1_held_logical).w
		bne.s	Ray_CheckMoves_Return

	.activate:
		moveq	#Skill_RayWallJump,d1
		bsr.w	MightyRay_TriangleJump_CheckAttach
		bclr	#Status_Roll,status(a0)
		st	double_jump_flag(a0)
		move.w	#$300,glide_anim_timer(a0)
		move.b	#$F8,mapping_frame(a0)
		addq.w	#4,sp

		move.w	x_vel(a0),d0
		move.w	d0,d1
		asr.w	#3,d1
		sub.w	d1,d0
		move.w	d0,x_vel(a0)
		btst	#Status_Facing,status(a0)
		beq.s	.calcSpeed
		neg.w	d0

	.calcSpeed:
		move.w	#$300,d1
		cmp.w	d0,d1
		ble.s	.checkControls
		btst	#Status_Underwater,status(a0)
		beq.s	.setSpeed
		move.w	#$180,d1
		cmp.w	d0,d1
		ble.s	.checkControls

	.setSpeed:
		move.w	d1,x_vel(a0)
		btst	#Status_Facing,status(a0)
		beq.s	.checkControls
		neg.w	x_vel(a0)

	.checkControls:
		bsr.w	Ray_AirGlide_CheckControls
		clr.w	ground_vel(a0)
		btst	#AirGlide_AnimUp,double_jump_flag(a0)
		beq.s	.done
		bclr	#AirGlide_Dive,double_jump_flag(a0)
		asr.w	#1,x_vel(a0)
		move.w	x_vel(a0),d0
		bmi.s	.calcAbilitySpeed
		neg.w	d0

	.calcAbilitySpeed:
		move.w	d0,d1
		move.w	d0,d2
		asr.w	#1,d0
		asr.w	#2,d1
		asr.w	#4,d2
		add.w	d2,d0
		add.w	d1,d0
		btst	#Status_Underwater,status(a0)
		beq.s	.setAbilitySpeed
		asr.w	#1,d0

	.setAbilitySpeed:
		move.w	d0,ground_vel(a0)
		cmpi.w	#$400,d0
		ble.s	.done
		move.w	#$400,ground_vel(a0)	; This seems impossible

	.done:
		asr.w	#1,y_vel(a0)
		move.b	#$40,angle(a0)
		move.b	#$40,ability_timer(a0)
		move.w	x_vel(a0),glide_speed_cap(a0)
		bpl.s	.return
		neg.w	glide_speed_cap(a0)

	.return:
		rts
; ---------------------------------------------------------------------------

Ray_AirGlide:							; Liliam: extra skills - air glide (credit: Rubberduckycooly)
		btst	#AirGlide_Dive,double_jump_flag(a0)
		bne.s	.isDiving
		cmpi.b	#$70,angle(a0)
		bge.s	.checkAbilitySpeed
		addq.b	#8,angle(a0)
		bra.s	.checkAbilitySpeed
; ---------------------------------------------------------------------------

	.isDiving:
		cmpi.b	#$10,angle(a0)
		ble.s	.checkAbilitySpeed
		subq.b	#8,angle(a0)

	.checkAbilitySpeed:
		move.w	ground_vel(a0),d0
		beq.s	.noAbilitySpeed
		move.w	d0,d1
		asr.w	#1,d1
		btst	#Status_Underwater,status(a0)
		bne.s	.setYSpeed
		asr.w	#1,d1

	.setYSpeed:
		add.w	d1,y_vel(a0)
		cmp.w	y_vel(a0),d0
		ble.s	.checkLimit
		move.w	d0,y_vel(a0)
		clr.w	ground_vel(a0)
		bra.s	.checkLimit
; ---------------------------------------------------------------------------

	.noAbilitySpeed:
		moveq	#0,d0
		move.b	angle(a0),d0
		lsl.w	#1,d0
		move.b	angle(a0),d0		; Technically this could be lsr.b #2,d0
		asr.b	#1,d0			; because angle is never negative
		jsr	(GetSineCosine_Fine).l
		lsl.w	#1,d1
		moveq	#$18,d0
		btst	#Status_Underwater,status(a0)
		bne.s	.applyGravity
		moveq	#$38,d0

	.applyGravity:
		muls.w	d0,d1
		moveq	#9,d0
		asr.w	d0,d1
		add.w	d1,y_vel(a0)

	.checkLimit:
		cmpi.w	#-$600,y_vel(a0)
		bge.s	.checkLimit2
		move.w	#-$600,y_vel(a0)

	.checkLimit2:
		btst	#AirGlide_Dive,double_jump_flag(a0)
		bne.s	.calcAcceleration
		cmpi.w	#$100,y_vel(a0)
		ble.s	.calcAcceleration
		move.w	y_vel(a0),d0
		asr.w	#2,d0
		sub.w	d0,y_vel(a0)

	.calcAcceleration:
		moveq	#$50,d0
		sub.b	angle(a0),d0
		jsr	(GetSineCosine).l
		muls.w	#22,d0
		asr.l	#8,d0
		move.w	glide_speed_cap(a0),d1
		move.w	y_vel(a0),d2
		bgt.s	.isFalling
		sub.w	d0,glide_speed_cap(a0)
		cmpi.w	#$400,d1
		bgt.s	.adjustAcceleration
		move.w	#$400,d1
		bra.s	.setSpeedCap
; ---------------------------------------------------------------------------

	.isFalling:
		cmp.w	d2,d1
		bge.s	.adjustAcceleration
		move.w	d2,d1
		asr.w	#6,d2
		sub.w	d2,d1

	.setSpeedCap:
		move.w	d1,glide_speed_cap(a0)

	.adjustAcceleration:
		btst	#Status_Underwater,status(a0)
		beq.s	.checkDirection
		asr.w	#1,d0

	.checkDirection:
		tst.w	x_vel(a0)
		beq.s	.checkControls		; This seems impossible
		btst	#Status_Facing,status(a0)
		beq.s	.facingRight
		neg.w	d1
		sub.w	d0,x_vel(a0)
		cmpi.w	#-$100,x_vel(a0)
		ble.s	.checkLimit3
		move.w	#-$100,x_vel(a0)

	.checkLimit3:
		cmp.w	x_vel(a0),d1
		ble.s	.checkControls
		move.w	d1,x_vel(a0)
		bra.s	.checkControls
; ---------------------------------------------------------------------------

	.facingRight:
		add.w	d0,x_vel(a0)
		cmpi.w	#$100,x_vel(a0)
		bge.s	.checkLimit4
		move.w	#$100,x_vel(a0)

	.checkLimit4:
		cmp.w	x_vel(a0),d1
		bge.s	.checkControls
		move.w	d1,x_vel(a0)

	.checkControls:
		bsr.w	Ray_AirGlide_CheckControls
		btst	#AirGlide_AnimUp,double_jump_flag(a0)
		bne.s	.checkStartSwoop
		cmpi.b	#$70,angle(a0)
		bne.w	.done
		btst	#AirGlide_Dive,double_jump_flag(a0)
		bne.w	.done
		bset	#AirGlide_Dive,double_jump_flag(a0)
		clr.w	ground_vel(a0)
		bra.w	.done
; ---------------------------------------------------------------------------

	.checkStartSwoop:
		cmpi.b	#$10,angle(a0)
		bne.s	.done
		btst	#AirGlide_Dive,double_jump_flag(a0)
		beq.s	.done
		bclr	#AirGlide_Dive,double_jump_flag(a0)
		cmpi.w	#$280,y_vel(a0)
		bgt.s	.updateAbilitySpeed
		cmpi.b	#$40,ability_timer(a0)
		beq.s	.updateAbilitySpeed
		btst	#Status_Underwater,status(a0)
		beq.s	.done
		cmpi.w	#$180,y_vel(a0)
		ble.s	.done

	.updateAbilitySpeed:
		move.w	x_vel(a0),d0
		bmi.s	.calcAbilitySpeed
		neg.w	d0

	.calcAbilitySpeed:
		move.w	d0,d1
		move.w	d0,d2
		asr.w	#1,d0
		asr.w	#2,d1
		asr.w	#4,d2
		add.w	d2,d0
		add.w	d1,d0
		moveq	#0,d1
		move.b	ability_timer(a0),d1
		lsl.w	#2,d1
		muls.w	d1,d0
		asr.l	#8,d0
		btst	#Status_Underwater,status(a0)
		beq.s	.setAbilitySpeed
		move.w	d0,d1
		asr.w	#1,d1
		asr.w	#3,d0
		add.w	d1,d0

	.setAbilitySpeed:
		move.w	d0,ground_vel(a0)
		cmpi.b	#4,ability_timer(a0)
		ble.s	.checkLimit5
		subq.b	#8,ability_timer(a0)

	.checkLimit5:
		cmpi.w	#-$600,ground_vel(a0)
		bge.s	.done
		move.w	#-$600,ground_vel(a0)

	.done:
		bsr.w	Player_LevelBound
		jsr	(MoveSprite_TestGravity2).l
		bset	#Status_Roll,status(a0)
		bsr.w	SonicKnux_DoLevelCollision
		bclr	#Status_Roll,status(a0)
		beq.s	.return
		tst.w	x_vel(a0)
		beq.s	.hitWall
		move.b	(Ctrl_1_held_logical).w,d0
		andi.b	#button_ABC_mask,d0
		beq.s	.cancelGlide
		move.w	(Camera_min_Y_pos).w,d0
		cmp.w	y_pos(a0),d0
		ble.s	.return

	.cancelGlide:
		clr.b	prev_anim(a0)
		tst.b	double_jump_flag(a0)
		beq.s	.return
		move.b	#2,double_jump_flag(a0)
		cmpi.b	#2,anim(a0)
		bne.s	.return
		bset	#Status_Roll,status(a0)
		tst.b	(Super_Sonic_Knux_flag).w
		bpl.s	.return
		clr.b	double_jump_flag(a0)

	.return:
		rts
; ---------------------------------------------------------------------------

	.hitWall:
		bsr.s	.cancelGlide
		bsr.s	.setUpTriangleJump
		rts
; ---------------------------------------------------------------------------

	.setUpTriangleJump:
		moveq	#Skill_RayWallJump,d1
		moveq	#button_left_mask,d0
		btst	#Status_Facing,status(a0)
		bne.s	.checkAttach
		moveq	#button_right_mask,d0

	.checkAttach:
		bsr.w	MightyRay_TriangleJump_CheckAttach
		rts
; ---------------------------------------------------------------------------

Ray_AirGlide_TouchFloor:					; Liliam: extra skills - air glide
		clr.b	double_jump_flag(a0)
		clr.b	anim(a0)
		rts
; ---------------------------------------------------------------------------

Ray_AirGlide_CheckControls:					; Liliam: extra skills - air glide
		move.b	#1,anim_frame_timer(a0)
		move.b	(Ctrl_1_held_logical).w,d0
		andi.b	#button_right_mask|button_left_mask,d0
		beq.s	.setAnimation
		lsr.b	#button_right-AirGlide_AnimUp,d0
		btst	#Status_Facing,status(a0)
		beq.s	.checkUpdate
		eori.b	#1<<AirGlide_AnimUp,d0

	.checkUpdate:
		move.b	double_jump_flag(a0),d1
		ori.b	#1<<AirGlide_AnimUp,d1
		eor.b	d1,d0
		cmp.b	double_jump_flag(a0),d0
		beq.s	.setAnimation
		move.b	d0,double_jump_flag(a0)
		clr.w	glide_anim_timer(a0)
		cmpi.b	#$F8-5,mapping_frame(a0)
		bne.s	.checkLimit
		addq.b	#1,mapping_frame(a0)
		bra.s	.setAnimation
; ---------------------------------------------------------------------------

	.checkLimit:
		cmpi.b	#$F8+5,mapping_frame(a0)
		bne.s	.setAnimation
		subq.b	#1,mapping_frame(a0)

	.setAnimation:
		btst	#AirGlide_AnimUp,double_jump_flag(a0)
		beq.s	.isDiving
		moveq	#signextendB(sfx_WindQuiet),d0
		subq.b	#1,glide_anim_timer(a0)
		bpl.s	.checkPlaySFX
		subq.b	#1,mapping_frame(a0)
		cmpi.b	#$F8-5,mapping_frame(a0)
		bhs.s	.loadPLC
		addq.b	#2,mapping_frame(a0)
		bra.s	.loadPLC
; ---------------------------------------------------------------------------

	.isDiving:
		moveq	#signextendB(sfx_WindLoud),d0
		subq.b	#1,glide_anim_timer(a0)
		bpl.s	.checkPlaySFX
		addq.b	#1,mapping_frame(a0)
		cmpi.b	#$F8+5,mapping_frame(a0)
		bls.s	.loadPLC
		subq.b	#2,mapping_frame(a0)

	.loadPLC:
		move.w	d0,-(sp)
		bsr.w	Sonic_Load_PLC_Extra
		move.w	(sp)+,d0
		move.b	#2,glide_anim_timer(a0)

	.checkPlaySFX:
		btst	#Status_Underwater,status(a0)
		beq.s	.playSFX
		clr.b	glide_sfx_timer(a0)

	.return:
		rts
; ---------------------------------------------------------------------------

	.playSFX:
		subq.b	#1,glide_sfx_timer(a0)
		bpl.s	.return
		move.b	#$F,glide_sfx_timer(a0)
		jmp	(Play_SFX).l
; ---------------------------------------------------------------------------

Obj_MetalSonic:							; Liliam: add extra characters
		move.l	#.main,(a0)
		move.b	#6,character_id(a0)
		move.l	#Obj_BoostMode,(Tails_tails_2P).w
		move.w	a0,(Tails_tails_2P+parent2).w

	.main:
		cmpa.w	#Player_1,a0
		bne.s	.player2
		lea	(Max_speed).w,a4
		lea	(Distance_from_top).w,a5
		lea	(Dust).w,a6
		tst.w	(Debug_placement_mode).w
		beq.s	MetalSonic_Normal
		bmi.w	Sonic_FrameCycle
		jmp	(DebugMode).l
; ---------------------------------------------------------------------------

	.player2:
		lea	(Max_speed_P2).w,a4
		lea	(Distance_from_top_P2).w,a5
		lea	(Dust_P2).w,a6

MetalSonic_Normal:
		move.l	#Map_MetalSonic,mappings(a0)
		bra.w	loc_10ADE
; ---------------------------------------------------------------------------

MetalSonic_CheckMoves:
		move.b	#2,double_jump_flag(a0)			; Liliam: extra skills - boost mode
		rts
; ---------------------------------------------------------------------------

Obj_Sonic:
		cmpa.w	#Player_1,a0					; Liliam: Encore mode - pick RAM variables by SST
		bne.s	loc_10AD8					;
		lea	(Max_speed).w,a4
		lea	(Distance_from_top).w,a5
		lea	(Dust).w,a6
		tst.w	(Debug_placement_mode).w
		beq.s	Sonic_Normal
		bmi.s	Sonic_FrameCycle			; Liliam: debug - move frame cycling mode to negative
;		cmpi.b	#1,(Debug_placement_type).w		;
;		beq.s	loc_10AD8				;
		jmp	(DebugMode).l				;
; ---------------------------------------------------------------------------

Sonic_FrameCycle:
		; By this point, we're assuming you're in frame cycling mode
		btst	#button_B,(Ctrl_1_pressed).w
		beq.s	loc_10ABC
		move.w	#0,(Debug_placement_mode).w
		jsr	(Debug_Reset_HUD).l				; Liliam: HUD - reset on exiting debug frame cycling mode

loc_10ABC:
		addq.b	#1,mapping_frame(a0)
		cmpi.b	#$FD,mapping_frame(a0)			; Liliam: simplify player anim selection
;		cmpi.b	#$FB,mapping_frame(a0)			;
		blo.s	loc_10ACE
		move.b	#0,mapping_frame(a0)

loc_10ACE:
		bsr.w	Sonic_Load_PLC_Extra			; Liliam: add extra characters
;		bsr.w	Sonic_Load_PLC				;
		jmp	(Draw_Sprite).l
; ---------------------------------------------------------------------------

loc_10AD8:
		lea	(Max_speed_P2).w,a4				; Liliam: Encore mode - pick RAM variables by SST
		lea	(Distance_from_top_P2).w,a5			;
		lea	(Dust_P2).w,a6					;
;		jmp	(DebugMode).l					;

Sonic_Normal:
		move.l	#Map_SuperSonic,mappings(a0)		; Liliam: Encore mode - change character item
		tst.b	(Super_Sonic_Knux_flag).w		;
		bne.s	loc_10ADE				;
		move.l	#Map_Sonic,mappings(a0)			;

loc_10ADE:
		moveq	#0,d0
		move.b	routine(a0),d0
		move.w	Sonic_Index(pc,d0.w),d1
		jmp	Sonic_Index(pc,d1.w)
; ---------------------------------------------------------------------------
Sonic_Index:
		dc.w Sonic_Init-Sonic_Index
		dc.w Sonic_Control-Sonic_Index
		dc.w Sonic_Hurt-Sonic_Index
		dc.w Sonic_Dead-Sonic_Index
		dc.w Sonic_GameOver-Sonic_Index
		dc.w Sonic_Drown-Sonic_Index			; Liliam: Encore mode - expand player routines
		dc.w Sonic_Dead-Sonic_Index			;
		dc.w Sonic_GameOver-Sonic_Index			;
;		dc.w Sonic_Respawn-Sonic_Index			;
;		dc.w Sonic_Drown-Sonic_Index			;
; ---------------------------------------------------------------------------

Sonic_Init:
		addq.b	#2,routine(a0)
		move.b	#$13,y_radius(a0)
		move.b	#9,x_radius(a0)
		move.b	#$13,default_y_radius(a0)
		move.b	#9,default_x_radius(a0)
;		move.l	#Map_Sonic,mappings(a0)			; Liliam: Encore mode - change character item
		move.w	#$100,priority(a0)
		move.b	#$18,width_pixels(a0)
		move.b	#$18,height_pixels(a0)
		move.b	#4,render_flags(a0)
;		move.b	#0,character_id(a0)			; Liliam: add extra characters
		move.w	#$600,Max_speed-Max_speed(a4)
		move.w	#$C,Acceleration-Max_speed(a4)
		move.w	#$80,Deceleration-Max_speed(a4)
		move.w	art_tile(a0),d0					; Liliam: Encore mode - pick art_tile by SST
;		tst.b	(Last_star_post_hit).w				;
;		bne.s	Sonic_Init_Continued				;
		move.w	#ArtTile_Player_1,art_tile(a0)
		cmpa.w	#Player_1,a0					;
		bne.s	.player2					;
		tst.b	(Last_star_post_hit).w				;
		bne.s	.checkPriority					;
		move.b	#$C,top_solid_bit(a0)
		move.b	#$D,lrb_solid_bit(a0)

	.checkPriority:
;		cmpi.b	#2,(Special_bonus_entry_flag).w			;
;		beq.s	Sonic_Init_Continued				;
;		move.w	x_pos(a0),(Saved_X_pos).w			;
;		move.w	y_pos(a0),(Saved_Y_pos).w			;
;		move.w	art_tile(a0),(Saved_art_tile).w			;
;		move.w	top_solid_bit(a0),(Saved_solid_bits).w		;
		tst.w	d0						;
		bmi.s	.setPriority					;
		bra.s	Sonic_Init_Continued				;
; ---------------------------------------------------------------------------

	.player2:
		move.w	(Player_1+art_tile).w,d0			;
		andi.w	#drawing_mask,d0				;
		cmpi.w	#ArtTile_Player_1,d0				;
		bne.s	.checkPriority2					;
		move.w	#ArtTile_Player_2,art_tile(a0)			;

	.checkPriority2:
		move.w	(Player_1+top_solid_bit).w,top_solid_bit(a0)	;
		tst.w	(Player_1+art_tile).w				;
		bpl.s	Sonic_Init_Continued				;

	.setPriority:
		ori.w	#high_priority,art_tile(a0)			;

Sonic_Init_Continued:
		move.b	#0,flips_remaining(a0)
		move.b	#4,flip_speed(a0)
		move.b	#0,(Super_Sonic_Knux_flag).w
		move.b	#30,air_left(a0)
		bra.w	Reset_Player_Position_Array		; Liliam: reset array to actual player position
;		subi.w	#$20,x_pos(a0)				;
;		addi.w	#4,y_pos(a0)				;
;		bsr.w	Reset_Player_Position_Array		;
;		addi.w	#$20,x_pos(a0)				;
;		subi.w	#4,y_pos(a0)				;
;		rts						;

; ---------------------------------------------------------------------------
; Normal state for Sonic
; ---------------------------------------------------------------------------

Sonic_Control:
		cmpa.w	#Player_1,a0				; Liliam: Encore mode - block debug mode for player 2
		bne.s	loc_10BF0.controlP2			;
		tst.w	(Debug_mode_flag).w		; is debug cheat enabled?
		beq.s	loc_10BF0			; if not, branch
		tst.b	(Disable_A_button_flag).w		; Liliam: Encore mode - disable A button
		bne.s	loc_10BCE				;
		tst.b	(Super_ready_HUD_flag).w		;
		bmi.s	loc_10BCE				;
		bclr	#button_A,(Ctrl_1_pressed).w	; is button A pressed?
		beq.s	loc_10BCE			; if not, branch
		eori.b	#1,(Reverse_gravity_flag).w	; toggle reverse gravity

loc_10BCE:
		btst	#button_B,(Ctrl_1_pressed).w	; is button B pressed?
		beq.s	loc_10BF0			; if not, branch
		move.w	#1,(Debug_placement_mode).w	; change Sonic into a ring/item
		clr.b	(Ctrl_1_locked).w		; unlock control
		btst	#button_C,(Ctrl_1_held).w	; was button C held before pressing B?
		beq.s	locret_10BEE			; if not, branch
		st	(Debug_placement_mode).w		; Liliam: debug - move frame cycling mode to negative
;		move.w	#2,(Debug_placement_mode).w		;

locret_10BEE:
		rts
; ---------------------------------------------------------------------------

loc_10BF0:
		tst.b	(Ctrl_1_locked).w		; are controls locked?
		bne.s	loc_10BFC			; if yes, branch
		move.w	(Ctrl_1).w,(Ctrl_1_logical).w	; copy new held buttons, to enable joypad control

		tst.b	(Disable_A_button_flag).w		; Liliam: Encore mode - disable A button
		beq.s	loc_10BFC				;
		cmpi.b	#8,anim(a0)				;
		blo.s	.disable				;
		cmpi.b	#$A,anim(a0)				;
		blo.s	loc_10BFC				;

	.disable:
		andi.w	#$BFBF,(Ctrl_1_logical).w		;
		bra.s	loc_10BFC				;
; ---------------------------------------------------------------------------

	.controlP2:
		move.w	(Ctrl_1_logical).w,-(sp)		; Liliam: Encore mode - use player 2 controls for player 2
		tst.b	(Ctrl_2_locked).w			;
		bmi.s	.controlLock				;
		bne.s	.controlCPU				;
		move.w	(Ctrl_2).w,(Ctrl_2_logical).w		;

	.controlCPU:
		bsr.w	Tails_CPU_Control			;

	.controlLock:
		move.w	(Ctrl_2_logical).w,(Ctrl_1_logical).w	;

loc_10BFC:
		btst	#0,object_control(a0)	; is Sonic interacting with another object that holds him in place or controls his movement somehow?
		beq.s	loc_10C0C		; if yes, branch to skip Sonic's control
		move.b	#0,double_jump_flag(a0)
		tst.b	(Flying_carrying_Sonic_flag).w		; Liliam: bugfix - release player from Tails
		beq.s	loc_10C26				;
;		bra.s	loc_10C26				;
		move.w	a0,d0					;
		eori.b	#$4A,d0					;
		movea.w	d0,a1					;
		tst.b	double_jump_flag(a1)			;
		bne.s	loc_10C26				;
		bset	#Status_InAir,status(a0)		;
		clr.b	object_control(a0)			;
		clr.w	(Flying_carrying_Sonic_flag).w		;

loc_10C0C:
		movem.l	a4-a6,-(sp)
		moveq	#0,d0
		move.b	status(a0),d0
		andi.w	#6,d0
		move.w	Sonic_Modes(pc,d0.w),d1
		jsr	Sonic_Modes(pc,d1.w)	; run Sonic's movement control code
		movem.l	(sp)+,a4-a6

loc_10C26:
		cmpi.w	#-$100,(Camera_min_Y_pos).w	; is vertical wrapping enabled?
		bne.s	loc_10C36			; if not, branch
		move.w	(Screen_Y_wrap_value).w,d0
		and.w	d0,y_pos(a0)			; perform wrapping of Sonic's y position

loc_10C36:
		bsr.s	Sonic_Display
		bsr.w	SonicKnux_SuperHyper
		bsr.w	Player_RecordPos
		bsr.w	Sonic_Water
		move.b	(Primary_Angle).w,next_tilt(a0)
		move.b	(Secondary_Angle).w,tilt(a0)
		tst.b	WindTunnel_flag-Distance_from_top(a5)		; Liliam: Encore mode - pick RAM variables by SST
;		tst.b	(WindTunnel_flag).w				;
		beq.s	loc_10C62
		tst.b	anim(a0)
		bne.s	loc_10C62
		move.b	prev_anim(a0),anim(a0)

loc_10C62:
		btst	#1,object_control(a0)
		bne.s	loc_10C7E
		bsr.w	Animate_Sonic_Extra			; Liliam: add extra characters
;		bsr.w	Animate_Sonic				;
;		tst.b	(Reverse_gravity_flag).w		;
;		beq.s	loc_10C7A				;
;		eori.b	#2,render_flags(a0)			;

;loc_10C7A:
		bsr.w	Sonic_Load_PLC_Extra			;
;		bsr.w	Sonic_Load_PLC				;

loc_10C7E:
		move.b	object_control(a0),d0
		andi.b	#$A0,d0
		bne.s	locret_10C8E
		jsr	(TouchResponse).l

locret_10C8E:
		cmpa.w	#Player_1,a0				; Liliam: Encore mode - use player 2 controls for player 2
		beq.s	.return					;
		move.w	(sp)+,(Ctrl_1_logical).w		;

	.return:
		rts
; ---------------------------------------------------------------------------
; secondary states under state Sonic_Control
Sonic_Modes:
		dc.w Sonic_MdNormal-Sonic_Modes
		dc.w Sonic_MdAir-Sonic_Modes
		dc.w Sonic_MdRoll-Sonic_Modes
		dc.w Sonic_MdJump-Sonic_Modes

; =============== S U B R O U T I N E =======================================


Sonic_Display:
		move.b	invulnerability_timer(a0),d0
		beq.s	loc_10CA6
		subq.b	#1,invulnerability_timer(a0)
		lsr.b	#3,d0
		bcc.s	Sonic_ChkInvin

loc_10CA6:
		jsr	(Draw_Sprite).l

Sonic_ChkInvin:
;		btst	#Status_Invincible,status_secondary(a0)	; Liliam: bugfix - clear super form on death
;		beq.s	Sonic_ChkShoes				;
		tst.b	invincibility_timer(a0)
		beq.s	Sonic_ChkShoes
		btst	#Status_Invincible,status_secondary(a0)	;
		beq.s	loc_10CC4				;
		move.b	(Level_frame_counter+1).w,d0
		andi.b	#7,d0
		bne.s	Sonic_ChkShoes

loc_10CC4:
		subq.b	#1,invincibility_timer(a0)
		bne.s	Sonic_ChkShoes
		tst.b	(Boss_flag).w
		bne.s	Sonic_RmvInvin
		tst.b	(Encore_mode).w				; Liliam: no drowning music in Encore mode
		bne.s	loc_10CD8				;
		cmpi.b	#12,air_left(a0)
		blo.s	Sonic_RmvInvin

loc_10CD8:
		move.w	(Current_music).w,d0
		jsr	(Play_Music).l

Sonic_RmvInvin:
		bclr	#Status_Invincible,status_secondary(a0)

Sonic_ChkShoes:
		btst	#Status_SpeedShoes,status_secondary(a0)
		beq.s	Sonic_ExitChk
		tst.b	speed_shoes_timer(a0)
		beq.s	Sonic_ExitChk
		move.b	(Level_frame_counter+1).w,d0
		andi.b	#7,d0
		bne.s	Sonic_ExitChk
		subq.b	#1,speed_shoes_timer(a0)
		bne.s	Sonic_ExitChk
		tst.w	(Competition_mode).w
		bne.s	Sonic_ChkShoesCompetition
		move.w	#$A00,Max_speed-Max_speed(a4)		; Liliam: add extra characters
		tst.b	character_id(a0)			;
		beq.s	loc_10D0C				;
		move.w	#$800,Max_speed-Max_speed(a4)		;

loc_10D0C:
		tst.b	(Super_Sonic_Knux_flag).w		; Liliam: bugfix - player speeds fix
		bne.s	loc_10D32				;
		move.w	#$600,Max_speed-Max_speed(a4)
		move.w	#$C,Acceleration-Max_speed(a4)
		move.w	#$80,Deceleration-Max_speed(a4)
;		tst.b	(Super_Sonic_Knux_flag).w		;
;		beq.s	loc_10D32				;
;		move.w	#$A00,Max_speed-Max_speed(a4)		;
;		move.w	#$30,Acceleration-Max_speed(a4)		;
;		move.w	#$100,Deceleration-Max_speed(a4)	;

loc_10D32:
		bclr	#Status_SpeedShoes,status_secondary(a0)
		moveq	#0,d0
		jmp	(Change_Music_Tempo).l
; ---------------------------------------------------------------------------

Sonic_ExitChk:
		rts
; ---------------------------------------------------------------------------

Sonic_ChkShoesCompetition:
		lea	(Character_Speeds).l,a1
		moveq	#0,d0
		move.b	character_id(a0),d0
		lsl.w	#3,d0
		lea	(a1,d0.w),a1
		move.w	(a1)+,Max_speed-Max_speed(a4)
		move.w	(a1)+,Acceleration-Max_speed(a4)
		move.w	(a1)+,Deceleration-Max_speed(a4)
		bclr	#Status_SpeedShoes,status_secondary(a0)
		rts
; End of function Sonic_Display

; ---------------------------------------------------------------------------
; Subroutine to record Sonic's previous positions for invincibility stars
; and input/status flags for Tails' CPU controls to follow
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Player_RecordPos:
		tst.w	(Competition_mode).w		; are we in Competition mode?
		bne.s	Player_RecordPosCompetition	; if so, branch
		cmpa.w	#Player_1,a0			; is Sonic the sidekick?
		bne.s	locret_10D9E			; if so, branch
		move.w	(Pos_table_index).w,d0
		lea	(Pos_table).w,a1
		lea	(a1,d0.w),a1
		move.w	x_pos(a0),(a1)+			; write location to pos_table
		move.w	y_pos(a0),(a1)+
		addq.b	#4,(Pos_table_index+1).w	; increment index as the post-increments did a1
		lea	(Pos_table_P2).w,a1
		lea	(a1,d0.w),a1
		move.w	(Ctrl_1_logical).w,(a1)+
		move.b	status(a0),(a1)+
		move.b	art_tile(a0),(a1)+

locret_10D9E:
		rts
; ---------------------------------------------------------------------------

Player_RecordPosCompetition:
		cmpa.w	#Player_1,a0			; is object player 1?
		bne.s	Player_RecordPosCompetitionP2	; if not, branch
		move.w	(Pos_table_index).w,d0
		lea	(Pos_table).w,a1
		lea	(a1,d0.w),a1
		move.w	x_pos(a0),(a1)+			; write location to pos_table
		move.w	y_pos(a0),(a1)+
		addq.b	#4,(Pos_table_index+1).w	; increment index as the post-increments did a1
		rts
; ---------------------------------------------------------------------------

Player_RecordPosCompetitionP2:
		move.w	(Pos_table_index_P2).w,d0
		lea	(Pos_table_P2).w,a1
		lea	(a1,d0.w),a1
		move.w	x_pos(a0),(a1)+			; write location to pos_table
		move.w	y_pos(a0),(a1)+
		addq.b	#4,(Pos_table_index_P2+1).w	; increment index as the post-increments did a1
		rts
; End of function Player_RecordPos


; =============== S U B R O U T I N E =======================================


Reset_Player_Position_Array:
		cmpa.w	#Player_1,a0			; is object player 1?
		bne.s	Reset_Player_Position_ArrayP2	; if not, branch
		lea	(Pos_table).w,a1
		lea	(Pos_table_P2).w,a2
		move.w	#bytesToLcnt(Pos_table_end-Pos_table),d0
		move.w	status(a0),d1				; Liliam: face left at left-facing star posts
		andi.l	#1<<Status_Facing<<8,d1			;

loc_10DEC:
		move.w	x_pos(a0),(a1)+
		move.w	y_pos(a0),(a1)+
		move.l	d1,(a2)+				;
;		move.l	#0,(a2)+				;
		dbf	d0,loc_10DEC
		move.w	#0,(Pos_table_index).w

Reset_Player_Position_ArrayP2:
		tst.w	(Competition_mode).w	; are we in Competition mode?
		beq.s	locret_10E24		; if not, branch
		lea	(Pos_table_P2).w,a1
		move.w	#bytesToLcnt(Pos_table_P2_end-Pos_table_P2),d0

loc_10E12:
		move.w	x_pos(a0),(a1)+
		move.w	y_pos(a0),(a1)+
		dbf	d0,loc_10E12
		move.w	#0,(Pos_table_index_P2).w

locret_10E24:
		rts
; End of function Reset_Player_Position_Array

; ---------------------------------------------------------------------------
; Subroutine for Sonic when he's underwater
; ---------------------------------------------------------------------------

; =============== S U B R O U T I N E =======================================


Sonic_Water:
		tst.b	(Water_flag).w	; does level have water?
		bne.s	Sonic_InWater	; if yes, branch

locret_10E2C:
		rts
; ---------------------------------------------------------------------------

Sonic_InWater:
		move.w	(Water_level).w,d0
		cmp.w	y_pos(a0),d0	; is Sonic above the water?
		bge.s	Sonic_OutWater	; if yes, branch

		bset	#Status_Underwater,status(a0)	; set underwater flag
		bne.s	locret_10E2C	; if already underwater, branch

		addq.b	#1,(Water_entered_counter).w
		movea.l	a0,a1
		bsr.w	Player_ResetAirTimer
		lea	Breathing_bubbles-Dust(a6),a1			; Liliam: Encore mode - pick RAM variables by SST
		move.l	#Obj_AirCountdown,(a1)				;
		move.b	#$81,subtype(a1)				;
		move.w	a0,parent(a1)					;
;		move.l	#Obj_AirCountdown,(Breathing_bubbles).w		;
;		move.b	#$81,(Breathing_bubbles+subtype).w		;
;		move.l	a0,(Breathing_bubbles+objoff_40).w		;

;		move.w	#$300,Max_speed-Max_speed(a4)		; Liliam: bugfix - player speeds fix
;		move.w	#6,Acceleration-Max_speed(a4)		;
;		move.w	#$40,Deceleration-Max_speed(a4)		;
;		tst.b	(Super_Sonic_Knux_flag).w		;
;		beq.s	loc_10E82				;
;		move.w	#$500,Max_speed-Max_speed(a4)		;
;		move.w	#$18,Acceleration-Max_speed(a4)		;
;		move.w	#$80,Deceleration-Max_speed(a4)		;

;loc_10E82:
		tst.b	object_control(a0)
		bne.s	locret_10E2C
		asr	x_vel(a0)
		asr	y_vel(a0)		; memory operands can only be shifted one bit at a time
		asr	y_vel(a0)
		beq.s	locret_10E2C
		move.w	#1<<8,anim(a6)		; splash animation, write 1 to anim and clear prev_anim
		move.w	#sfx_Splash,d0
		jmp	(Play_SFX).l
; ---------------------------------------------------------------------------

Sonic_OutWater:
		bclr	#Status_Underwater,status(a0)	; unset underwater flag
		beq.w	locret_10E2C			; if already above water, branch
		addq.b	#1,(Water_entered_counter).w
		movea.l	a0,a1
		bsr.w	Player_ResetAirTimer
;		move.w	#$600,Max_speed-Max_speed(a4)		; Liliam: bugfix - player speeds fix
;		move.w	#$C,Acceleration-Max_speed(a4)		;
;		move.w	#$80,Deceleration-Max_speed(a4)		;
;		tst.b	(Super_Sonic_Knux_flag).w		;
;		beq.s	loc_10EE0				;
;		move.w	#$A00,Max_speed-Max_speed(a4)		;
;		move.w	#$30,Acceleration-Max_speed(a4)		;
;		move.w	#$100,Deceleration-Max_speed(a4)	;

;loc_10EE0:
		cmpi.b	#State_Hurt,routine(a0)	; is Sonic falling back from getting hurt?
		beq.s	loc_10EFC		; if yes, branch
		tst.b	object_control(a0)
		bne.s	loc_10EFC
		move.w	y_vel(a0),d0
		cmpi.w	#-$400,d0
		blt.s	loc_10EFC
		asl	y_vel(a0)

loc_10EFC:
;		cmpi.b	#$1C,anim(a0)			; Liliam: stop going invisible in HCZ water tunnels
;		beq.w	locret_10E2C			;
		tst.w	y_vel(a0)
		beq.w	locret_10E2C
		move.w	#1<<8,anim(a6)	; splash animation, write 1 to anim and clear prev_anim
		cmpi.w	#-$1000,y_vel(a0)
		bgt.s	loc_10F22
		move.w	#-$1000,y_vel(a0)	; limit upward y velocity exiting the water

loc_10F22:
		move.w	#sfx_Splash,d0
		jmp	(Play_SFX).l
; End of function Sonic_Water

; ---------------------------------------------------------------------------
; Start of subroutine Obj01_MdNormal
; Called if Sonic is neither airborne nor rolling this frame
; ---------------------------------------------------------------------------

Sonic_MdNormal:
		jsr	(Sonic_PeelOut).l			; Liliam: extra skills - peel out (credit: Tiddles)
		bsr.w	SonicKnux_Spindash
		bsr.w	Sonic_Jump
		bsr.w	Player_SlopeResist
		bsr.w	Sonic_Move
		bsr.w	SonicKnux_Roll
		bsr.w	Player_LevelBound
		jsr	(MoveSprite_TestGravity2).l
		bsr.w	Call_Player_AnglePos
		bsr.w	Player_SlopeRepel
		tst.b	(Background_collision_flag).w
		beq.s	locret_10F82
		bsr.w	sub_F846
		tst.w	d1
		bmi.w	Kill_Character
		movem.l	a4-a6,-(sp)
		bsr.w	CheckLeftWallDist
		tst.w	d1
		bpl.s	loc_10F72
		sub.w	d1,x_pos(a0)

loc_10F72:
		bsr.w	CheckRightWallDist
		tst.w	d1
		bpl.s	loc_10F7E
		add.w	d1,x_pos(a0)

loc_10F7E:
		movem.l	(sp)+,a4-a6

locret_10F82:
		rts

; =============== S U B R O U T I N E =======================================


Call_Player_AnglePos:
		tst.b	(Reverse_gravity_flag).w
		beq.w	Player_AnglePos
		move.b	angle(a0),d0
		addi.b	#$40,d0
		neg.b	d0
		subi.b	#$40,d0
		move.b	d0,angle(a0)
		bsr.w	Player_AnglePos
		move.b	angle(a0),d0
		addi.b	#$40,d0
		neg.b	d0
		subi.b	#$40,d0
		move.b	d0,angle(a0)
		rts
; End of function Call_Player_AnglePos

; ---------------------------------------------------------------------------
; Start of subroutine Sonic_MdAir
; Called if Sonic is airborne, but not in a ball (thus, probably not jumping)

Sonic_MdAir:
		tst.b	double_jump_flag(a0)			; Liliam: extra skills - air glide
		bmi.w	Ray_AirGlide				;
		jsr	(Sonic_PeelOut_SFX).l			; Liliam: extra skills - peel out
