		beq.s	loc_11908				;
		tst.b	$39(a6)					;
		bgt.s	loc_11908				;
		tst.b	double_jump_property(a0)		; Liliam: extra skills - drop dash
		beq.s	locret_118FE				;
		move.b	(Ctrl_1_held_logical).w,d0		;
		andi.b	#button_ABC_mask,d0			;
		bne.w	Sonic_DropDash_Charge			;
		clr.b	double_jump_property(a0)		;
		move.b	#2,anim(a0)				;
		tst.b	character_id(a0)			;
		beq.s	locret_118FE				;
		move.b	#3,anim(a0)				;
		rts						;
; ---------------------------------------------------------------------------

loc_11908:
		move.b	(Ctrl_1_pressed_logical).w,d0
		cmpa.w	#Player_1,a0				; Liliam: Encore mode - block jump moves for player 2
		beq.s	loc_1190C				;
		tst.w	(Tails_CPU_idle_timer).w		;
		beq.s	locret_1192A				;

		andi.b	#button_ABC_mask,d0			;
		beq.s	locret_1192A				;
		bclr	#Status_RollJump,status(a0)		;

		move.b	character_id(a0),d0			; Liliam: add extra characters
		bne.s	Sonic_ExtraCharacterMoves		;

		tst.w	(Competition_mode).w			; Liliam: dash dust - player 2 insta-shield
		bne.s	Sonic_InstaShield			;
		move.b	#5,(Dust_P2+anim).w			;
		bsr.s	Sonic_DropDash_2P			;

Sonic_InstaShield:
