loc_11958:
		move.w	d0,x_vel(a0)		; apply velocity...
		move.w	d0,ground_vel(a0)	; ...both ground and air
		move.w	#0,y_vel(a0)		; kill y-velocity
		move.w	#$2000,(H_scroll_frame_offset).w
