		beq.s	Sonic_BubbleShield
		move.b	(Ctrl_1_held_logical).w,d0		; Liliam: QOL - Tails assist
		andi.b	#button_right_mask|button_left_mask,d0	;
		bne.s	loc_11982				;
		btst	#button_up,(Ctrl_1_held_logical).w	;
		bne.s	locret_11A14				;

loc_11982:
		move.b	#1,(Shield+anim).w
		move.b	#Status_LtngShield,double_jump_flag(a0)	; Liliam: simplify double jump selection
;		move.b	#1,double_jump_flag(a0)			;
		move.w	#-$580,y_vel(a0)	; bounce Sonic up, creating the double jump effect
		clr.b	jumping(a0)
		move.w	#sfx_ElectricAttack,d0
		jmp	(Play_SFX).l
; ---------------------------------------------------------------------------

Sonic_BubbleShield:
		btst	#Status_BublShield,status_secondary(a0)
		beq.s	Sonic_CheckTransform
		move.b	(Ctrl_1_held_logical).w,d0		; Liliam: QOL - Tails assist
		andi.b	#button_right_mask|button_left_mask,d0	;
		bne.s	loc_119AA				;
		btst	#button_up,(Ctrl_1_held_logical).w	;
		bne.s	locret_11A14				;

loc_119AA:
		move.b	#1,(Shield+anim).w
		move.b	#Status_BublShield,double_jump_flag(a0)	; Liliam: simplify double jump selection
;		move.b	#1,double_jump_flag(a0)			;
		move.w	#0,x_vel(a0)		; halt horizontal speed...
		move.w	#0,ground_vel(a0)	; ...both ground and air
		move.w	#$800,y_vel(a0)		; force Sonic down
		move.w	#sfx_BubbleAttack,d0
		jmp	(Play_SFX).l
; ---------------------------------------------------------------------------

Sonic_CheckTransform:
;		cmpi.b	#7,(Super_emerald_count).w			; Liliam: HUD - barrier HUD
;		bhs.s	loc_119E8					;
;		cmpi.b	#7,(Chaos_emerald_count).w			;
;		blo.s	Sonic_InstaShield				;
;		tst.b	(Emeralds_converted_flag).w			;
;		bne.s	Sonic_InstaShield				;

;loc_119E8:
;		cmpi.w	#50,(Ring_count).w				;
;		blo.s	Sonic_InstaShield				;
;		tst.b	(Update_HUD_timer).w				;
;		bne.s	Sonic_Transform					;

;Sonic_InstaShield:
;		btst	#Status_Shield,status_secondary(a0)		;
;		bne.s	locret_11A14					;
		move.b	#1,(Shield+anim).w
		bsr.w	Sonic_DropDash				; Liliam: extra skills - drop dash
		bra.w	Sonic_InstaShield			;
;		move.b	#1,double_jump_flag(a0)			;
;		move.w	#sfx_InstaAttack,d0			;
;		jmp	(Play_SFX).l				;
; ---------------------------------------------------------------------------

locret_11A14:
		rts
; ---------------------------------------------------------------------------

Sonic_Transform:
		tst.b	character_id(a0)			; Liliam: add extra characters
		bne.w	Knux_Transform				;

		move.b	#1,(Super_palette_status).w	; set Super/Hyper palette status to 'fading'
		move.b	#$F,(Palette_timer).w
		move.w	#60,(Super_frame_count).w
;		move.l	#Map_SuperSonic,mappings(a0)		; Liliam: Encore mode - change character item
		move.b	#$81,object_control(a0)
		move.b	#$16,anim(a0)				; Liliam: simplify player anim selection
;		move.b	#$1F,anim(a0)				;
		movea.l	a0,a1					; Liliam: bugfix - clear roll state
		jsr	(Player_ClearRollHeight2).l		;
		clr.b	(Super_ready_HUD_flag).w			; Liliam: HUD - barrier HUD

		cmpi.b	#7,(Super_emerald_count).w		; does Sonic have all 7 Super Emeralds?
		blo.s	.super					; if not, turn Super
		move.b	#-1,(Super_Sonic_Knux_flag).w		; set flag to Hyper Sonic
		move.l	#Obj_HyperSonic_Stars,(Invincibility_stars).w
		move.l	#Obj_HyperSonicKnux_Trail,(Super_stars).w
		move.b	#30,air_left(a0)				; Liliam: bugfix - replenish air on hyper transform
		bra.s	.continued
; ---------------------------------------------------------------------------

	.super:
		move.b	#1,(Super_Sonic_Knux_flag).w		; set flag to Super Sonic
		move.l	#Obj_SuperSonic_Stars,(Super_stars).w

	.continued:
		btst	#Status_SpeedShoes,status_secondary(a0)	; Liliam: bugfix - player speeds fix
		bne.s	loc_11A6E				;
		move.w	#$A00,Max_speed-Max_speed(a4)

loc_11A6E:
		move.w	#$30,Acceleration-Max_speed(a4)
		move.w	#$100,Deceleration-Max_speed(a4)
		move.b	#0,invincibility_timer(a0)
		bset	#Status_Invincible,status_secondary(a0)
		moveq	#signextendB(sfx_SuperTransform),d0
		jsr	(Play_SFX).l
		tst.b	(Boss_flag).w				; Liliam: bugfix - use correct music for bosses
		bne.w	locret_11A14				;

		moveq	#signextendB(mus_HyperTheme),d0		; Liliam: special music for hyper forms
		tst.b	(Super_Sonic_Knux_flag).w		;
		bmi.s	loc_11A90				;
		cmpi.b	#12,air_left(a0)			;
		blo.w	locret_11A14				;
		moveq	#signextendB(mus_Invincibility),d0
		btst	#EncoreFlags_Music,(Encore_flags).w	; Liliam: Encore mode - music
		beq.s	loc_11A90				;
		moveq	#signextendB(mus_InvincibilityK),d0	;

loc_11A90:
		movea.l	a0,a1					; Liliam: bugfix - keep correct tempo
		jmp	(Play_Music_Tempo).l			;
;		jmp	(Play_Music).l				;
; ---------------------------------------------------------------------------

Sonic_HyperDash:
		bsr.w	HyperAttackTouchResponse
		move.w	#$2000,(H_scroll_frame_offset).w
		bsr.w	Reset_Player_Position_Array
		move.b	#3,double_jump_flag(a0)			; Liliam: simplify double jump selection
;		move.b	#1,double_jump_flag(a0)			;
		move.b	#1,(Invincibility_stars+anim).w	; This causes the screen flash, and sparks to come out of Sonic
		moveq	#signextendB(sfx_Dash),d0
		jsr	(Play_SFX).l
		move.b	(Ctrl_1_held_logical).w,d0
		andi.w	#button_up_mask|button_down_mask|button_left_mask|button_right_mask,d0	; Get D-pad input
		beq.s	.noInput
		; Any values totaling $B or above are produced by holding
		; both opposing directions on the D-pad, which is invalid
		cmpi.b	#$B,d0
		bhs.s	.noInput
		lsl.w	#2,d0
		lea	Sonic_HyperDash_Velocities-4(pc,d0.w),a1
		move.w	(a1)+,d0
		move.w	d0,x_vel(a0)
		move.w	d0,ground_vel(a0)
		move.w	(a1)+,d0
		move.w	d0,y_vel(a0)
		rts
; ---------------------------------------------------------------------------

	.noInput:
		; If there's no directional input, we just dash forward
		move.w	#$800,d0	; Go right...
		btst	#Status_Facing,status(a0)	; ...unless Sonic is facing left...
		beq.s	.applySpeeds
		neg.w	d0		; ...in which case, go left

	.applySpeeds:
		move.w	d0,x_vel(a0)
		move.w	d0,ground_vel(a0)
		move.w	#0,y_vel(a0)
		rts
; End of function Sonic_JumpHeight

; ---------------------------------------------------------------------------
Sonic_HyperDash_Velocities:
		dc.w      0, -$800	; up
		dc.w      0,  $800	; down
		dc.w      0,     0	; up + down (shouldn't happen)
		dc.w  -$800,     0	; left
		dc.w  -$800, -$800	; left + up
		dc.w  -$800,  $800	; left + down
		dc.w      0,     0	; left + up + down (shouldn't happen)
		dc.w   $800,     0	; right
		dc.w   $800, -$800	; right + up
		dc.w   $800,  $800	; right + down
		; Everything after this would be bad button combinations
; ---------------------------------------------------------------------------

Tails_Super:
		tst.b	(Super_Tails_flag).w
		beq.w	SonicKnux_SuperHyper.return
		bpl.s	SonicKnux_SuperHyper.notHyperTails		; Liliam: animate super forms consistently
		moveq	#3,d0						;
		bra.s	SonicKnux_SuperHyper.continued

; =============== S U B R O U T I N E =======================================


SonicKnux_SuperHyper:
		tst.b	(Super_Sonic_Knux_flag).w
		beq.w	.return

	.notHyperTails:
		moveq	#2,d0						; Liliam: animate super forms consistently

	.continued:
		tst.b	(Update_HUD_timer).w	; Level over?
		beq.s	.revertToNormal
		subq.w	#1,(Super_frame_count).w
	if FixBugs
		bhi.w	.return
	else
		; Bug: This should be a 'bhi'; currently counts down 61 frames
		bpl.w	.return
	endif
		move.w	#60,(Super_frame_count).w
		tst.w	(Ring_count).w
		beq.s	.revertToNormal	; If rings depleted, return to normal
		; This checks if the ring counter needs to be blanked
		; for example, this ticks '10' down to ' 9' instead of '19' (yes, this does happen)
		ori.b	#1,(Update_HUD_ring_count).w	; Update ring counter
		cmpi.w	#1,(Ring_count).w
		beq.s	.resetHUD
		cmpi.w	#10,(Ring_count).w
		beq.s	.resetHUD
		cmpi.w	#100,(Ring_count).w
		bne.s	.updateHUD

	.resetHUD:
		ori.b	#$80,(Update_HUD_ring_count).w	; Re-init ring counter

	.updateHUD:
		subq.w	#1,(Ring_count).w
		beq.s	.revertToNormal					; Liliam: animate super forms consistently
;		bne.s	.return						;
		rts							;
; ---------------------------------------------------------------------------

	.revert:
		lea	(Max_speed).w,a4				; Liliam: animate super forms consistently
		moveq	#3,d0						;
		tst.b	(Super_Tails_flag).w				;
		bmi.s	.revertToNormal					;
		moveq	#2,d0						;

	.revertToNormal:
;		move.b	#2,(Super_palette_status).w			;
		move.b	d0,(Super_palette_status).w			;
		move.w	#$1E,(Palette_frame).w
		clr.b	(Palette_timer).w				;
		clr.b	(Disable_A_button_flag).w			; Liliam: Hyper Amy
		move.b	#0,(Super_Sonic_Knux_flag).w
		move.b	#0,(Super_Tails_flag).w
		move.b	#-1,prev_anim(a0)			; Liliam: bugfix - fix stuck animation
;		move.b	#-1,(Player_prev_frame).w		;
		tst.b	character_id(a0)
		bne.s	.notSonic
		move.l	#Map_Sonic,mappings(a0)
		move.b	#-1,(Player_prev_frame).w		;

	.notSonic:
;	;	move.b	#1,prev_anim(a0)			; Liliam: bugfix - fix walk anim restarting			;
		move.b	#1,invincibility_timer(a0)
		bclr	#Status_Invincible,status_secondary(a0)	; Liliam: bugfix - clear super form on death
		move.w	#$600,Max_speed-Max_speed(a4)
		move.w	#$C,Acceleration-Max_speed(a4)
		move.w	#$80,Deceleration-Max_speed(a4)
		btst	#Status_SpeedShoes,status_secondary(a0)	; Liliam: bugfix - player speeds fix
;		btst	#Status_Underwater,status(a0)		;
		beq.s	.return
		move.w	#$C00,Max_speed-Max_speed(a4)		;
		move.w	#$18,Acceleration-Max_speed(a4)		;
		move.w	#$80,Deceleration-Max_speed(a4)		;
;		move.w	#$300,Max_speed-Max_speed(a4)		;
;		move.w	#6,Acceleration-Max_speed(a4)		;
;		move.w	#$40,Deceleration-Max_speed(a4)		;

	.return:
		rts
; End of function SonicKnux_SuperHyper


