Sonic_DropDash_Charge:						; Liliam: extra skills - drop dash (credit: MainMemory)
		tst.b	double_jump_property(a0)
		bmi.s	locret_12170
		subq.b	#1,double_jump_property(a0)
		bne.s	locret_12170
		move.b	#$A,anim(a0)
		move.b	#-1,double_jump_property(a0)
		moveq	#signextendB(sfx_DropDash),d0
		jmp	(Play_SFX).l
; ---------------------------------------------------------------------------

Sonic_TouchFloor_CheckDropDash:					; Liliam: extra skills - drop dash (credit: MainMemory)
		tst.b	double_jump_property(a0)
		bpl.w	Player_TouchFloor
		bsr.w	Player_TouchFloor2

Sonic_DropDash_Release:
		tst.b	character_id(a0)
		bne.w	Amy_HammerRush_Release
		clr.b	double_jump_property(a0)
		btst	#button_right,(Ctrl_1_logical).w
		beq.s	.notright
		bclr	#Status_Facing,status(a0)

	.notright:
		btst	#button_left,(Ctrl_1_logical).w
		beq.s	.notleft
		bset	#Status_Facing,status(a0)

	.notleft:
		moveq	#signextendB(sfx_Dash),d0
		move.w	#$800,d2
		move.w	#$C00,d3
		tst.b	(Super_Sonic_Knux_flag).w
		beq.s	.notsuper
		moveq	#signextendB(sfx_DashRelease),d0
		move.w	#$C00,d2
		move.w	#$D00,d3

	.notsuper:
		btst	#Status_Facing,status(a0)
		bne.s	.facingleft
		tst.w	x_vel(a0)
		bmi.s	.backwards_r
		move.w	ground_vel(a0),d1
		asr.w	#2,d1
		add.w	d2,d1
		move.w	d1,ground_vel(a0)
		cmp.w	d3,d1
		blt.s	.checkplayer
		move.w	d3,ground_vel(a0)
		bra.s	.checkplayer
; ---------------------------------------------------------------------------

	.backwards_r:
		tst.b	angle(a0)
		beq.s	.setspeed
		move.w	ground_vel(a0),d1
		asr.w	#1,d1
		add.w	d2,d1
		move.w	d1,ground_vel(a0)
		bra.s	.checkplayer
; ---------------------------------------------------------------------------

	.facingleft:
		neg.w	d2
		neg.w	d3
		tst.w	x_vel(a0)
		bpl.s	.backwards_l
		move.w	ground_vel(a0),d1
		asr.w	#2,d1
		add.w	d2,d1
		move.w	d1,ground_vel(a0)
		cmp.w	d3,d1
		bgt.s	.checkplayer
		move.w	d3,ground_vel(a0)
		bra.s	.checkplayer
; ---------------------------------------------------------------------------

	.backwards_l:
		tst.b	angle(a0)
		beq.s	.setspeed
		move.w	ground_vel(a0),d1
		asr.w	#1,d1
		add.w	d2,d1
		move.w	d1,ground_vel(a0)
		bra.s	.checkplayer
; ---------------------------------------------------------------------------

	.setspeed:
		move.w	d2,ground_vel(a0)

	.checkplayer:
		cmpa.w	#Player_1,a0
		bne.s	.checkair
		move.w	ground_vel(a0),d1
		bpl.s	.calcoffset
		neg.w	d1

	.calcoffset:
		subi.w	#$800,d1
		add.w	d1,d1
		andi.w	#$1F00,d1
		neg.w	d1
		addi.w	#$2000,d1
		move.w	d1,(H_scroll_frame_offset).w
		move.w	#$62,(Distance_from_top).w
		movem.l	d0/a1,-(sp)
		bsr.w	Reset_Player_Position_Array
		movem.l	(sp)+,d0/a1

	.checkair:
		cmpi.b	#12,air_left(a0)
		blo.s	.setanim
		andi.b	#$FC,status(a6)
		move.w	x_pos(a0),x_pos(a6)
		move.w	y_pos(a0),y_pos(a6)
		subq.w	#5,y_pos(a6)
		tst.b	(Reverse_gravity_flag).w
		beq.s	.noYflip
		ori.b	#2,status(a6)
		addi.w	#10,y_pos(a6)

	.noYflip:
		btst	#Status_Facing,status(a0)
		beq.s	.noXflip
		ori.b	#1,status(a6)

	.noXflip:
		move.w	#6<<8,anim(a6)
		btst	#Status_OnObj,status(a0)
		beq.s	.setanim
		move.l	a0,-(sp)
		movea.w	interact(a0),a0
		move.w	x_pos(a0),ground_vel(a6)
		move.w	y_pos(a0),y_radius(a6)
		move.w	a0,parent2(a6)
		move.w	#7<<8,anim(a6)
		movea.l	(sp)+,a0

	.setanim:
		move.b	#2,anim(a0)
		jmp	(Play_SFX).l

