BubbleShield_CheckOnObj:					; Liliam: bugfix - release player from object
		movem.l	a1-a2,-(sp)
		moveq	#-1,d0
		btst	#Status_OnObj,status(a0)
		beq.s	.return
		movea.w	interact(a0),a1
		lea	BubbleShield_Blacklist(pc),a2

	.loop:
		move.l	(a2)+,d0
		bmi.s	.return
		cmp.l	(a1),d0
		bne.s	.loop
		moveq	#0,d0

	.return:
		movem.l	(sp)+,a1-a2
		rts

