Obj_Tails_Tail:
		; Init
		move.l	#Map_Tails_Tail,mappings(a0)
		movea.w	$30(a0),a2					; Liliam: Encore mode - pick art_tile by parent
		move.w	art_tile(a2),d0					;
		addi.w	#ArtTile_TailsTail-ArtTile_Player_2,d0		;
		move.w	d0,art_tile(a0)					;
;		move.w	#ArtTile_TailsTail,art_tile(a0)			;
		move.w	#$100,priority(a0)
		move.b	#$18,width_pixels(a0)
		move.b	#$18,height_pixels(a0)
		move.b	render_flags(a2),render_flags(a0)	; Liliam: AIZ intro - give Tails intro
		ori.b	#$40,render_flags(a0)			;
;		move.b	#4,render_flags(a0)			;
		move.l	#Obj_Tails_Tail_Main,(a0)
		cmpi.l	#Obj_Tails,(a2)				; Liliam: Encore mode - draw Tails' tails along with him
		bne.s	Obj_Tails_Tail_Main			;
		move.l	#Obj_Tails_Tail_NoDraw,(a0)		;

Obj_Tails_Tail_Main:
		bsr.w	Draw_Sprite				;

Obj_Tails_Tail_NoDraw:
		; Here, several SSTs are inherited from the parent, normally Tails
		movea.w	$30(a0),a2	; Is Parent in S2
		move.b	angle(a2),angle(a0)
		move.b	status(a2),status(a0)
		move.w	x_pos(a2),x_pos(a0)
		move.w	y_pos(a2),y_pos(a0)
		move.w	priority(a2),priority(a0)
		andi.w	#drawing_mask,art_tile(a0)
		tst.w	art_tile(a2)
		bpl.s	loc_16106
		ori.w	#high_priority,art_tile(a0)

loc_16106:
		moveq	#0,d0
		move.b	anim(a2),d0
;		btst	#Status_Push,status(a2)			; Liliam: simplify player anim selection
