Knuckles_Fall_From_Glide:
		; This function updates 'Gliding_collision_flags'.
		move.w	a4,-(sp)				; Liliam: allow glide-landing on objects (credit: flamewing)
		bsr.w	Knux_DoLevelCollision_CheckRet		;
		move.w	(sp)+,a4				;

		bsr.w	Knux_ChgJumpDir

		; Apply gravity.
		addi.w	#$38,y_vel(a0)

		; Fall slower when underwater.
		btst	#Status_Underwater,status(a0)
		beq.s	.skip1
		subi.w	#$28,y_vel(a0)

.skip1:
		btst	#Status_OnObj,status(a0)		; Liliam: allow glide-landing on objects (credit: flamewing)
		bne.s	.skip4					;
;		bsr.w	Knux_DoLevelCollision_CheckRet		;

		btst	#Status_InAir,(Gliding_collision_flags).w
		bne.s	.return

.skip4:
		; Knuckles has touched the ground.
		move.w	#0,ground_vel(a0)
		move.w	#0,x_vel(a0)
		move.w	#0,y_vel(a0)

		move.b	y_radius(a0),d0
		sub.b	default_y_radius(a0),d0
		ext.w	d0
		tst.b	(Reverse_gravity_flag).w
		beq.s	.skip2
		neg.w	d0

.skip2:
		add.w	d0,y_pos(a0)

		moveq	#signextendB(sfx_GlideLand),d0
		jsr	(Play_SFX).l

		move.b	angle(a0),d0
		addi.b	#$20,d0
		andi.b	#$C0,d0
		beq.s	.skip3
		bra.w	Knux_TouchFloor

.skip3:
		bsr.w	Knux_TouchFloor
		move.w	#$F,move_lock(a0)
		move.b	#$1E,anim(a0)				; Liliam: simplify player anim selection
;		move.b	#$23,anim(a0)				;
; locret_16B04:
.return:
		rts
; ---------------------------------------------------------------------------

Knuckles_Sliding:
		move.b	(Ctrl_1_held_logical).w,d0
		andi.b	#button_ABC_mask,d0
		beq.s	.getUp

		tst.w	x_vel(a0)
		bpl.s	.goingRight

;.goingLeft:
		addi.w	#$20,x_vel(a0)
		bmi.s	.continueSliding2

		bra.s	.getUp
; ---------------------------------------------------------------------------
; loc_16B20:
.continueSliding2:
		bra.s	.continueSliding
; ---------------------------------------------------------------------------
; loc_16B22:
.goingRight:
		subi.w	#$20,x_vel(a0)
		bpl.s	.continueSliding
; loc_16B2A:
.getUp:
		move.w	#0,ground_vel(a0)
		move.w	#0,x_vel(a0)
		move.w	#0,y_vel(a0)

		move.b	y_radius(a0),d0
		sub.b	default_y_radius(a0),d0
		ext.w	d0
		tst.b	(Reverse_gravity_flag).w
		beq.s	.skip1
		neg.w	d0

.skip1:
		add.w	d0,y_pos(a0)

		bsr.w	Knux_TouchFloor

		move.w	#$F,move_lock(a0)
		move.b	#$1F,anim(a0)				; Liliam: simplify player anim selection
;		move.b	#$22,anim(a0)				;

		rts
; ---------------------------------------------------------------------------
; loc_16B64:
.continueSliding:
		bsr.w	Knux_DoLevelCollision_CheckRet
		btst	#Status_OnObj,status(a0)		; Liliam: allow glide-landing on objects (credit: flamewing)
		bne.s	.skip4					;

		; Get distance from floor in 'd1', and angle of floor in 'd3'.
		bsr.w	sub_11FD6

		; If the distance from the floor is suddenly really high, then
		; Knuckles must have slid off a ledge, so make him enter his falling
		; state.
		cmpi.w	#14,d1
		bge.s	.fail

		tst.b	(Reverse_gravity_flag).w
		beq.s	.skip2
		neg.w	d1

.skip2:
		add.w	d1,y_pos(a0)
		move.b	d3,angle(a0)

.skip4:
		; Play the sliding sound every 8 frames.
		move.b	(Level_frame_counter+1).w,d0
		andi.b	#7,d0
		bne.s	.skip3

		moveq	#signextendB(sfx_GroundSlide),d0
		jsr	(Play_SFX).l
.skip3:
		rts
; ---------------------------------------------------------------------------
; loc_16B96:
.fail:
		move.b	#2,double_jump_flag(a0)
		move.b	#$1D,anim(a0)				; Liliam: simplify player anim selection
;		move.b	#$21,anim(a0)				;

		move.b	default_y_radius(a0),y_radius(a0)
		move.b	default_x_radius(a0),x_radius(a0)

		bset	#Status_InAir,(Gliding_collision_flags).w
		rts
; ---------------------------------------------------------------------------

Knuckles_Wall_Climb:
		tst.b	(Disable_wall_grab).w
		bmi.w	Knuckles_LetGoOfWall

		; If Knuckles' X coordinate is no longer the same as when he first
		; latched onto the wall, then detach him from the wall. This is
		; probably intended to detach Knuckles from the wall if something
		; physically pushes him away from it.
		move.w	x_pos(a0),d0
		cmp.w	x_pos+2(a0),d0
		bne.w	Knuckles_LetGoOfWall
		move.w	y_pos(a0),d0				; Liliam: bugfix - release Knuckles from wall
		cmp.w	y_pos+2(a0),d0				;
		bne.w	Knuckles_LetGoOfWall			;

		; If an object is now carrying Knuckles, then detach him from the
		; wall.
		btst	#Status_OnObj,status(a0)
		bne.w	Knuckles_LetGoOfWall

		move.w	#0,ground_vel(a0)
		move.w	#0,x_vel(a0)
		move.w	#0,y_vel(a0)

		move.l	(Primary_collision_addr).w,(Collision_addr).w
		cmpi.b	#$D,lrb_solid_bit(a0)
		beq.s	loc_16BFA
		move.l	(Secondary_collision_addr).w,(Collision_addr).w

loc_16BFA:
		tst.b	spin_dash_flag(a0)			; Liliam: extra skills - climb dash
		bne.w	Knuckles_ClimbDash			;
		move.b	lrb_solid_bit(a0),d5

		moveq	#0,d1	; Climbing animation delta: make the animation pause.

		btst	#button_up,(Ctrl_1_logical).w
		beq.w	.notClimbingUp

;.climbingUp:
		tst.b	(Reverse_gravity_flag).w
		bne.w	.climbingUp_ReverseGravity

