		bpl.s	.notMoving
		move.b	#3,double_jump_property(a0)

		; Add delta to animation frame.
		add.b	mapping_frame(a0),d1

	; Make the animation loop.
		cmpi.b	#$B7,d1
		bhs.s	.noLoop1
