		move.b	#1,jumping(a0)

		move.b	#$E,y_radius(a0)
		move.b	#7,x_radius(a0)

		move.b	#2,anim(a0)
		bset	#Status_Roll,status(a0)
		move.b	#0,double_jump_flag(a0)
