; sub_16F4E:
GetDistanceFromWall:
		move.b	lrb_solid_bit(a0),d5
		btst	#Status_Facing,status(a0)
		bne.s	.facingLeft

;.facingRight:
		move.w	x_pos(a0),d3
		jmp	(loc_FAA4).l				; Liliam: fallout
;		bra.w	loc_FAA4				;
