Knuckles_ClimbDash:						; Liliam: extra skills - climb dash
		btst	#button_down,(Ctrl_1_held_logical).w
		beq.s	Knuckles_ClimbDash_Release
		tst.w	spin_dash_counter(a0)
		beq.s	.checkButtons
		move.w	spin_dash_counter(a0),d0
		lsr.w	#5,d0
		sub.w	d0,spin_dash_counter(a0)
		bcc.s	.checkButtons
		move.w	#0,spin_dash_counter(a0)

	.checkButtons:
		move.b	(Ctrl_1_pressed_logical).w,d0
		andi.b	#button_ABC_mask,d0
		beq.w	.moveCamera
		move.w	#$A<<8,anim(a0)
		move.w	#signextendB(sfx_Spindash),d0
		jsr	(Play_SFX).l
		addi.w	#$200,spin_dash_counter(a0)
		cmpi.w	#$800,spin_dash_counter(a0)
		blo.s	.moveCamera
		move.w	#$800,spin_dash_counter(a0)

	.moveCamera:
		move.w	(Camera_Y_pos).w,d0
		cmp.w	(Camera_min_Y_pos).w,d0
		beq.s	.return
		cmp.w	(Camera_max_Y_pos).w,d0
		beq.s	.return
		sub.w	y_pos(a0),d0
		andi.w	#$FFFE,d0
		cmpi.w	#-$60,d0
		beq.s	.return
		blo.s	.increment
		subq.w	#4,(Camera_Y_pos).w

	.increment:
		addq.w	#2,(Camera_Y_pos).w

	.return:
		rts
; ---------------------------------------------------------------------------

Knuckles_ClimbDash_Release:					; Liliam: extra skills - climb dash
		move.b	#$E,y_radius(a0)
		move.b	#7,x_radius(a0)
		move.b	#2,anim(a0)
		bclr	#Status_InAir,status(a0)
		bset	#Status_Roll,status(a0)
		clr.b	anim(a6)
		clr.b	spin_dash_flag(a0)
		clr.b	double_jump_flag(a0)
		clr.b	jumping(a0)
		clr.w	x_pos+2(a0)
		clr.w	y_pos+2(a0)
		moveq	#0,d0
		move.b	spin_dash_counter(a0),d0
		add.w	d0,d0
		lea	(word_15320).l,a1
		tst.b	(Super_Sonic_Knux_flag).w
		bne.s	.applySpeed
		lea	(word_1530E).l,a1

	.applySpeed:
		move.w	(a1,d0.w),ground_vel(a0)
		move.b	#$C0,angle(a0)
		btst	#Status_Facing,status(a0)
		beq.s	.playSFX
		neg.w	ground_vel(a0)
		move.b	#$40,angle(a0)

	.playSFX:
		moveq	#signextendB(sfx_Dash),d0
		jmp	(Play_SFX).l
