Sonic_ClearShieldJump:						; Liliam: simplify double jump selection
		movea.w	parent(a0),a2
		tst.b	character_id(a2)
		bne.s	.return
		cmpi.b	#Status_LtngShield,double_jump_flag(a2)
		bne.s	.clear
		move.b	#1,jumping(a2)

	.clear:
		clr.b	double_jump_flag(a2)

	.return:
		rts
