Obj_SuperTailsBirds_Move:
		; Update the bird's x_vel
		move.w	#$20,d1
		cmp.w	x_pos(a0),d2
		bge.s	.go_right
		neg.w	d1
		tst.w	x_vel(a0)
		bmi.s	.x_vel_done
		; Going the wrong way - make it turn around faster
		add.w	d1,d1
		add.w	d1,d1
		bra.s	.x_vel_done
; ---------------------------------------------------------------------------

	.go_right:
		tst.w	x_vel(a0)
		bpl.s	.x_vel_done
		; Going the wrong way - make it turn around faster
		add.w	d1,d1
		add.w	d1,d1

	.x_vel_done:
		add.w	d1,x_vel(a0)
		; Update the bird's y_vel
		and.w	(Screen_Y_wrap_value).w,d3
		move.w	#$20,d1
		sub.w	y_pos(a0),d3
		bcc.s	loc_1A3CA
		cmpi.w	#-$500,d3
		ble.s	loc_1A3D0

loc_1A3B4:
		cmpi.w	#-$1000,y_vel(a0)
		ble.s	loc_1A3D8

loc_1A3BC:
		neg.w	d1
		tst.w	y_vel(a0)
		bmi.s	loc_1A3E2
		; Going the wrong way - make it turn around faster
		add.w	d1,d1
		add.w	d1,d1
		bra.s	loc_1A3E2
; ---------------------------------------------------------------------------

loc_1A3CA:
		cmpi.w	#$500,d3
		bge.s	loc_1A3B4

loc_1A3D0:
		cmpi.w	#$1000,y_vel(a0)
		bge.s	loc_1A3BC

loc_1A3D8:
		tst.w	y_vel(a0)
		bpl.s	loc_1A3E2
		; Going the wrong way - make it turn around faster
		add.w	d1,d1
		add.w	d1,d1

loc_1A3E2:
		add.w	d1,y_vel(a0)
		jsr	(MoveSprite2).l
		move.w	(Level_repeat_offset).w,d0
		sub.w	d0,x_pos(a0)
		move.w	(Screen_Y_wrap_value).w,d0
		and.w	d0,y_pos(a0)
		rts
; End of function sub_1A37A


