		neg.w	d1

	.checkEnable:
		cmpi.w	#$1000,d1
		beq.s	.silentEnable
		cmpi.w	#$600,d1
		blo.s	.resetTimer
		move.w	(Ring_count).w,d1
		cmpi.w	#150,d1
		blo.s	.checkTimer
		move.w	#150,d1

	.checkTimer:
		subq.w	#1,d0
		cmp.w	d0,d1
		bhs.s	.normalEnable
		move.w	d0,anim_frame_timer(a0)
		rts
; ---------------------------------------------------------------------------

	.disable:
		tst.b	invincibility_timer(a2)
		bne.s	.resetSpeeds
		bclr	#Status_Invincible,status_secondary(a2)

	.resetSpeeds:
		btst	#Status_SpeedShoes,status_secondary(a2)
		bne.s	.resetTimer
		move.w	#$600,Max_speed-Max_speed(a1)
		move.w	#$C,Acceleration-Max_speed(a1)

	.resetTimer:
		move.w	#$B4,anim_frame_timer(a0)
		rts
; ---------------------------------------------------------------------------

	.normalEnable:
		cmpa.w	#Player_1,a2
		bne.s	.playSFX
		move.w	#$A00,(H_scroll_frame_offset).w

	.playSFX:
		moveq	#signextendB(sfx_Dash),d0
		jsr	(Play_SFX).l

	.silentEnable:
		clr.w	anim_frame_timer(a0)

	.enabled:
		lea	(Max_speed_P2).w,a1
		cmpa.w	#Player_1,a2
		bne.s	.checkInAir
		lea	(Max_speed).w,a1

	.checkInAir:
		btst	#Status_InAir,status(a2)
		bne.s	.applySpeeds
		move.w	ground_vel(a2),d1
		bpl.s	.checkDisable
		neg.w	d1

	.checkDisable:
		cmpi.w	#$400,d1
		blo.s	.disable

	.applySpeeds:
		bset	#Status_Invincible,status_secondary(a2)
		btst	#Status_SpeedShoes,status_secondary(a2)
		bne.s	.checkframe
		move.w	#$A00,Max_speed-Max_speed(a1)
		move.w	#$18,Acceleration-Max_speed(a1)

	.checkframe:
		moveq	#$C,d1
		btst	#0,(Level_frame_counter+1).w
		beq.s	.evenframe
		moveq	#$14,d1

	.evenframe:
		cmpa.w	#Player_1,a2
		beq.s	.checkPositionArray
		move.w	angle(a0),d0
		sub.b	d1,d0
		andi.b	#$1F,d0
		lea	collision_flags(a0),a1
		lea	(a1,d0.w),a1
		move.w	(a1)+,x_pos(a0)
		move.w	(a1)+,y_pos(a0)
		andi.w	#drawing_mask,art_tile(a0)
		tst.w	art_tile(a2)
		bmi.s	.setPriority
		bra.s	.drawTrail
; ---------------------------------------------------------------------------

	.checkPositionArray:
		move.w	(Pos_table_index).w,d0
		sub.b	d1,d0
		lea	(Pos_table).w,a1
		lea	(a1,d0.w),a1
		move.w	(a1)+,x_pos(a0)
		move.w	(a1)+,y_pos(a0)
		lea	(Stat_table).w,a1
		andi.w	#drawing_mask,art_tile(a0)
		tst.b	3(a1,d0.w)
		bpl.s	.drawTrail

	.setPriority:
		ori.w	#high_priority,art_tile(a0)

	.drawTrail:
		move.b	mapping_frame(a2),mapping_frame(a0)
		move.b	render_flags(a2),render_flags(a0)
		move.w	priority(a2),priority(a0)
		bra.w	Draw_Sprite
; ---------------------------------------------------------------------------

Encore_UnpackStocks:							; Liliam: Encore mode - save data
		lea	Encore_stocks-Reserved_object_3+1(a0),a1
		moveq	#1,d1
		moveq	#7,d2
		and.b	d0,d2
		beq.s	.setStockCount

	.unpackStock:
		addq.b	#1,d1
		subq.b	#1,d2
		move.b	d2,(a1)+
		bclr	d2,(Encore_available_chars).w
		lsr.w	#3,d0
		moveq	#7,d2
		and.b	d0,d2
		bne.s	.unpackStock

	.setStockCount:
		move.b	d1,Encore_stocks-Reserved_object_3(a0)
		rts
; ---------------------------------------------------------------------------

Obj_EncoreHelper:						; Liliam: Encore mode - player swap
		move.l	#Obj_EncoreHelper_Main,(a0)
		move.l	#Map_EncoreHelper,mappings(a0)
		move.b	#$44,render_flags(a0)
		move.w	#$100,priority(a0)
		move.w	#1,mainspr_childsprites(a0)
		move.b	#2,mapping_frame(a0)
		move.b	#$C,width_pixels(a0)
		move.b	#$18,height_pixels(a0)
		tst.l	(Player_2).w
		beq.s	Obj_EncoreHelper_Main
		move.w	(Encore_stocks_packed).w,d0
		bsr.s	Encore_UnpackStocks
		add.b	d1,d1
		move.w	d1,Encore_HUD_stocks_frame-Reserved_object_3(a0)

Obj_EncoreHelper_Main:
		jsr	(Obj_ResetCollisionResponseList).l
		tst.w	Encore_HUD_stocks_scroll-Reserved_object_3(a0)
		beq.s	.checkStocks
		subq.w	#2,Encore_HUD_stocks_scroll-Reserved_object_3(a0)

	.checkStocks:
		move.w	Encore_HUD_stocks_timer-Reserved_object_3(a0),d0
		beq.s	.checkPlatform
		subq.w	#1,d0
		move.w	d0,Encore_HUD_stocks_timer-Reserved_object_3(a0)
		andi.b	#1,d0
		neg.b	d0
		add.b	Encore_stocks-Reserved_object_3(a0),d0
		add.b	d0,d0
		move.w	d0,Encore_HUD_stocks_frame-Reserved_object_3(a0)

	.checkPlatform:
		bsr.w	EncoreHelper_KnucklesPlatform
		move.w	Encore_cursor_timer-Reserved_object_3(a0),d0
		beq.s	.checkSpawn
		subq.w	#1,d0
		tst.w	Encore_HUD_player_frame-Reserved_object_3(a0)
		beq.w	.drawCursor
		subi.w	#$C,Encore_HUD_player_frame-Reserved_object_3(a0)
		bra.w	.drawCursor
; ---------------------------------------------------------------------------

	.checkPlayer1:
		tst.w	(Debug_placement_mode).w
		bne.s	.return
		btst	#button_A,(Ctrl_1_pressed).w
		beq.s	.return
		lea	(Player_1).w,a1
		cmpi.b	#8,anim(a1)
		blo.s	.checkPlayer2
		cmpi.b	#$A,anim(a1)
		blo.s	.return
		beq.s	.checkKnuckles
		cmpi.b	#4,double_jump_flag(a0)
		bne.s	.checkPlayer2
		btst	#button_down,(Ctrl_1_held).w
		beq.s	.checkPlayer2

	.checkKnuckles:
		cmpi.b	#2,character_id(a1)
		bne.s	.checkPlayer2

	.return:
		rts
; ---------------------------------------------------------------------------

	.checkSpawn:
		move.b	routine(a0),d0
		beq.s	.checkPlayer1
		clr.b	routine(a0)
		tst.b	d0
		bmi.s	.swapPlayers
		move.w	#2,(Tails_CPU_routine).w
		bra.s	.swapPlayers
; ---------------------------------------------------------------------------

	.checkPlayer2:
		moveq	#signextendB(sfx_EncoreSwapBlocked),d0
		lea	(Player_2).w,a2
		tst.l	(a2)
		beq.w	.playSFX
		tst.b	(Ctrl_2_locked).w
		bmi.w	.playSFX
		move.b	(Update_HUD_timer).w,d1
		or.b	(Bonus_stage_flag).w,d1
		beq.w	.playSFX
		tst.b	render_flags(a2)
		bpl.s	.return
		tst.b	(Flying_carrying_Sonic_flag).w
		bne.s	.checkAlive
		move.b	object_control(a1),d1
		or.b	object_control(a2),d1
		bne.w	.playSFX

	.checkAlive:
		cmpi.b	#State_Control,routine(a1)
		bne.w	.playSFX
		cmpi.b	#State_Control,routine(a2)
		bne.w	.playSFX
		move.w	#$C*7,Encore_HUD_player_frame-Reserved_object_3(a0)
		bchg	#Encore_SwapHUD,(Encore_mode).w

	.swapPlayers:
		move.b	status_secondary(a1),status_secondary(a2)
		clr.b	status_secondary(a1)
		move.b	invincibility_timer(a1),invincibility_timer(a2)
		clr.b	invincibility_timer(a1)
		move.b	speed_shoes_timer(a1),speed_shoes_timer(a2)
		clr.b	speed_shoes_timer(a1)
		bsr.w	EncoreHelper_SwapPlayers
		lea	(Breathing_bubbles).w,a1
		bsr.w	EncoreHelper_SwapChildObjects
		lea	(Dust).w,a1
		bsr.w	EncoreHelper_SwapChildObjects
		lea	(Tails_tails).w,a2
		tst.l	(a2)
		beq.s	.checkBoostMode
		eori.w	#Player_2-Player_1,$30(a2)

	.checkBoostMode:
		lea	(Tails_tails_2P).w,a2
		tst.l	(a2)
		beq.s	.swapObjects
		lea	(Max_speed_P2).w,a1
		eori.b	#Player_2-Player_1,parent2+1(a2)
		beq.s	.resetSpeeds
		btst	#Status_SpeedShoes,(Player_1+status_secondary).w
		bne.s	.swapObjects
		lea	(Max_speed).w,a1

	.resetSpeeds:
		move.w	#$600,Max_speed-Max_speed(a1)
		move.w	#$C,Acceleration-Max_speed(a1)

	.swapObjects:
		lea	(Dynamic_object_RAM).w,a1
		moveq	#((Dynamic_object_RAM_end-Dynamic_object_RAM)/object_size)-1,d0

	.loop1:
		tst.l	(a1)
		beq.s	.nextObject
		lea	EncoreHelper_ColiChgObjPtrs(pc),a2

	.loop2:
		move.l	(a2)+,d1
		bmi.s	.swapInteractBits
		cmp.l	(a1),d1
		bne.s	.loop2
		move.b	$34(a1),d1
		move.b	$35(a1),$34(a1)
		move.b	d1,$35(a1)
		bra.s	.nextObject
; ---------------------------------------------------------------------------

	.swapInteractBits:
		btst	#6,render_flags(a1)
		bne.s	.nextObject
		moveq	#$78,d1
		and.b	status(a1),d1
		eor.b	d1,status(a1)
		lsr.b	#3,d1
		move.b	EncoreHelper_StatusLookup(pc,d1.w),d1
		or.b	d1,status(a1)

	.nextObject:
		lea	next_object(a1),a1
		dbf	d0,.loop1
		move.b	(Player_prev_frame).w,d0
		move.b	(Player_prev_frame_P2).w,(Player_prev_frame).w
		move.b	d0,(Player_prev_frame_P2).w
		move.b	(P1_character).w,d0
		move.b	(P2_character).w,(P1_character).w
		move.b	d0,(P2_character).w
		move.b	#$47,(Tails_CPU_pos_table_offset).w
		moveq	#signextendB(sfx_EncoreSwap),d0

	.playSFX:
		jsr	(Play_SFX).l
		moveq	#29,d0

	.drawCursor:
		move.w	d0,Encore_cursor_timer-Reserved_object_3(a0)
		andi.b	#2,d0
		ror.w	#4,d0
		ori.w	#ArtTile_EncoreCursor,d0
		move.w	d0,art_tile(a0)
		move.w	(Player_1+x_pos).w,sub2_x_pos(a0)
		move.w	(Player_1+y_pos).w,sub2_y_pos(a0)
		move.b	(Reverse_gravity_flag).w,sub2_mapframe(a0)
		bra.w	Draw_Sprite
; ---------------------------------------------------------------------------
EncoreHelper_ColiChgObjPtrs:					; Liliam: Encore mode - player swap
		dc.l Obj_PathSwap_Vertical
		dc.l Obj_PathSwap_Horizontal
		dc.l Obj_SOZPathSwap_Vertical
		dc.l Obj_SOZPathSwap_Horizontal
		dc.l Obj_AutoSpin_Vertical
		dc.l Obj_AutoSpin_Horizontal
		dc.w $FFFF
EncoreHelper_StatusLookup:					; Liliam: Encore mode - player swap
		dc.b %0000000, %0010000, %0001000, %0011000
		dc.b %1000000, %1010000, %1001000, %1011000
		dc.b %0100000, %0110000, %0101000, %0111000
		dc.b %1100000, %1110000, %1101000, %1111000
Map_EncoreHelper:						; Liliam: Encore mode - player swap
		include "General/Sprites/Enemy Misc/Map - Encore Cursor.asm"
; ---------------------------------------------------------------------------

EncoreHelper_SwapChildObjects:					; Liliam: Encore mode - player swap
		lea	next_object(a1),a2
		eori.w	#Player_2-Player_1,parent(a1)
		eori.w	#Player_2-Player_1,parent(a2)

EncoreHelper_SwapPlayers:
		moveq	#$11,d0

	.loop:
		move.l	(a1),d1
		move.l	(a2),(a1)+
		move.l	d1,(a2)+
		dbf	d0,.loop
		rts
; ---------------------------------------------------------------------------

EncoreHelper_KnucklesPlatform:					; Liliam: Encore mode - Knuckles is platform while climbing
		lea 	(Player_1).w,a1
		lea 	(Player_2).w,a2
		move.w	x_pos(a1),x_pos(a0)
		move.w	y_pos(a1),y_pos(a0)
		tst.l	(a2)
		beq.s	.return
		moveq	#3,d6
		bsr.s	.checkClimbing
		lea 	(Player_1).w,a2
		lea 	(Player_2).w,a1
		moveq	#4,d6

	.checkClimbing:
		tst.b	render_flags(a2)
		bpl.s	.return
		tst.b	spin_dash_flag(a2)
		bne.s	.notClimbing
		cmpi.b	#2,character_id(a2)
		bne.s	.notClimbing
		cmpi.b	#4,double_jump_flag(a2)
		bne.s	.notClimbing
		moveq	#$14,d1
		moveq	#$10,d3
		move.w	x_pos(a2),d4
		move.w	d4,x_pos(a0)
		move.w	y_pos(a2),y_pos(a0)
		bra.w	SolidObjectTop_1P
; ---------------------------------------------------------------------------

	.notClimbing:
		btst	d6,status(a0)
		beq.s	.return
		bclr	#Status_OnObj,status(a1)
		bset	#Status_InAir,status(a1)
		bclr	d6,status(a0)

	.return:
		rts
; ---------------------------------------------------------------------------

Obj_EncoreRespawn:						; Liliam: Encore mode - respawn partner character
		clr.w	(Tails_CPU_flight_timer).w
		move.w	#$120,d0
		tst.w	(H_scroll_frame_offset).w
		bne.s	.setPosition
		tst.w	(Debug_placement_mode).w
		bne.s	.setPosition
		tst.b	(Boss_flag).w
		beq.s	.usePlayerPosition
		cmpi.w	#$B01,(Current_zone_and_act).w
		beq.s	.setPosition

	.usePlayerPosition:
		lea	(Pos_table).w,a1
		move.w	(Pos_table_index).w,d0
		subq.b	#8,d0
		move.w	(a1,d0.w),d0
		sub.w	(Camera_X_pos).w,d0
		addi.w	#$80,d0

	.setPosition:
		move.w	d0,x_pos(a0)
		move.w	#$175,y_pos(a0)
		move.w	#-$800,y_vel(a0)
		move.b	(Player_1+status).w,d0
		andi.b	#1,d0
		move.b	d0,render_flags(a0)
		move.b	d0,status(a0)
		clr.b	mapping_frame(a0)
		move.w	#$80,priority(a0)
		move.b	#2,anim(a0)
		move.b	#5,anim_frame_timer(a0)
		move.b	#7,x_radius(a0)
		move.b	#$E,y_radius(a0)
		move.l	#Obj_EncoreRespawn_Main,(a0)
		move.l	#Map_EncoreRespawn_Amy,mappings(a0)
		cmpi.b	#3,character_id(a0)
		beq.s	.setTailsHeight
		move.l	#Map_EncoreRespawn,mappings(a0)
		cmpi.b	#1,character_id(a0)
		bne.s	.checkGravity
		move.l	#Obj_EncoreRespawn_Tails,(a0)
		move.l	#Map_EncoreRespawn_Tails,mappings(a0)
		move.b	d0,(Tails_tails+render_flags).w
		move.w	art_tile(a0),d0
		addi.w	#ArtTile_EncoreTail-ArtTile_Player_2,d0
		move.w	d0,(Tails_tails+art_tile).w

	.setTailsHeight:
		move.b	#TailsRollHeight,y_radius(a0)

	.checkGravity:
		tst.b	(Reverse_gravity_flag).w
		beq.s	Obj_EncoreRespawn_Animate
		bset	#1,render_flags(a0)
		subi.w	#$12A,y_pos(a0)

Obj_EncoreRespawn_Animate:
		moveq	#0,d0
		move.b	character_id(a0),d0
		lsl.w	#3,d0
		lea	DPLCPtr_EncoreRespawn(pc,d0.w),a1
		movea.l	(a1)+,a3
		movea.l	(a1)+,a2
		move.b	mapping_frame(a0),d0
		add.w	d0,d0
		adda.w	(a2,d0.w),a2
		move.w	(a2)+,d5
		move.w	art_tile(a0),d4
		lsl.w	#5,d4
		moveq	#0,d3
		jsr	(loc_8504A).l

Obj_EncoreRespawn_Draw:
		bsr.w	Draw_Sprite
		move.w	(Camera_X_pos).w,$30(a0)
		move.w	(Camera_Y_pos).w,$32(a0)
		btst	#1,render_flags(a0)
		beq.w	MoveSprite
		bra.w	MoveSprite_ReverseGravity
; ---------------------------------------------------------------------------
DPLCPtr_EncoreRespawn:						; Liliam: Encore mode - respawn partner character
		dc.l ArtUnc_EncoreRespawn_Sonic
		dc.l DPLC_EncoreRespawn
		dc.l ArtUnc_EncoreRespawn_Tails
		dc.l DPLC_EncoreRespawn_Tails
		dc.l ArtUnc_EncoreRespawn_Knuckles
		dc.l DPLC_EncoreRespawn
		dc.l ArtUnc_EncoreRespawn_Amy
		dc.l DPLC_EncoreRespawn_Amy
		dc.l ArtUnc_EncoreRespawn_Mighty
		dc.l DPLC_EncoreRespawn
		dc.l ArtUnc_EncoreRespawn_Ray
		dc.l DPLC_EncoreRespawn
		dc.l ArtUnc_EncoreRespawn_MetalSonic
		dc.l DPLC_EncoreRespawn
; ---------------------------------------------------------------------------

Obj_EncoreRespawn_DrawTails:					; Liliam: Encore mode - respawn partner character
		move.l	a0,-(sp)
		lea	(Tails_tails).w,a0
		bsr.w	Draw_Sprite
		movea.l	(sp)+,a0
		jmp	(a2)
; ---------------------------------------------------------------------------

Obj_EncoreRespawn_Main:						; Liliam: Encore mode - respawn partner character
		subq.b	#1,anim_frame_timer(a0)
		bne.s	Obj_EncoreRespawn_Draw
		move.b	#5,anim_frame_timer(a0)
		addq.b	#1,mapping_frame(a0)
		cmpi.b	#8,mapping_frame(a0)
		bne.w	Obj_EncoreRespawn_Animate
		bra.s	Obj_EncoreRespawn_Release
; ---------------------------------------------------------------------------

Obj_EncoreRespawn_Tails:					; Liliam: Encore mode - respawn partner character
		lea	Obj_EncoreRespawn_Draw(pc),a2
		subq.b	#1,anim_frame_timer(a0)
		bne.s	Obj_EncoreRespawn_DrawTails
		lea	Obj_EncoreRespawn_Animate(pc),a2
		move.b	#5,anim_frame_timer(a0)
		addq.b	#1,mapping_frame(a0)
		cmpi.b	#8,mapping_frame(a0)
		bne.s	Obj_EncoreRespawn_DrawTails
		move.b	#$C4,(Tails_tails+render_flags).w
		move.w	#$100,(Tails_tails+priority).w
		move.w	art_tile(a0),d0
		addi.w	#ArtTile_TailsTail-ArtTile_Player_2,d0
		move.w	d0,(Tails_tails+art_tile).w

Obj_EncoreRespawn_Release:
		move.w	(Camera_X_pos).w,d0
		move.w	d0,d1
		subi.w	#$80,d1
		add.w	d1,x_pos(a0)
		sub.w	$30(a0),d0
		lsl.w	#8,d0
		add.w	d0,x_vel(a0)
		move.w	(Camera_Y_pos).w,d0
		move.w	d0,d1
		subi.w	#$80,d1
		add.w	d1,y_pos(a0)
		sub.w	$32(a0),d0
		lsl.w	#8,d0
		tst.b	(Reverse_gravity_flag).w
		beq.s	.checkWater
		neg.w	d0

	.checkWater:
		add.w	d0,y_vel(a0)
		tst.b	(Water_flag).w
		beq.s	.checkAutoSpin
		cmp.w	(Water_level).w,d1
		blt.s	.checkAutoSpin
		move.b	#1<<Status_Underwater,status(a0)

	.checkAutoSpin:
		lea	(Player_1).l,a1
		move.b	spin_dash_flag(a1),d0
		beq.s	.release
		btst	#Status_Roll,status(a1)
		beq.s	.release
		move.b	d0,spin_dash_flag(a0)
	if VariableRollHeight
		move.b	#$F,y_radius(a0)
		move.b	#9,x_radius(a0)
	else
		move.b	#7,x_radius(a0)
