		bmi.s	Render_Sprites_NextObj
		movea.l	mappings(a0),a1
		moveq	#0,d4
		btst	#5,d6		; is the static mappings flag set?
		bne.s	loc_1ADD8	; if it is, branch
		move.b	mapping_frame(a0),d4
		add.w	d4,d4
