Monitor_SetupEncoreRoulette:					; Liliam: Encore mode - item roulette monitor
		cmpi.b	#1,d0
		bne.s	Monitor_SetupDone
		moveq	#2,d0
		move.l	#Obj_Monitor_EncoreRoulette,(a0)
		tst.b	(Encore_available_chars).w
		beq.s	Monitor_SetupDone
		lea	(Dynamic_object_RAM).w,a1
		moveq	#((Dynamic_object_RAM_end-Dynamic_object_RAM)/object_size)-1,d1
		move.l	#Obj_Monitor_EncoreStock,d2

	.loop:
		cmp.l	(a1),d2
		beq.s	Monitor_SetupDone
		lea	next_object(a1),a1
		dbf	d1,.loop
		move.l	d2,(a0)

Monitor_SetupDone:
		move.b	d0,anim(a0)
		move.b	#-1,character_id(a0)
		rts
; ---------------------------------------------------------------------------

Monitor_RemoveHandler:						; Liliam: Knuckles route fixup
		move.l	#Obj_Monitor,(a0)
		bra.s	Obj_Monitor
; ---------------------------------------------------------------------------

Obj_Monitor_EncoreRoulette:					; Liliam: Encore mode - item roulette monitor
		cmpi.b	#4,routine(a0)
		beq.s	Monitor_RemoveHandler
		tst.b	mapping_frame(a0)
		bne.s	Obj_Monitor
		tst.b	anim_frame_timer(a0)
		bne.s	Obj_Monitor
		move.b	anim(a0),d0
		bne.s	.nextItem
		moveq	#3,d0

	.nextItem:
		addq.b	#1,d0
		cmpi.b	#$A,d0
		blo.s	.setItem
		moveq	#0,d0

	.setItem:
		move.b	d0,anim(a0)
		move.b	d0,prev_anim(a0)
		bra.s	Obj_Monitor
; ---------------------------------------------------------------------------

Obj_Monitor_EncoreStock:					; Liliam: Encore mode - character stock monitor
		cmpi.b	#4,routine(a0)
		beq.s	Monitor_RemoveHandler
		tst.b	mapping_frame(a0)
		bne.s	Obj_Monitor
		tst.b	anim_frame_timer(a0)
		bne.s	Obj_Monitor
		move.b	(Encore_available_chars).w,d2
		moveq	#0,d1
		move.b	character_id(a0),d1
		move.b	d1,d0

	.nextItem:
		addq.b	#1,d1
		cmpi.b	#7,d1
		blo.s	.checkAvailable
		moveq	#0,d1

	.checkAvailable:
		btst	d1,d2
		beq.s	.nextItem
		cmp.b	d1,d0
		beq.s	Obj_Monitor

		move.b	d1,character_id(a0)
		lsl.w	#7,d1
		addi.l	#ArtUnc_EncorePlayerIcons,d1
		move.w	#tiles_to_bytes(ArtTile_Monitors+$1C),d2
		moveq	#$40,d3
		jsr	(Add_To_DMA_Queue).l

Obj_Monitor:
		moveq	#0,d0
		move.b	routine(a0),d0
		move.w	Monitor_Index(pc,d0.w),d1
		jmp	Monitor_Index(pc,d1.w)
; ---------------------------------------------------------------------------
Monitor_Index:
		dc.w Obj_MonitorInit-Monitor_Index
		dc.w Obj_MonitorMain-Monitor_Index
		dc.w Obj_MonitorBreak-Monitor_Index
		dc.w Obj_MonitorAnimate-Monitor_Index
		dc.w loc_1D61A-Monitor_Index
; ---------------------------------------------------------------------------

Obj_MonitorInit:
		addq.b	#2,routine(a0)	; => Obj_MonitorMain
		move.b	#$F,y_radius(a0)
		move.b	#$F,x_radius(a0)
		move.l	#Map_Monitor,mappings(a0)
		move.w	#make_art_tile(ArtTile_Monitors,0,0),art_tile(a0)
		ori.b	#4,render_flags(a0)
		move.w	#$180,priority(a0)
		move.b	#$E,width_pixels(a0)
		move.b	#$10,height_pixels(a0)
		move.w	respawn_addr(a0),d0	; Get address in respawn table
		beq.s	.notbroken		; If it's zero, it isn't remembered
		movea.w	d0,a2			; Load address into a2
		btst	#0,(a2)			; Is this monitor broken?
		beq.s	.notbroken		; If not, branch
		move.b	#$B,mapping_frame(a0)	; Use 'broken monitor' frame
		move.l	#Sprite_OnScreen_Test,(a0)
		rts
; ---------------------------------------------------------------------------

	.notbroken:
		move.b	#$46,collision_flags(a0)
		bsr.w	Monitor_SetupAquaBarrier		; Liliam: bugfix - use safe colors for aqua barrier icon
;		move.b	subtype(a0),anim(a0)			;

Obj_MonitorMain:
		bsr.s	Monitor_Fall
		move.w	#$19,d1			; Monitor's width
		move.w	#$10,d2
		move.w	d2,d3
		addq.w	#1,d3
		move.w	x_pos(a0),d4
		lea	(Player_1).w,a1
		moveq	#p1_standing_bit,d6
		movem.l	d1-d4,-(sp)
		bsr.w	SolidObject_Monitor_SonicKnux
		movem.l	(sp)+,d1-d4
		lea	(Player_2).w,a1
		moveq	#p2_standing_bit,d6
		bsr.w	SolidObject_Monitor_Tails
		jsr	(Add_SpriteToCollisionResponseList).l
		lea	(Ani_Monitor).l,a1
		bsr.w	Animate_Sprite

loc_1D61A:
		tst.b	character_id(a0)			; Liliam: Encore mode - character stock monitor
		bmi.w	Sprite_OnScreen_Test			;

		bsr.w	Sprite_OnScreen_Test			; Liliam: Encore mode - special Robotnik icon for palette
		tst.l	(a0)					;
		bne.s	locret_1D66A				;
		lea	PLC_RobotnikLifeIcon(pc),a1		;
		jmp	(Load_PLC_Raw).l			;
;		bra.w	Sprite_OnScreen_Test			;
; ---------------------------------------------------------------------------

Obj_MonitorAnimate:
		addq.b	#2,routine(a0)				; Liliam: Knuckles route fixup
;		cmpi.b	#$B,mapping_frame(a0)			;
;		bne.s	.notbroken				;
;		move.l	#loc_1D61A,(a0)				;

