SolidObject_Monitor_Tails:
		btst	d6,status(a0)		; Is Tails standing on the monitor?
		bne.s	Monitor_ChkOverEdge	; If so, branch
		tst.w	(Competition_mode).w	; Are we in competition mode?
		beq.w	SolidObject_cont	; If not, branch
		bra.s	loc_1D69C				; Liliam: simplify roll anim selection
;		cmpi.b	#2,anim(a1)				;
;		bne.w	SolidObject_cont			;
;		rts						;
; End of function SolidObject_Monitor_Tails

; ---------------------------------------------------------------------------

Monitor_ChkOverEdge:
		move.w	d1,d2
		add.w	d2,d2
		btst	#Status_InAir,status(a1)	; Is the character in the air?
		bne.s	.notonmonitor		; If so, branch
		; Check if character is standing on
		move.w	x_pos(a1),d0
		sub.w	x_pos(a0),d0
		add.w	d1,d0
		bmi.s	.notonmonitor		; Branch, if character is behind the left edge of the monitor
		cmp.w	d2,d0
		blo.s	Monitor_CharStandOn	; Branch, if character is not beyond the right edge of the monitor

	.notonmonitor:
		; if the character isn't standing on the monitor
		bclr	#Status_OnObj,status(a1)	; Clear 'on object' bit
		bset	#Status_InAir,status(a1)	; Set 'in air' bit
		bclr	d6,status(a0)			; Clear 'standing on' bit for the current character
		moveq	#0,d4
		rts
; ---------------------------------------------------------------------------

Monitor_CharStandOn:
		move.w	d4,d2
		bsr.w	MvSonicOnPtfm
		moveq	#0,d4
		rts
; ---------------------------------------------------------------------------

Obj_MonitorBreak:
		move.b	status(a0),d0
;		andi.b	#standing_mask|pushing_mask,d0		; Liliam: bugfix - stop uncurling next to monitors
;		beq.s	Obj_MonitorSpawnIcon			;
;		move.b	d0,d1					;
;		andi.b	#p1_standing|p1_pushing,d1		;
		btst	#p1_standing_bit,d0			;
		beq.s	.checkpush				;
		bset	#Status_InAir,(Player_1+status).w	;
		bclr	#Status_OnObj,(Player_1+status).w	;

	.checkpush:
		btst	#p1_pushing_bit,d0			;
		beq.s	.notmainchar
;		andi.b	#$D7,(Player_1+status).w		;
;		ori.b	#1<<Status_InAir,(Player_1+status).w	;
		bclr	#Status_Push,(Player_1+status).w	;

	.notmainchar:
;		andi.b	#p2_standing|p2_pushing,d0		;
		btst	#p2_standing_bit,d0			;
		beq.s	.checkpush2				;
		bset	#Status_InAir,(Player_2+status).w	;
		bclr	#Status_OnObj,(Player_2+status).w	;

	.checkpush2:
		btst	#p2_pushing_bit,d0			;
		beq.s	Obj_MonitorSpawnIcon
;		andi.b	#$D7,(Player_2+status).w		;
;		ori.b	#1<<Status_InAir,(Player_2+status).w	;
		bclr	#Status_Push,(Player_2+status).w	;

Obj_MonitorSpawnIcon:
		andi.b	#3,status(a0)
		move.b	#0,collision_flags(a0)
		bsr.w	AllocateObjectAfterCurrent
		bne.s	.skipiconcreation
		move.l	#Obj_MonitorContents,(a1)
		move.w	x_pos(a0),x_pos(a1)		; Set icon's position
		move.w	y_pos(a0),y_pos(a1)
		move.b	anim(a0),anim(a1)
		move.b	render_flags(a0),render_flags(a1)
		move.b	status(a0),status(a1)
		move.b	character_id(a0),character_id(a1)	; Liliam: Encore mode - character stock monitor
		move.w	parent(a0),parent(a1)

	.skipiconcreation:
		bsr.w	AllocateObjectAfterCurrent
		bne.s	.skipexplosioncreation
		move.l	#Obj_Explosion,(a1)
		addq.b	#2,routine(a1)			; => loc_1E61A
		move.w	x_pos(a0),x_pos(a1)		; Set explosion's position
		move.w	y_pos(a0),y_pos(a1)
		movea.w	parent(a0),a2				; Liliam: extra skills - hammer attack
		jsr	(EnemyDefeat_PickSound).l		;

	.skipexplosioncreation:
		move.w	respawn_addr(a0),d0		; Get address in respawn table
		beq.s	.notremembered			; If it's zero, it isn't remembered
		movea.w	d0,a2				; Load address into a2
		bset	#0,(a2)				; Mark monitor as destroyed

	.notremembered:
		move.b	#$A,anim(a0)			; Display 'broken' animation
		addq.b	#2,routine(a0)				; Liliam: Knuckles route fixup
;		move.l	#Obj_MonitorAnimate,(a0)		;
		bra.w	Draw_Sprite
; ---------------------------------------------------------------------------

