Encore_RotateStocks:						; Liliam: Encore mode - change character item
		lea	(Encore_stocks).w,a4
		move.b	(a4)+,d2
		subq.b	#2,d2
		bmi.s	locret_1DB2C
		moveq	#0,d0
		move.b	(a4),d0

	.loop:
		move.b	1(a4),(a4)+
		subq.b	#1,d2
		bpl.s	.loop
		lea	(Player_prev_frame).w,a2
		lea	(P1_character).w,a3
		lea	(Max_speed).w,a5
		lea	(Dust).w,a6
		cmpa.w	#Player_1,a1
		beq.s	.swapPlayers
		lea	(Player_prev_frame_P2).w,a2
		lea	(P2_character).w,a3
		lea	(Max_speed_P2).w,a5
		lea	(Dust_P2).w,a6

	.swapPlayers:
		move.b	(a3),-1(a4)
		move.b	d0,(a3)
		move.b	#1,(Update_HUD_life_count).w
		move.b	#$A,(Encore_HUD_stocks_scroll+1).w
		cmpa.w	(Tails_tails+$30).w,a1
		bne.s	.checkBoostMode
		move.l	#Delete_Current_Sprite,(Tails_tails).w

	.checkBoostMode:
		cmpa.w	(Tails_tails_2P+parent2).w,a1
		bne.s	.checkTails
		move.l	#Delete_Current_Sprite,(Tails_tails_2P).w
		btst	#Status_SpeedShoes,status_secondary(a1)
		bne.s	.checkTails
		move.w	#$600,Max_speed-Max_speed(a5)
		move.w	#$C,Acceleration-Max_speed(a5)

	.checkTails:
		moveq	#$13,d1
		moveq	#$E,d2
		clr.w	$38(a6)
		cmpi.b	#1,d0
		bne.s	.checkAmy
		move.l	#Obj_Tails_Tail,(Tails_tails).w
		move.w	a1,(Tails_tails+$30).w
		bra.s	.setTailsHeight
; ---------------------------------------------------------------------------

	.checkAmy:
		cmpi.b	#3,d0
		bne.s	.checkRolling
		btst	#Skill_AmyDoubleJump,(Skill_options).w
		beq.s	.setTailsHeight
		move.b	#1,$39(a6)

	.setTailsHeight:
		moveq	#$F,d1
		moveq	#TailsRollHeight,d2
		move.b	#5-TailsRollHeightDiff,$38(a6)

	.checkRolling:
		moveq	#0,d3
		move.b	y_radius(a1),d3
		cmp.b	default_y_radius(a1),d3
		bne.s	.checkInAir
		move.b	d1,d2

	.checkInAir:
		btst	#Status_InAir,status(a1)
		bne.s	.setHeight
		sub.w	d2,d3
		add.w	d3,y_pos(a1)

	.setHeight:
		move.b	d1,default_y_radius(a1)
		move.b	d2,y_radius(a1)
		tst.b	double_jump_flag(a1)
		beq.s	.setPlayerPtrs
		clr.b	double_jump_flag(a1)
		clr.b	jumping(a1)
		move.b	#2,anim(a1)

	.setPlayerPtrs:
		move.b	#-1,(a2)
		move.b	#-1,prev_anim(a1)
		move.b	d0,character_id(a1)
		lsl.w	#2,d0
		lea	(Player_ObjectPtrs).l,a2
		move.l	(a2,d0.w),(a1)
		movea.l	a1,a2
		bsr.w	AllocateObjectAfterCurrent
		bne.s	.playSFX
		move.l	#loc_1E626,(a1)
		move.w	art_tile(a2),art_tile(a1)
		move.w	x_pos(a2),x_pos(a1)
		move.w	y_pos(a2),y_pos(a1)

	.playSFX:
		moveq	#signextendB(sfx_ChangeCharacter),d0
		jsr	(Play_SFX).l

