		move.w	d0,(Camera_X_pos).w
		move.w	d0,(Camera_X_pos_copy).w
		move.w	d0,(Camera_min_X_pos).w
		move.w	d0,(Camera_max_X_pos).w	; Set all the camera/start positions
		move.w	d0,d1
		lea	(Player_1).w,a1
		bsr.s	sub_50318
		move.w	d1,d0
		lea	(Player_2).w,a1

