loc_50324:
		addi.w	#$18,d0
		cmp.w	x_pos(a1),d0
		bls.s	loc_5033A
		move.w	d0,x_pos(a1)			; Make sure Sonic stays on-screen
		move.w	#$400,ground_vel(a1)		; Set his running velocity to $400 if the left of screen is hit
