HCZ1_Deform:
		move.w	(Camera_Y_pos_copy).w,d0		; Get the BG camera Y position
		subi.w	#$610,d0				; Get the difference between that and the water line equilibrium point
		move.w	d0,d1
		asr.w	#2,d0
		move.w	d0,d2
		addi.w	#$190,d0
		move.w	d0,(Camera_Y_pos_BG_copy).w		; The effective BG Y is negative when the BG is above the water line, positive when otherwise
		sub.w	d1,d2					; The difference between the effective BG Y and the actual BG Y difference is what's used to calculate how the water line should be drawn
		move.w	d2,(Events_bg+$10).w
		move.w	(Camera_X_pos_copy).w,d0		; Get the camera BG X
		swap	d0
		clr.w	d0
		tst.w	d2
		beq.w	loc_50DDA		; If equilibrium point, branch
		move.l	d0,d1
		move.l	d0,d3			; Set up deformation scroll value
		asr.l	#7,d3
		moveq	#$30-1,d4
		cmpi.w	#-$60,d2
		bgt.s	loc_50D52
		lea	(HScroll_table+$01A).w,a1	; If background is high enough that water line doesn't have to be messed with, just apply the standard formation to it

loc_50D3A:
		swap	d1
		move.w	d1,(a1)+
		swap	d1
		sub.l	d3,d1
		swap	d1
		move.w	d1,(a1)+
		swap	d1
		sub.l	d3,d1
		dbf	d4,loc_50D3A
		bra.w	loc_50DDA		; Then finish it up
; ---------------------------------------------------------------------------

loc_50D52:
		lea	(HScroll_table+$19A).w,a1

loc_50D56:
		swap	d1				; If background camera is lower, then apply water line deformation backwards
		move.w	d1,-(a1)
		swap	d1
		sub.l	d3,d1
		swap	d1
		move.w	d1,-(a1)
		swap	d1
		sub.l	d3,d1
		dbf	d4,loc_50D56
		cmpi.w	#$60,d2
		bge.s	loc_50DDA		; If background camera is low enough that water line doesn't need to be messed with, then end it.
		lea	(HScroll_table+$0DA).w,a1	; Otherwise, the fun begins
		lea	(a1),a5
		lea	(HCZ_WaterlineScroll_Data).l,a6
		move.w	d2,d1
		bmi.s	loc_50DAE
		move.w	d1,d3			; If waterline is displayed below water level
		neg.w	d3
		addi.w	#$60,d3
		lsl.w	#5,d3
		adda.w	d3,a6
		add.w	d3,d3
		adda.w	d3,a6			; Set up area of water line scroll data to use based on position
		subq.w	#1,d1
		moveq	#0,d3
		lsr.w	#1,d1
		bcc.s	loc_50DA0

loc_50D98:
		move.b	(a6)+,d3
		add.w	d3,d3
		move.w	(a5,d3.w),(a1)+

loc_50DA0:
		move.b	(a6)+,d3
		add.w	d3,d3
		move.w	(a5,d3.w),(a1)+	; Apply scroll data
		dbf	d1,loc_50D98
		bra.s	loc_50DDA
; ---------------------------------------------------------------------------

loc_50DAE:
		move.w	d1,d3			; If waterline is displayed above water level
		addi.w	#$60,d3
		lsl.w	#5,d3
		adda.w	d3,a6
		add.w	d3,d3
		adda.w	d3,a6			; Set up area of water line scroll data to use based on position
		neg.w	d1
		subq.w	#1,d1
		moveq	#0,d3
		lsr.w	#1,d1
		bcc.s	loc_50DCE

loc_50DC6:
		move.b	(a6)+,d3
		add.w	d3,d3
		move.w	(a5,d3.w),-(a1)

loc_50DCE:
		move.b	(a6)+,d3
		add.w	d3,d3
		move.w	(a5,d3.w),-(a1)	; Apply scroll data
		dbf	d1,loc_50DC6

loc_50DDA:
		move.l	d0,d1			; Get BG X again
		asr.l	#2,d0
		asr.l	#5,d1
		lea	(HScroll_table).w,a1
		swap	d0
		move.w	d0,(a1)
		move.w	d0,$18(a1)
		move.w	d0,d3
		swap	d0
		sub.l	d1,d0
		swap	d0
		move.w	d0,2(a1)
		move.w	d0,$16(a1)
		swap	d0
		sub.l	d1,d0
		swap	d0
		move.w	d0,4(a1)
		move.w	d0,$14(a1)
		swap	d0
		sub.l	d1,d0
		swap	d0
		move.w	d0,6(a1)
		move.w	d0,$12(a1)
		swap	d0
		sub.l	d1,d0
		swap	d0
		move.w	d0,8(a1)
		move.w	d0,$10(a1)
		swap	d0
		sub.l	d1,d0
		swap	d0
		move.w	d0,$A(a1)
		move.w	d0,$E(a1)
		swap	d0
		sub.l	d1,d0
		swap	d0
		move.w	d0,$C(a1)
		move.w	d0,$19A(a1)
		move.w	d0,d4
		tst.w	d2
		bpl.s	loc_50E68
		lea	(HScroll_table+$0DA).w,a1	; Water line above water
		moveq	#$30-1,d0

loc_50E4E:
		move.w	d4,(a1)+
		move.w	d4,(a1)+
		dbf	d0,loc_50E4E
		moveq	#$60-1,d0
		add.w	d2,d0
		bmi.s	locret_50E86
		lea	(HScroll_table+$01A).w,a1

loc_50E60:
		move.w	d3,(a1)+
		dbf	d0,loc_50E60
		bra.s	locret_50E86
; ---------------------------------------------------------------------------

loc_50E68:
		lea	(HScroll_table+$01A).w,a1	; Water line below water
		moveq	#$30-1,d0

loc_50E6E:
		move.w	d3,(a1)+
		move.w	d3,(a1)+
		dbf	d0,loc_50E6E
		moveq	#$60-1,d0
		sub.w	d2,d0
		bmi.s	locret_50E86
