		jsr	Clear_Switches(pc)
		jsr	(Load_Level).l
		jsr	(Animate_Init).l		; Liliam: bugfix - act 2 scroll garbage
		jsr	(LoadSolids).l
		jsr	(CheckLevelForWater).l			; Level stuff, etc.
		cmpi.w	#3,(Player_mode).w
		beq.s	loc_51EC0
