		lea	(Object_RAM).w,a0
		move.w	#41,$2E(a0)
		move.w	#-$20,$28(a0)
		clr.w	mainspr_childsprites(a0)

	.done:
		moveq	#signextendB(sfx_Starpost),d0
		jmp	(Play_SFX).l
