; ---------------------------------------------------------------------------

OptionsScreen_Scroll:						; Liliam: options menu
		addq.w	#1,d0
		lsr.w	#1,d0
		lea	OptionsScreen_ScrollOffsets-1(pc,d0.w),a1
		moveq	#10-1,d1
		moveq	#32-1,d2

	.loop1:
		moveq	#0,d0
		tst.b	(a1)+
		beq.s	.loop2
		move.l	$28(a0),d0

	.loop2:
		add.l	d0,(a2)+
		dbf	d2,.loop2
		moveq	#16-1,d2
		dbf	d1,.loop1
		subq.w	#1,$2E(a0)
		bne.s	.return
		tst.l	$28(a0)
		bmi.s	.return
		move.w	#1,mainspr_childsprites(a0)

	.return:
		rts
