		bne.w	MuseumChecklist
		move	#$2700,sr
		bsr.w	Museum_Controls
		move	#$2300,sr
		btst	#button_B,(Ctrl_1_pressed).w
		beq.s	Museum_MainLoop
		clr.w	(Museum_entry).w
