Obj_MuseumSprites:						; Liliam: museum
		addq.w	#2,$24(a0)
		addq.w	#4,$26(a0)
		addq.w	#4,$28(a0)
		addq.w	#6,$2A(a0)
		addq.w	#8,$2C(a0)
		addq.w	#8,$2E(a0)
		subq.b	#1,$1C(a0)
		beq.s	.done
		cmpi.b	#$10,$1C(a0)
		bhi.s	MuseumSprites_ApplySpeeds
		subi.w	#$10,$48(a0)
		bra.s	MuseumSprites_ApplySpeeds
; ---------------------------------------------------------------------------

	.done:
		move.l	#Obj_MuseumSprites_DrawOption,(a0)
		bra.s	Obj_MuseumSprites_Main
