CNZMinibossTop_CheckHitBase:
		movea.w	parent3(a0),a1
		lea	CNZMiniboss_BaseRange(pc),a2		; Two hit boxes. First is the slightly wider base
		move.w	x_pos(a1),d2
		add.w	(a2)+,d2
		cmp.w	d2,d0
		blo.s	loc_6E23C
		add.w	(a2)+,d2
		cmp.w	d2,d0
		bhs.s	loc_6E23C
		move.w	y_pos(a1),d2
		add.w	(a2)+,d2
		cmp.w	d2,d1
		blo.s	loc_6E23C
		add.w	(a2)+,d2
		cmp.w	d2,d1
		blo.s	loc_6E270

loc_6E23C:
		lea	CNZMiniboss_CoilRange(pc),a2		; Then it's the coil, different ranges depending on open or close state
		btst	#6,$38(a1)
		beq.s	loc_6E24C
		lea	CNZMiniboss_CoilOpenRange(pc),a2

loc_6E24C:
		move.w	x_pos(a1),d2
		add.w	(a2)+,d2
		cmp.w	d2,d0
		blo.s	loc_6E26C
		add.w	(a2)+,d2
		cmp.w	d2,d0
		bhs.s	loc_6E26C
		move.w	y_pos(a1),d2
		add.w	(a2)+,d2
		cmp.w	d2,d1
		blo.s	loc_6E26C
		add.w	(a2)+,d2
		cmp.w	d2,d1
		blo.s	loc_6E270

loc_6E26C:
		moveq	#0,d2
		rts
