		cmpi.b	#2,d0
		bne.s	loc_83808
		moveq	#$B,d0

loc_83808:
		move.b	d0,mapping_frame(a0)				; Liliam: simplify end sign selection
		rts
; ---------------------------------------------------------------------------

loc_838FA:
