Obj_WaitForParent:
		movea.w	parent3(a0),a1
		btst	#5,$38(a1)
		bne.w	loc_83EC2
		tst.l	(a1)
		beq.w	loc_83EC2
		move.w	x_pos(a1),x_pos(a0)
		move.w	y_pos(a1),y_pos(a0)
		jmp	Obj_Wait(pc)
