		dc.w  -$300, -$200
		dc.w   $300, -$200
		dc.w  -$200, -$200
		dc.w      0, -$200
		dc.w  -$400, -$300
		dc.w   $400, -$300
		dc.w   $300, -$300
		dc.w  -$400, -$300
		dc.w   $400, -$300
		dc.w  -$200, -$200
		dc.w   $200, -$200
;		dc.w      0, -$100				; Liliam: bugfix - set correct velocity for emeralds
