;		dc.w  -$200, -$700				;
;		dc.w  -$280, -$700				;
;		dc.w  -$300, -$700				;
		dc.w      0, -$100
		dc.w  -$100, -$100
		dc.w   $100, -$100
		dc.w  -$200, -$100
		dc.w   $200, -$100
		dc.w  -$200, -$200
		dc.w   $200, -$200
