Chase_Object:
		move.w	d0,d2			; d0 = Maximum speed
		neg.w	d2
		move.w	d1,d3			; d1 = acceleration
		move.w	x_pos(a0),d4
		cmp.w	x_pos(a1),d4
		seq	d5
		beq.s	loc_8545E
		bcs.s	loc_8544C
		neg.w	d1

loc_8544C:
		move.w	x_vel(a0),d4
		add.w	d1,d4
		cmp.w	d2,d4
		blt.s	loc_8545E
		cmp.w	d0,d4
		bgt.s	loc_8545E
		move.w	d4,x_vel(a0)

loc_8545E:
		move.w	y_pos(a0),d4
		cmp.w	y_pos(a1),d4
		beq.s	loc_85480
		bcs.s	loc_8546C
		neg.w	d3

loc_8546C:
		move.w	y_vel(a0),d4
		add.w	d3,d4
		cmp.w	d2,d4
		blt.s	locret_8547E
		cmp.w	d0,d4
		bgt.s	locret_8547E
		move.w	d4,y_vel(a0)

locret_8547E:
		rts
; ---------------------------------------------------------------------------

loc_85480:
		tst.b	d5
		beq.s	locret_8547E
		clr.w	x_vel(a0)
		clr.w	y_vel(a0)
		rts
; End of function Chase_Object


