Make_CutsceneSkipObj:						; Liliam: cutscene skip object
		tst.w	(Debug_placement_mode).w
		bne.s	CutsceneSkip_Return
		jsr	(AllocateObject).l
		bne.s	CutsceneSkip_Return
		clr.b	(Update_HUD_timer).w
		move.l	#Obj_CutsceneSkip_CheckDelete,(a1)
		move.l	#Map_CutsceneSkip,mappings(a1)
		move.w	#make_art_tile(ArtTile_Ring+$1E,0,1),art_tile(a1)
		move.w	#$14F,y_pos(a1)
		move.w	(Current_zone_and_act).w,d0
		beq.s	CutsceneSkip_LoadArt
		ror.b	#1,d0
		lsr.w	#6,d0
		move.b	d0,routine(a1)
		cmpi.b	#($1700>>6)+2,d0
		bne.s	.notHPZSS
		move.l	#Obj_CutsceneSkip_HPZSSResults,(a1)
		tst.w	(Ending_running_flag).w
		beq.s	CutsceneSkip_LoadArt
		move.l	#Obj_CutsceneSkip_HPZSSEntry,(a1)
		move.b	#($D00>>6),routine(a1)
		move.w	a1,(HPZ_special_stage_completed).w
		bra.s	CutsceneSkip_LoadArt
; ---------------------------------------------------------------------------

	.notHPZSS:
		tst.w	(Ending_running_flag).w
		bne.s	CutsceneSkip_InitEnding
		tst.b	(Level_started_flag).w
		beq.s	CutsceneSkip_LoadArt
		move.l	#Obj_CutsceneSkip_ScrollHUD,(a1)

CutsceneSkip_Return:
		rts
; ---------------------------------------------------------------------------

CutsceneSkip_InitEnding:					; Liliam: cutscene skip object
		move.l	#Obj_CutsceneSkip_Ending,(a1)
		move.w	#1,(Game_paused).w

CutsceneSkip_LoadArt:
		move.l	#ArtUnc_CutsceneSkip,d1
		move.w	#tiles_to_bytes(ArtTile_Ring+$1E),d2
		move.w	#$110,d3
		jmp	(Add_To_DMA_Queue).l
; ---------------------------------------------------------------------------

Obj_CutsceneSkip_ScrollHUD:					; Liliam: cutscene skip object
		subi.b	#$10,(Level_started_flag).w
		cmpi.b	#$89,(Level_started_flag).w
		bhi.s	CutsceneSkip_Return
		clr.b	(Level_started_flag).w
		bsr.s	CutsceneSkip_LoadArt
		move.l	#Obj_CutsceneSkip_CheckDelete,(a0)

Obj_CutsceneSkip_CheckDelete:
		tst.w	(Debug_placement_mode).w
		bne.s	CutsceneSkip_Delete
		tst.b	(Update_HUD_timer).w
		beq.s	Obj_CutsceneSkip_Main

CutsceneSkip_Delete:
		st	(Update_HUD_score).w
		ori.b	#$80,(Update_HUD_timer).w
		tst.b	(Level_started_flag).w
		bne.w	Go_Delete_Sprite
		move.b	#$91,(Level_started_flag).w
		bra.w	Go_Delete_Sprite
; ---------------------------------------------------------------------------

Obj_CutsceneSkip_Ending:					; Liliam: cutscene skip - ending
		tst.w	(Ending_running_flag).w
		bmi.w	Obj_CutsceneSkip_Main
		bra.w	Go_Delete_Sprite
; ---------------------------------------------------------------------------

Obj_CutsceneSkip_HPZSSEntry:					; Liliam: cutscene skip - HPZ SS entry
		tst.w	(Debug_placement_mode).w
		beq.s	Obj_CutsceneSkip_Main
		clr.w	(HPZ_special_stage_completed).w
		jmp	(Delete_Current_Sprite).l
; ---------------------------------------------------------------------------

Obj_CutsceneSkip_HPZSSResults:					; Liliam: cutscene skip - HPZ SS results
		cmpi.b	#$A,(Dynamic_object_RAM+(object_size*29)+routine).w
		beq.w	Go_Delete_Sprite

Obj_CutsceneSkip_Main:
		move.b	(Reverse_gravity_flag).w,d0
		bclr	#button_start,(Ctrl_1_pressed).w
		bne.s	.checkScroll
		move.w	$2E(a0),d1
		bne.s	.checkDisplay
		rts
; ---------------------------------------------------------------------------

	.checkScroll:
		move.w	$2E(a0),d1
		bne.s	.checkDisplay
		move.w	#67*8,d1
		move.w	d1,$2E(a0)
		move.b	d0,subtype(a0)

	.checkDisplay:
		subi.w	#60*8,d1
		bmi.s	.checkActivate
		addi.w	#$19C,d1
		move.w	d1,x_pos(a0)

	.checkActivate:
		subq.w	#8,$2E(a0)
		btst	#button_A,(Ctrl_1_pressed).w
		bne.s	.skipCutscene
		cmp.b	subtype(a0),d0
		bne.s	.skipCutscene
		move.b	d0,subtype(a0)
		jmp	(Draw_Sprite).l
; ---------------------------------------------------------------------------

	.skipCutscene:
		moveq	#0,d0
		stopZ80
		move.b	d0,(Z80_RAM+zSFXNumber0).l
		move.b	d0,(Z80_RAM+zSFXNumber1).l
		move.b	#cmd_StopSFX,(Z80_RAM+zMusicNumber).l
		startZ80
		move.b	routine(a0),d0
		move.w	CutsceneSkip_Index(pc,d0.w),d0
		jmp	CutsceneSkip_Index(pc,d0.w)
; ---------------------------------------------------------------------------
