		dc.w CutsceneSkip_Ending-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_DEZ2-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_HPZSSEntry-CutsceneSkip_Index
		dc.w CutsceneSkip_Ending-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_ALZ-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_DPZ-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
		dc.w CutsceneSkip_Delete-CutsceneSkip_Index
