; =============== S U B R O U T I N E =======================================


DebugMode:
		moveq	#0,d0
		move.b	(Debug_placement_routine).w,d0
		move.w	DebugMode_Index(pc,d0.w),d1
		jmp	DebugMode_Index(pc,d1.w)
; End of function DebugMode

; ---------------------------------------------------------------------------
DebugMode_Index:
		dc.w loc_92A20-DebugMode_Index
		dc.w loc_92AB0-DebugMode_Index
; ---------------------------------------------------------------------------

loc_92A20:
		addq.b	#2,(Debug_placement_routine).w
		move.l	mappings(a0),(Debug_saved_mappings).w
		cmpi.b	#State_NoControl,routine(a0)
		bhs.s	loc_92A38
		move.w	art_tile(a0),(Debug_saved_art_tile).w

loc_92A38:
		move.w	(Screen_Y_wrap_value).w,d0
		and.w	d0,(Player_1+y_pos).w
		and.w	d0,(Camera_Y_pos).w
		clr.b	(Scroll_lock).w
		clr.b	(WindTunnel_flag).w				; Liliam: Encore mode - pick RAM variables by SST
;		clr.w	(WindTunnel_flag).w				;
		clr.b	jumping(a0)					; Liliam: HUD - barrier HUD
		clr.b	routine(a0)				; Liliam: debug - resume processing sprites
		bset	#Status_InAir,status(a0)		; Liliam: debug - set airborne flag for camera
		move.b	status(a0),d0				; Liliam: debug - properly orient debug sprite
		andi.b	#1,d0					;
		andi.b	#$FC,render_flags(a0)			;
		or.b	d0,render_flags(a0)			;
		tst.b	(Reverse_gravity_flag).w		;
		beq.s	loc_92A4C				;
		bset	#1,render_flags(a0)			;

loc_92A4C:
		movea.l	a0,a1					; Liliam: bugfix - clear flags
		jsr	(Player_ClearSpinDash).l		;
		bclr	#Status_Underwater,status(a0)
		beq.s	loc_92A6E
;		movea.l	a0,a1					;
		jsr	(Player_ResetAirTimer).l
;		move.w	#$600,(Max_speed).w			; Liliam: bugfix - player speeds fix
;		move.w	#$C,(Acceleration).w			;
;		move.w	#$80,(Deceleration).w			;

loc_92A6E:
		move.b	#0,mapping_frame(a0)
		move.b	#0,anim(a0)
		moveq	#0,d0
		move.w	(Current_zone_and_act).w,d0
		ror.b	#1,d0
		lsr.w	#6,d0
		andi.w	#$7E,d0
		lea	(DebugOffs).l,a2
		adda.w	(a2,d0.w),a2
		move.w	(a2)+,d6
		cmp.b	(Debug_object).w,d6
		bhi.s	loc_92AA0
		move.b	#0,(Debug_object).w

loc_92AA0:
		bsr.w	sub_92C88
		move.b	#$C,(Debug_camera_delay).w
		move.b	#1,(Debug_camera_speed).w

loc_92AB0:
		moveq	#0,d0
		move.w	(Current_zone_and_act).w,d0
		ror.b	#1,d0
		lsr.w	#6,d0
		andi.w	#$7E,d0
		lea	(DebugOffs).l,a2
		adda.w	(a2,d0.w),a2
		move.w	(a2)+,d6
		bsr.w	sub_92AD4
		jmp	(Draw_Sprite).l

; =============== S U B R O U T I N E =======================================


sub_92AD4:
		moveq	#0,d4
		move.w	#1,d1
		move.b	(Ctrl_1_pressed).w,d4
		andi.w	#button_up_mask|button_down_mask|button_left_mask|button_right_mask,d4
		bne.s	loc_92B16
		move.b	(Ctrl_1_held).w,d0
		andi.w	#button_up_mask|button_down_mask|button_left_mask|button_right_mask,d0
		bne.s	loc_92AFE
		move.b	#$C,(Debug_camera_delay).w
		move.b	#$F,(Debug_camera_speed).w
		bra.w	loc_92B7A
; ---------------------------------------------------------------------------

loc_92AFE:
		subq.b	#1,(Debug_camera_delay).w
		bne.s	loc_92B1A
		move.b	#1,(Debug_camera_delay).w
		addq.b	#1,(Debug_camera_speed).w
		bne.s	loc_92B16
		move.b	#255,(Debug_camera_speed).w

loc_92B16:
		move.b	(Ctrl_1_held).w,d4

loc_92B1A:
		moveq	#0,d1
		move.b	(Debug_camera_speed).w,d1
		addq.w	#1,d1
		swap	d1
		asr.l	#4,d1
		move.l	y_pos(a0),d2
		move.l	x_pos(a0),d3
		btst	#button_up,d4
		beq.s	loc_92B44
		sub.l	d1,d2
		moveq	#0,d0
		move.w	(Camera_min_Y_pos).w,d0
		cmpi.w	#-$100,d0				; Liliam: debug - properly apply camera boundaries
		beq.s	loc_92B44				;
		swap	d0
		cmp.l	d0,d2
		bge.s	loc_92B44
		move.l	d0,d2

loc_92B44:
		move.l	(Screen_Y_wrap_value).w,d0		; Liliam: debug - properly apply camera boundaries
		move.w	#-1,d0					;
		and.l	d0,d2					;
		btst	#button_down,d4
